import type { QuizQuestion } from '../../types/quiz';

const questions: QuizQuestion[] = [
  { q: 'Kardiyoloji hangi organla ilgilenir?', a: ['Böbrek', 'Kalp', 'Akciğer', 'Beyin'], c: 1, e: 'Kardiyoloji, kalp ve damar sistemi hastalıklarını inceler. "Kardio" Yunanca kalp anlamına gelir.' },
  { q: 'Nöroloji hangi sistemle ilgilenir?', a: ['Sindirim', 'Dolaşım', 'Sinir', 'Endokrin'], c: 2, e: 'Nöroloji, beyin, omurilik ve sinirlerden oluşan sinir sistemini inceler. Alzheimer, epilepsi ve inme nöroloji alanındadır.' },
  { q: 'Onkoloji neyin bilimidir?', a: ['Kemik hastalıkları', 'Kanser hastalıkları', 'Deri hastalıkları', 'Göz hastalıkları'], c: 1, e: 'Onkoloji, kanserin tanı ve tedavisini inceler. "Onkos" Yunanca tümör demektir. Kanser dünyada en yaygın ölüm nedenlerinden biridir.' },
  { q: 'Oftalmoloji hangi organı inceler?', a: ['Kulak', 'Dil', 'Göz', 'Burun'], c: 2, e: 'Oftalmoloji göz hastalıklarıyla ilgilenir. "Ophthalmos" Yunanca göz demektir. Göz doktoru muayene, gözlük reçetesi ve ameliyat yapar.' },
  { q: 'Ortopedi neyle ilgilenir?', a: ['Kas-iskelet sistemi', 'Sinir sistemi', 'Dolaşım sistemi', 'Bağışıklık sistemi'], c: 0, e: 'Ortopedi, kemik, eklem, kas ve bağları kapsar. Kırıklar, omurga sorunları ve diz problemleri ortopedi alanındadır.' },
  { q: 'Kan basıncının normal değeri kaçtır?', a: ['80/60 mmHg', '100/70 mmHg', '120/80 mmHg', '140/90 mmHg'], c: 2, e: '120/80 mmHg normal tansiyondur. 140/90 ve üzeri hipertansiyon (yüksek tansiyon) olarak kabul edilir.' },
  { q: 'Normal vücut ısısı kaç derecedir?', a: ['35°C', '36–37°C', '38°C', '39°C'], c: 1, e: 'Normal vücut sıcaklığı 36-37°C arasındadır. 37.5°C üzeri ateş sayılır; 38°C\'nin üzeri yüksek ateştir.' },
  { q: 'Diyabet hangi hormonun eksikliğiyle ilgilidir?', a: ['Adrenalin', 'İnsülin', 'Kortizol', 'Tiroksin'], c: 1, e: 'Tip 1 diyabette pankreas yeterli insülin üretemez; Tip 2\'de ise vücut insüline dirençlidir. İnsülin kan şekerini düzenler.' },
  { q: 'İnsülin hangi organ tarafından üretilir?', a: ['Karaciğer', 'Böbrek', 'Pankreas', 'Dalak'], c: 2, e: 'İnsülin, pankreasın Langerhans adacıklarındaki beta hücreleri tarafından üretilir. Kan şekerini düşürme işlevi görür.' },
  { q: 'Hemoglobin ne işe yarar?', a: ['Sindirimi kolaylaştırır', 'Kanda oksijen taşır', 'Yağ depolar', 'Enfeksiyonla savaşır'], c: 1, e: 'Hemoglobin, kırmızı kan hücrelerindeki demir içeren bir proteindir. Akciğerden aldığı oksijeni dokulara taşır.' },
  { q: '"Hipertansiyon" ne demektir?', a: ['Düşük tansiyon', 'Yüksek tansiyon', 'Düzensiz tansiyon', 'Normal tansiyon'], c: 1, e: 'Hipertansiyon yüksek kan basıncı demektir. "Sessiz katil" olarak da bilinir çünkü uzun süre belirti vermeyebilir.' },
  { q: '"Hipoglisemi" ne demektir?', a: ['Yüksek kan şekeri', 'Düşük kan şekeri', 'Yüksek kolesterol', 'Düşük kan basıncı'], c: 1, e: '"Hipo" = düşük, "glisemi" = kan şekeri. Hipoglisemi kan şekerinin 70 mg/dL\'nin altına düşmesi durumudur; baş dönmesi ve titreme yapabilir.' },
  { q: 'EKG (Elektrokardiyogram) neyi ölçer?', a: ['Beyin aktivitesini', 'Kalp aktivitesini', 'Kasların gücünü', 'Kan şekerini'], c: 1, e: 'EKG, kalbin elektriksel aktivitesini kaydeden bir testtir. Kalp ritim bozuklukları, kalp krizi ve diğer kalp sorunlarını gösterir.' },
  { q: '"Apandisit" hangi organın iltihabıdır?', a: ['Mide', 'Pankreas', 'Apandiks', 'Ince bağırsak'], c: 2, e: 'Apandiks, kalın bağırsağın başına tutunmuş küçük bir uzantıdır. İltihaplanırsa apandisit oluşur ve acil ameliyat gerektirir.' },
  { q: '"Pnömoni" hangi organın enfeksiyonudur?', a: ['Böbrek', 'Karaciğer', 'Akciğer', 'Mide'], c: 2, e: 'Pnömoni, akciğerlerin bakteri, virüs veya mantar enfeksiyonudur. Özellikle yaşlılar ve bağışıklığı zayıflar için tehlikelidir.' },
  { q: 'Antibiyotikler hangi tür enfeksiyonlara karşı etkilidir?', a: ['Viral', 'Bakteriyel', 'Fungal', 'Parazitik'], c: 1, e: 'Antibiyotikler yalnızca bakteriyel enfeksiyonlara karşı etkilidir. Grip ve soğuk algınlığı viral olduğu için antibiyotik işe yaramaz.' },
  { q: 'Karaciğerin temel işlevi nedir?', a: ['Sinir iletimi', 'Kan üretimi', 'Toksinleri süzmek ve detoks', 'Oksijen taşımak'], c: 2, e: 'Karaciğer 500\'den fazla işlevi olan dev bir fabrikadır. Toksinleri süzer, safra üretir, glikozu depolar ve proteinleri sentezler.' },
  { q: '"Sinüzit" neyin iltihabıdır?', a: ['Gırtlak', 'Burun sinüsleri', 'Kulak zarı', 'Dil'], c: 1, e: 'Sinüzit, alın, yanak ve burun çevresindeki hava boşluklarının (sinüslerin) iltihabıdır. Baş ağrısı ve tıkanıklık belirtileri gösterir.' },
  { q: '"Osteoporoz" nedir?', a: ['Kemik yoğunluğunun azalması', 'Kas erimesi', 'Eklem iltihabı', 'Sinir hasarı'], c: 0, e: 'Osteoporoz kemik yoğunluğunun azalmasıyla kemiklerin kırılgan hale gelmesidir. Menopoz sonrası kadınlarda daha sık görülür.' },
  { q: '"Alzheimer" hangi organı etkiler?', a: ['Kalp', 'Böbrek', 'Beyin', 'Karaciğer'], c: 2, e: 'Alzheimer, beynin yavaş yavaş tahrip olduğu bir demans türüdür. Bellek kaybı ve bilişsel gerilemeyle kendini gösterir.' },
  { q: 'Evrensel kan donörünün grubu hangisidir?', a: ['A Rh+', 'B Rh-', 'O Rh-', 'AB Rh+'], c: 2, e: 'O Rh- kan grubu herkese verilebilir çünkü yüzeyinde A, B veya Rh antijenlerini taşımaz. Acil kanamalarda hayat kurtarır.' },
  { q: 'Evrensel alıcının kan grubu hangisidir?', a: ['O Rh-', 'A Rh+', 'B Rh-', 'AB Rh+'], c: 3, e: 'AB Rh+ kan grubu sahipleri herkesten kan alabilir çünkü vücutları tüm antijenleri tanır ve reddetmez.' },
  { q: '"Kemoterapisi" ne için uygulanır?', a: ['Diyabet tedavisi', 'Kanser tedavisi', 'Kemik kırıklarında', 'Alerji tedavisi'], c: 1, e: 'Kemoterapi, hızlı bölünen kanser hücrelerini yok etmek için kullanılan ilaç tedavisidir. Maalesef sağlıklı hücreleri de etkileyebilir.' },
  { q: '"Diyaliz" hangi organın görevini üstlenir?', a: ['Karaciğer', 'Kalp', 'Böbrek', 'Akciğer'], c: 2, e: 'Diyaliz, böbrekler yeterince çalışamadığında kanı yapay olarak filtreleyen bir tedavi yöntemidir.' },
  // ── Ek Tıbbi Terimler Soruları ───────────────────────────────────
  { q: '"Tachycardia" ne anlama gelir?', a: ['Yavaş kalp atışı', 'Hızlı kalp atışı', 'Düzensiz kalp ritmi', 'Kalp durması'], c: 1, e: 'Taşikardi, kalbin dakikada 100\'den fazla atması durumudur. Bradikardi ise kalbin yavaş atması (60 altı) anlamına gelir.' },
  { q: '"İnme" (Stroke) nedir?', a: ['Kalp krizi', 'Beyne kan akışının kesilmesi veya kanaması', 'Tansiyon düşmesi', 'Solunum yetmezliği'], c: 1, e: 'İnme, beyne kan akışının durması (iskemik) veya beyin kanaması (hemorajik) nedeniyle yaşanan tıbbi acildir.' },
  { q: '"Biopsi" ne için yapılır?', a: ['Kan testi', 'Doku örneği alarak laboratuvarda inceleme', 'Röntgen çekimi', 'Kalp ritmi ölçümü'], c: 1, e: 'Biyopsi, şüpheli dokudan örnek alarak kanser başta olmak üzere hastalıkları kesin teşhis etmek için yapılır.' },
  { q: '"Palyatif bakım" nedir?', a: ['Acil müdahale', 'İyileştirilemeyen hastalıklarda yaşam kalitesini artırma', 'Rehabilitasyon', 'Yoğun bakım'], c: 1, e: 'Palyatif bakım; tedavi edilemeyen hastalıklarda ağrı ve semptomları gidererek hastanın yaşam kalitesini iyileştirmeyi hedefler.' },
  { q: '"Homeostasis" nedir?', a: ['Kan pıhtılaşması', 'Vücudun iç dengesini koruma mekanizması', 'Sinir iletimi', 'Bağışıklık tepkisi'], c: 1, e: 'Homeostasis; vücut sıcaklığı, kan şekeri ve pH gibi iç parametrelerin dengeli tutulmasını sağlayan fizyolojik mekanizmadır.' },
  { q: '"Anoreksi" hastalığı neyle ilgilidir?', a: ['Aşırı yeme', 'Yemek yemeyi reddetme ve ciddi kilo kaybı', 'Hafıza kaybı', 'Kas erimesi'], c: 1, e: 'Anoreksiya nervoza, kişinin beden algısının bozulması nedeniyle yemekten kaçınması ve ciddi kilo kaybıyla seyreden yeme bozukluğudur.' },
  { q: '"Kolesterol" nedir?', a: ['Bir vitamin', 'Bir hormon', 'Hücre zarlarında bulunan yağ benzeri madde', 'Kan şekeri türü'], c: 2, e: 'Kolesterol, hücre zarı yapısı ve hormon üretimi için gereklidir; ancak fazlası damar tıkanıklığına yol açabilir.' },
  { q: '"Fibromiyalji" hangi sistemi etkiler?', a: ['Sindirim', 'Dolaşım', 'Kas-iskelet (yaygın ağrı)', 'Solunum'], c: 2, e: 'Fibromiyalji, vücudun birçok noktasında kronik yaygın ağrı, yorgunluk ve uyku bozuklukları ile karakterize bir sendromdur.' },
  { q: '"Sepsis" nedir?', a: ['Deri hastalığı', 'Enfeksiyona karşı aşırı ve tehlikeli bağışıklık tepkisi', 'Karaciğer hastalığı', 'Sinir iltihabı'], c: 1, e: 'Sepsis, bir enfeksiyona karşı vücudun kontrolden çıkan tepkisidir; organ yetmezliğine ve ölüme yol açabilir.' },
  { q: '"MRI" neden "X-Ray"den üstün kabul edilir?', a: ['Daha ucuz', 'Radyasyon kullanmaz ve yumuşak dokuları daha iyi gösterir', 'Daha hızlı', 'Daha küçük cihaz'], c: 1, e: 'MRI (Manyetik Rezonans Görüntüleme) radyasyon kullanmaz; manyetik alan ve radyo dalgaları kullanarak yumuşak dokuları detaylı gösterir.' },
  { q: '"Tromboz" nedir?', a: ['Damar genişlemesi', 'Damar içinde pıhtı oluşması', 'Kan incelmesi', 'Dolaşım hızlanması'], c: 1, e: 'Tromboz, bir damar içinde kan pıhtısı (tromb) oluşmasıdır. Tıkadığı damara göre kalp krizi veya inmeye neden olabilir.' },
  { q: '"Enfeksiyon" ile "İnflamasyon" arasındaki fark nedir?', a: ['İkisi aynı şeydir', 'Enfeksiyon mikrop kaynaklı, inflamasyon vücudun savunma tepkisidir', 'İnflamasyon mikrop kaynaklıdır', 'Enfeksiyon yalnızca virüs nedeniyledir'], c: 1, e: 'Enfeksiyon: bakteri/virüs gibi mikroorganizmaların vücuda girmesi. İnflamasyon: vücudun enfeksiyon veya yaralanmaya karşı verdiği kızarma-ağrı tepkisi.' },
  { q: '"İmmünoglobulin" nedir?', a: ['Bir hormon', 'Antikor (bağışıklık proteini)', 'Enzim', 'Vitamin'], c: 1, e: 'İmmünoglobulin (Ig), bağışıklık sistemi tarafından üretilen antikorlardır; yabancı maddelere karşı savaşır.' },
  { q: 'Hangi vitamin eksikliği "Skorbüt" hastalığına yol açar?', a: ['Vitamin A', 'Vitamin B12', 'Vitamin C', 'Vitamin D'], c: 2, e: 'C vitamini eksikliğinde skorbüt gelişir; diş eti kanaması, deri döküntüsü ve yorgunluk başlıca belirtilerdir. Limon bu hastalıktan kurtarıcıdır.' },
  { q: '"Anemi" (kansızlık) en çok hangi besinin eksikliğiyle ilişkilidir?', a: ['Kalsiyum', 'Demir', 'Magnezyum', 'Çinko'], c: 1, e: 'Demir eksikliği anemisi en yaygın anemi türüdür. Hemoglobin üretimi için demir şarttır; kırmızı et, ıspanak iyi kaynaklardır.' },
  { q: '"Psikosomatik" hastalık ne demektir?', a: ['Yalnızca zihinsel hastalık', 'Fiziksel belirtileri olan ama psikolojik kökenli hastalık', 'Kalıtsal hastalık', 'Bulaşıcı hastalık'], c: 1, e: 'Psikosomatik hastalıklarda stres ve psikolojik etkenler gerçek fiziksel semptomlara (mide ağrısı, baş ağrısı vb.) yol açar.' },
  { q: '"Laparoskopi" nedir?', a: ['Kan tahlili', 'Küçük kesilerle yapılan kapalı ameliyat yöntemi', 'Röntgen türü', 'İlaç tedavisi'], c: 1, e: 'Laparoskopi; karın bölgesine küçük kesiler açılarak kamera ve aletlerle yapılan minimal invaziv cerrahi yöntemdir.' },
  { q: '"Hipotermi" ne anlama gelir?', a: ['Yüksek ateş', 'Vücut sıcaklığının tehlikeli şekilde düşmesi', 'Kan basıncı yükselmesi', 'Kan şekeri düşmesi'], c: 1, e: 'Hipotermi; vücut sıcaklığının 35°C\'nin altına düşmesidir. Donma tehlikesinde oluşur; ağır vakalarda ölüme yol açabilir.' },
  { q: '"Endoskopi" hangi organları incelemek için kullanılır?', a: ['Kalp', 'Beyin', 'Sindirim sistemi (mide, bağırsak)', 'Akciğer'], c: 2, e: 'Endoskopi; ışıklı esnek bir tüpün ağız ya da maktattan sokularak yemek borusu, mide ve bağırsağın incelenmesidir.' },
  { q: '"Kortizol" nedir?', a: ['Cinsiyet hormonu', 'Stres hormonu', 'Büyüme hormonu', 'Uyku hormonu'], c: 1, e: 'Kortizol, böbreküstü bezinden salgılanan stres hormonudur. Tehlike anında savaş-kaç tepkisini tetikler.' },
  { q: '"Alerji" nasıl oluşur?', a: ['Virüs saldırısı', 'Bağışıklık sisteminin zararsız maddelere aşırı tepkisi', 'Bakteri enfeksiyonu', 'Vitamin eksikliği'], c: 1, e: 'Alerji; bağışıklık sisteminin polen, toz, besin gibi normalde zararsız maddeleri tehdit olarak algılayıp aşırı tepki vermesidir.' },
  { q: '"Kolon kanseri" taraması için hangi yöntem kullanılır?', a: ['MRI', 'Kolonoskopi', 'Röntgen', 'Ultrason'], c: 1, e: 'Kolonoskopi, kalın bağırsağın kamera ile incelenmesidir; kolon kanseri başta olmak üzere bağırsak hastalıklarını erken tespit eder.' },
  { q: '"Kan grubu" tespit edilmesinde temel araç nedir?', a: ['Ultrason', 'Kan tahlili', 'EKG', 'Biyopsi'], c: 1, e: 'Kan grubu, kan tahlili ile yüzey antijenlerine (A, B, AB, O) ve Rh faktörüne bakılarak belirlenir.' },
  { q: '"Plazma" nedir?', a: ['Kırmızı kan hücreleri', 'Beyaz kan hücreleri', 'Kanın sıvı kısmı', 'Trombositler'], c: 2, e: 'Plazma, kanın yaklaşık %55\'ini oluşturan sarımsı sıvı bileşendir; içinde proteinler, hormonlar ve besinler taşınır.' },
  { q: '"Profilaksi" ne demektir?', a: ['Hastalık tedavisi', 'Hastalık teşhisi', 'Hastalıktan korunmak için önlem alma', 'Ameliyat sonrası bakım'], c: 2, e: 'Profilaksi; hastalığı önlemek amacıyla önceden alınan tedbirler veya uygulanan ilaç tedavisidir.' },
  // ── Ek Tıbbi Terimler ─────────────────────────────────────────────
  { q: '"Aritmia" nedir?', a: ['Kalp durması', 'Kalp ritim bozukluğu', 'Düşük tansiyon', 'Kalp kapağı hastalığı'], c: 1, e: 'Aritmia; kalbin çok hızlı, çok yavaş veya düzensiz atması durumudur. Çeşitlerine göre tehlikesizden hayatı tehdit edene kadar değişir.' },
  { q: '"Akut" ve "Kronik" hastalık arasındaki fark nedir?', a: ['İkisi aynıdır', 'Akut ani/kısa süreli, kronik uzun süreli/süreğen hastalıktır', 'Kronik daha tehlikelidir', 'Akut tedavi edilemez'], c: 1, e: 'Akut: ani başlayıp kısa süren. Kronik: yavaş ilerleyen, uzun süre devam eden hastalık. Grip akut, diyabet kroniktir.' },
  { q: '"İntravenöz (IV)" ne anlama gelir?', a: ['Kas içi enjeksiyon', 'Damar içi uygulama', 'Deri altı enjeksiyon', 'Ağız yoluyla ilaç'], c: 1, e: 'IV uygulama; ilaç veya sıvıların doğrudan damar içine verilmesidir. En hızlı etki yoludur.' },
  { q: '"Metabolizma" nedir?', a: ['Sinir iletimi', 'Vücuttaki kimyasal reaksiyonların tümü', 'Kan dolaşımı', 'Sindirim süreci'], c: 1, e: 'Metabolizma; hücrelerde besinlerin enerjiye dönüştürülmesi ve yaşamsal fonksiyonların sürdürülmesi için gerçekleşen tüm kimyasal süreçlerdir.' },
  { q: '"Otoimmün hastalık" nedir?', a: ['Virüs kaynaklı', 'Bağışıklık sisteminin kendi dokularına saldırması', 'Genetik bozukluk', 'Enfeksiyona bağlı'], c: 1, e: 'Otoimmün hastalıklarda bağışıklık sistemi kendi sağlıklı dokularını yabancı sanarak saldırır. Romatoid artrit, lupus örnek gösterilebilir.' },
  { q: '"Fibrin" ne işe yarar?', a: ['Oksijen taşır', 'Kan pıhtısı oluşturmada görev alır', 'Sinir iletimini sağlar', 'Yağ depolar'], c: 1, e: 'Fibrin, yaralanma sonrası kan pıhtısının ağ yapısını oluşturan proteindir. Kanamanın durmasında kritik rol oynar.' },
  { q: '"Biyolojik ilaç" nedir?', a: ['Bitkisel ilaç', 'Canlı hücrelerden üretilen ilaç (biyoteknoloji)', 'Kimyasal sentez ilacı', 'Homeopatik ilaç'], c: 1, e: 'Biyolojikler; bakteri, maya veya memeli hücrelerinden üretilen karmaşık protein yapılı ilaçlardır. Kanser ve otoimmün hastalıklarda kullanılır.' },
  { q: '"Ventilasyon" tıpta ne anlama gelir?', a: ['Kan dolaşımı', 'Solunum (akciğerlere hava girip çıkması)', 'Böbrek fonksiyonu', 'Kalp debisi'], c: 1, e: 'Ventilasyon; akciğerlere havanın girip çıkması yani solunum sürecidir. Mekanik ventilasyon ise cihazla yapay solunum sağlamaktır.' },
  { q: '"Kemoterapi" hangi prensibiyle çalışır?', a: ['Tümörü dondurur', 'Hızlı bölünen hücreleri yok eder', 'Bağışıklık sistemini güçlendirir', 'Geni düzeltir'], c: 1, e: 'Kemoterapi ilaçları, hızlı bölünen hücreleri hedef alır. Ne var ki sağlıklı hızlı bölünen hücreler (saç, bağırsak) de etkilenebilir.' },
  { q: '"İmmünoterapi" nasıl çalışır?', a: ['Antiviral ilaçlar verir', 'Vücudun bağışıklık sistemini kansere karşı güçlendirir', 'Radyasyon kullanır', 'Hormon dengeler'], c: 1, e: 'İmmünoterapi; vücudun kendi bağışıklık sistemini aktive ederek kanser hücrelerini tanımasını ve yok etmesini sağlar.' },
  { q: '"Triyaj" nedir?', a: ['Ameliyat türü', 'Hastaların aciliyetine göre önceliklendirilmesi', 'İlaç dozaj hesabı', 'Kan tahlili yöntemi'], c: 1, e: 'Triyaj; özellikle afet ve toplu kazalarda hastaların aciliyet durumlarına göre tedavi önceliğinin belirlenmesidir.' },
  { q: '"Anamnez" nedir?', a: ['Fizik muayene', 'Hastanın tıbbi öyküsünün alınması', 'Kan testi', 'Görüntüleme yöntemi'], c: 1, e: 'Anamnez; doktorun tanı sürecinde hastanın şikayetlerini, tıbbi geçmişini ve aile öyküsünü sorgulamasıdır.' },
  { q: '"Prognoz" nedir?', a: ['Tanı koyma', 'Tedavi planı', 'Hastalığın tahmini seyri ve sonucu', 'İlaç reçetesi'], c: 2, e: 'Prognoz; bir hastalığın olası seyrine ilişkin tahmindir. "İyi prognoz" iyileşme beklentisinin yüksek olduğunu ifade eder.' },
  { q: 'Hangisi "doğuştan gelen" (konjenital) bir hastalıktır?', a: ['Grip', 'Kalp kapağı anomalisi', 'Kırık', 'Sinüzit'], c: 1, e: 'Konjenital hastalıklar doğumda mevcut olan bozukluklardır. Kalp defektleri ve Down sendromu örnek verilebilir.' },

  // ── YENİ SORULAR ──────────────────────────────────────────────────
  { q: 'Kalp atışları çok hızlanmasına ne denir?', a: ['Bradikardi', 'Taşikardi', 'Aritmi', 'Hipertansiyon'], c: 1, e: 'Taşikardi, dinlenme durumunda kalp atış hızının dakikada 100\'ün üzerine çıkmasıdır.', d: 1 },
  { q: 'Hangi kan grubu "evrensel verici" olarak bilinir?', a: ['A+', 'B-', 'O-', 'AB+'], c: 2, e: 'O Rh negatif (O-) kan grubu, tüm kan gruplarına verilebilir; bu yüzden "evrensel verici" olarak adlandırılır.', d: 1 },
  { q: 'Şeker hastalığının tıbbi adı nedir?', a: ['Hipertansiyon', 'Diyabet', 'Artrit', 'Astım'], c: 1, e: 'Diyabet (diabetes mellitus), pankreastan yeterli insülin salgılanmaması veya insüline direnç nedeniyle kan şekerinin yükselmesidir.', d: 1 },
  { q: '"MRI" nedir?', a: ['Röntgen türü', 'Manyetik rezonans görüntüleme', 'Kan testi', 'İdrar testi'], c: 1, e: 'MRI (Manyetik Rezonans Görüntüleme), radyasyon kullanmadan güçlü mıknatıslar ve radyo dalgalarıyla iç organları görüntüler.', d: 1 },
  { q: '"Antibiyotik" neye karşı etkilidir?', a: ['Virüslere', 'Bakterilere', 'Mantarlara', 'Alerjilere'], c: 1, e: 'Antibiyotikler bakterileri öldürür veya üremelerini engeller; virüslere karşı etkisizdirler.', d: 1 },
  { q: 'İnsan vücudunda kaç kemik bulunur?', a: ['106', '206', '306', '406'], c: 1, e: 'Yetişkin bir insanda 206 kemik bulunur; bebekler yaklaşık 270-300 kemiğe sahipken bunlar zamanla kaynaşır.', d: 1 },
  { q: 'Hangi organ insülin üretir?', a: ['Karaciğer', 'Böbrek', 'Pankreas', 'Dalak'], c: 2, e: 'Pankreasdaki beta hücreleri insülin üretir; insülin kan şekerini düzenleyerek hücrelerin glikozu almasını sağlar.', d: 1 },
  { q: '"Hipertansiyon" ne anlama gelir?', a: ['Düşük tansiyon', 'Yüksek tansiyon', 'Düzensiz kalp atışı', 'Düşük kan şekeri'], c: 1, e: 'Hipertansiyon (yüksek tansiyon), kan basıncının kronik olarak normal değerlerin (120/80 mmHg) üzerinde olmasıdır.', d: 1 },
  { q: '"Kolesterol" yüksekliği hangi organı riske atar?', a: ['Böbrekler', 'Kalp ve damarlar', 'Karaciğer', 'Akciğerler'], c: 1, e: 'Yüksek LDL kolesterol, damarlarda plak birikmesine (ateroskleroz) neden olarak kalp krizi ve felç riskini artırır.', d: 1 },
  { q: '"Refleks" nedir?', a: ['Bilinçli hareket', 'Beyne gerek kalmadan otomatik gerçekleşen sinir tepkisi', 'Kas gerilmesi', 'Hormonal tepki'], c: 1, e: 'Refleksler, uyarıya karşı beyin devreye girmeden omurilik üzerinden gerçekleşen hızlı ve otomatik tepkilerdir.', d: 2 },
  { q: '"Osteoporoz" hangi dokuyu etkiler?', a: ['Kaslar', 'Kemikler', 'Eklemler', 'Sinirler'], c: 1, e: 'Osteoporoz, kemik yoğunluğunun azalmasıyla kemiklerin kırılgan hale geldiği metabolik kemik hastalığıdır.', d: 2 },
  { q: '"CT" (Bilgisayarlı Tomografi) ile röntgen arasındaki fark nedir?', a: ['CT daha az radyasyon kullanır', 'CT kesitsel görüntüler üretir ve daha fazla detay verir', 'CT yalnızca eklemleri görüntüler', 'İkisi aynıdır'], c: 1, e: 'BT (CT), X-ışınlarını kullanarak vücudun kesitsel (dilim) görüntülerini oluşturur; normal röntgenden çok daha ayrıntılıdır.', d: 2 },
  { q: '"Alerji" nasıl oluşur?', a: ['Vitamin eksikliği', 'Bağışıklık sisteminin zararsız maddelere aşırı tepkisi', 'Bakteri enfeksiyonu', 'Sinir hasarı'], c: 1, e: 'Alerjide bağışıklık sistemi, normalde zararsız olan maddeleri (polen, fıstık) tehdit olarak algılayarak histamin salgılar.', d: 2 },
  { q: '"Otoimmün hastalık" ne demektir?', a: ['Bulaşıcı hastalık', 'Bağışıklık sisteminin kendi dokularına saldırması', 'Genetik hastalık', 'Besinsel eksiklik'], c: 1, e: 'Otoimmün hastalıklarda bağışıklık sistemi kendi vücut hücrelerini yabancı sanarak saldırır; MS, romatoid artrit, lupus örnek verilebilir.', d: 2 },
  { q: 'Hangi vitamin "sinir sistemi" için kritik öneme sahiptir?', a: ['Vitamin A', 'B12 vitamini', 'Vitamin C', 'Vitamin D'], c: 1, e: 'B12 vitamini; sinir kılıflarının (miyelin) sağlığı, kırmızı kan hücresi üretimi ve DNA sentezi için zorunludur.', d: 2 },
  { q: '"Sepsis" nedir?', a: ['Yara enfeksiyonu', 'Enfeksiyona karşı yaşamı tehdit eden aşırı sistemik tepki', 'Kıl dönmesi', 'Basit ateş'], c: 1, e: 'Sepsis, enfeksiyona karşı vücudun kontrolsüz sistemik tepkisidir; organ yetmezliğine yol açarak hayatı tehdit eder.', d: 2 },
  { q: '"Biyopsi" nedir?', a: ['Cerrahi ameliyat', 'Doku örneği alıp laboratuvarda inceleme', 'Kan testi', 'Görüntüleme yöntemi'], c: 1, e: 'Biyopsi, şüpheli dokudan örnek alınarak patoloji laboratuvarında kanser veya başka hastalık açısından incelenmesidir.', d: 2 },
  { q: '"Nabız" neyi ölçer?', a: ['Kan şekerini', 'Kalbin atış hızını', 'Kan basıncını', 'Oksijen satürasyonunu'], c: 1, e: 'Nabız, kalbin her atışında damarlardaki basınç dalgasını hissederek kalp atım hızını ölçer; normalde dakikada 60-100 atıştır.', d: 1 },
  { q: 'Akciğerleri örten zarın adı nedir?', a: ['Periton', 'Perikard', 'Plevra', 'Meninks'], c: 2, e: 'Plevra, akciğerleri ve göğüs boşluğunu örten çift katlı zarın adıdır. Plevrit bu zarın iltihaplanmasıdır.', d: 2 },
  { q: '"Genel anestezi" ile "lokal anestezi" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Genel anestezi bilinci kapatır, lokal yalnızca bölgeyi uyuşturur', 'Lokal daha tehlikelidir', 'Genel daha kısa etkilidir'], c: 1, e: 'Genel anestezi, tüm vücudu ve bilinci etkiler; lokal anestezi ise sadece belirli bir bölgeyi uyuşturarak hasta uyanık kalır.', d: 2 },
  { q: '"Stres hormonu" olarak bilinen hormon hangisidir?', a: ['İnsülin', 'Kortizol', 'Melatonin', 'Serotonin'], c: 1, e: 'Kortizol, böbrek üstü bezi tarafından stres durumunda salgılanan hormondur; kan şekerini ve bağışıklık tepkisini etkiler.', d: 2 },
  { q: '"Endoskopi" nedir?', a: ['Kan testi', 'Esnek bir kamerayla sindirim sistemi içini görüntüleme', 'Cerrahi kesim', 'MRI türü'], c: 1, e: 'Endoskopi, ağız ya da anüsten esnek bir kamera aleti geçirilerek mide, bağırsak gibi organların içinin görüntülenmesidir.', d: 2 },
  { q: '"Hepatit" hangi organı etkiler?', a: ['Böbrek', 'Karaciğer', 'Akciğer', 'Mide'], c: 1, e: 'Hepatit, karaciğerin iltihaplanmasıdır; A, B, C, D ve E tipleri vardır; bulaşma yolları ve tedavileri farklılık gösterir.', d: 1 },
  { q: '"Parkinson hastalığı" hangi sistemi etkiler?', a: ['Sindirim sistemi', 'Merkezi sinir sistemi (dopamin üretimi)', 'Böbrekler', 'Bağışıklık sistemi'], c: 1, e: 'Parkinson, beyindeki dopamin üreten hücrelerin ilerleyici kaybına bağlı hareket bozukluklarıyla seyreden nörolojik hastalıktır.', d: 2 },
  { q: '"Alzheimer" hangi süreçleri etkiler?', a: ['Yalnızca hafıza', 'Hafıza, düşünme ve davranış — ilerleyici demans', 'Yalnızca motor beceriler', 'Yalnızca konuşma'], c: 1, e: 'Alzheimer, beyin hücrelerinin ilerleyici kaybına bağlı hafıza, düşünme ve davranış bozukluklarına yol açan en yaygın demans türüdür.', d: 2 },
  { q: '"Hemofili" nedir?', a: ['Demir eksikliği', 'Kan pıhtılaşma faktörü eksikliğiyle aşırı kanama', 'Kırmızı kan hücresi eksikliği', 'Lösemi türü'], c: 1, e: 'Hemofili, pıhtılaşma faktörlerinin eksikliğiyle karakterize, yaralanmada aşırı kanamayla seyreden kalıtsal kanama bozukluğudur.', d: 3 },
  { q: '"KOAH" açılımı ve ne anlama gelir?', a: ['Kronik Obstrüktif Akciğer Hastalığı', 'Kronik Otoimmün Artrit Hastalığı', 'Kronik Organ Ağırlık Hastalığı', 'Kardiyak Obstrüksiyon'], c: 0, e: 'KOAH (Kronik Obstrüktif Akciğer Hastalığı), uzun süre sigara gibi tahriş edici maddelere maruz kalma sonucu gelişen ilerleyici solunum yolu tıkanıklığıdır.', d: 3 },
  { q: '"Kanser hücresi" normal hücreden nasıl ayrılır?', a: ['Daha küçüktür', 'Kontrolsüz çoğalır ve apoptozdan (hücre ölümü) kaçınır', 'Enerji üretmez', 'DNA taşımaz'], c: 1, e: 'Kanser hücreleri, normal büyüme sinyallerine yanıt vermez; kontrol dışı çoğalır ve programlı hücre ölümüne (apoptoz) direnir.', d: 3 },
  { q: '"Polifarmasi" (polypharmacy) ne anlama gelir?', a: ['Tek ilaç tedavisi', 'Hastanın beş veya daha fazla ilaç kullanması', 'Ağrı kesici bağımlılığı', 'Bitkisel ilaç kullanımı'], c: 1, e: 'Polifarmasi, genellikle yaşlı hastalarda birden fazla kronik hastalık nedeniyle beş ve üzeri ilaç kullanılmasıdır; ilaç etkileşimi riskini artırır.', d: 3 },
  { q: '"PCR testi" neyi saptar?', a: ['Kan grubunu', 'DNA/RNA bazlı patojenlerin varlığını (örn. COVID-19, tüberküloz)', 'Protein eksikliğini', 'Alerji türünü'], c: 1, e: 'Polimeraz Zincir Reaksiyonu (PCR) testi, küçük DNA/RNA parçalarını milyarlarca kez kopyalayarak virüs veya bakteri varlığını saptar.', d: 3 },
  { q: '"Hipertansiyon" hangi değerlerde tanılanır?', a: ['Sistolik 100/diyastolik 60 üzeri', 'Sistolik 140 mmHg ve/veya diyastolik 90 mmHg üzeri', 'Sistolik 120/diyastolik 70 üzeri', 'Yalnızca yaşlılarda tanılanır'], c: 1, e: 'Dünya Sağlık Örgütü\'ne göre ≥140/90 mmHg kan basıncı hipertansiyon (yüksek tansiyon) olarak tanımlanır; kronik hipertansiyon kalp, böbrek ve beyin hasarına yol açabilir.', d: 2 },
  { q: '"Kolesterol" yüksekliğinde hangi lifler önerilir?', a: ['Hayvansal lifler', 'Çözünür bitkisel lifler (yulaf, baklagil, elma)', 'Rafine tahıllar', 'Et ürünleri'], c: 1, e: 'Çözünür lifler (yulaf, fasulye, elma, armut) bağırsakta safra asitlerini bağlayarak LDL kolesterolün düşmesine katkı sağlar.', d: 2 },
  { q: '"İnsülin direnci" nedir?', a: ['İnsülin eksikliği', 'Vücudun normal insüline yeterli tepki vermemesi; hücreler glikozu verimli alamaz', 'Aşırı insülin üretimi', 'İnsülinin böbrekte süzülmesi'], c: 1, e: 'İnsülin direncinde hücreler insüline duyarsızlaşır; pankreas daha fazla insülin üretmek zorunda kalır. Tedavi edilmezse tip 2 diyabete zemin hazırlar.', d: 2 },
  { q: '"Grip" ile "soğuk algınlığı" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Grip ani başlayan yüksek ateş, kas ağrısı ve yorgunlukla gelir; soğuk algınlığı daha hafif seyreder', 'Soğuk algınlığı daha tehlikelidir', 'Grip antibiyotikle tedavi edilir'], c: 1, e: 'Grip (influenza); ani başlayan yüksek ateş, yaygın kas ağrısı ve şiddetli yorgunlukla seyreder. Soğuk algınlığı daha hafif, yavaş başlangıçlı ve genellikle burun-boğaz semptomlarına yoğunlaşır.', d: 1 },
  { q: '"Romatoid artrit" hangi sistemi etkiler?', a: ['Yalnızca yaşlılarda görülür', 'Bağışıklık sisteminin eklem zarlarına saldırısıyla seyreden otoimmün hastalık', 'Yalnızca kemikleri etkiler', 'Yalnızca kalçayı etkiler'], c: 1, e: 'Romatoid artrit; bağışıklık sisteminin eklem zarını (sinovyum) hedef aldığı kronik inflamatuvar otoimmün bir hastalıktır. Genç erişkinlerde de görülebilir.', d: 2 },
  { q: '"Anemi" nedir ve en yaygın nedeni nedir?', a: ['Kan basıncının düşmesi', 'Kanda hemoglobin/kırmızı kan hücresi yetersizliği; en yaygın nedeni demir eksikliği', 'Yalnızca beslenme bozukluğu', 'Yüksek kolesterol'], c: 1, e: 'Anemi; kanda hemoglobin düzeyinin normalin altına düşmesiyle ortaya çıkar. Dünyada en yaygın anemi türü demir eksikliği anemidir; özellikle kadınlarda yaygındır.', d: 1 },
  { q: '"Tiroid bezi" hangi hormonları üretir ve işlevi nedir?', a: ['Yalnızca kortizol', 'T3 ve T4 hormonları; metabolizma hızını, ısı üretimini ve büyümeyi düzenler', 'Yalnızca insülin', 'Yalnızca büyüme hormonu'], c: 1, e: 'Tiroid; T3 (triiyodotironin) ve T4 (tiroksin) hormonlarını salgılar. Bu hormonlar vücudun enerji kullanımını, metabolizma hızını ve organ gelişimini düzenler.', d: 2 },
  { q: '"Kolon kanseri" için risk faktörleri nelerdir?', a: ['Yalnızca genetik', 'Kırmızı et, işlenmiş et, obezite, sigara, aile öyküsü ve yaş', 'Yalnızca yaşlılık', 'Yalnızca enfeksiyon'], c: 1, e: 'Kolon kanseri için başlıca risk faktörleri; aşırı kırmızı/işlenmiş et tüketimi, az lifli beslenme, obezite, sigara, aile öyküsü ve 50 yaş üzeri olmaktır. Kolonoskopi erken tanıda kritiktir.', d: 2 },
  { q: '"Meme kanseri" taramasında hangi yöntem kullanılır?', a: ['Yalnızca MRI', 'Mamografi; 40-50 yaş üzeri kadınlara düzenli önerilir', 'Yalnızca kan testi', 'Yalnızca muayene'], c: 1, e: 'Mamografi (meme röntgeni); erken evre meme kanserini saptamada en yaygın kullanılan tarama yöntemidir. Pek çok ülkede 40-50 yaş üzeri kadınlara düzenli mamografi önerilmektedir.', d: 2 },
  { q: '"Bağırsak florasının" sağlığa katkısı nedir?', a: ['Hiçbir katkısı yok', 'Sindirime yardım, bağışıklık modülasyonu ve bazı vitaminlerin sentezi', 'Yalnızca gaz üretimi', 'Yalnızca toksin üretimi'], c: 1, e: 'Bağırsak mikrobiyomu; sindirim, B ve K vitaminleri sentezi, bağışıklık sistemi düzenlenmesi ve patojenlere karşı bariyer işlevi gibi kritik rolleri üstlenir.', d: 2 },
  { q: '"Obezite" nasıl tanımlanır?', a: ['10 kg fazla kilolu olmak', 'Vücut Kitle İndeksi (VKİ) ≥30 kg/m²', 'Yalnızca beden görünümüne göre', 'Yalnızca çocuklarda'], c: 1, e: 'Obezite; kilonun (kg) boyun karesine (m²) oranlanmasıyla hesaplanan Vücut Kitle İndeksi\'nin 30\'un üzerine çıkmasıyla tanımlanır.', d: 1 },
  { q: '"Sağlıklı beslenme piramidinin" tabanında ne yer alır?', a: ['Et ve süt ürünleri', 'Tam tahıllar, sebze ve meyveler; bol su tüketimi', 'Şekerli gıdalar', 'Yağlı gıdalar'], c: 1, e: 'Sağlıklı beslenme piramidinin temeli; tam tahıllar, sebzeler, meyveler ve bol su tüketimidir. Bu gıdaların sık tüketilmesi önerilirken şeker ve doymuş yağlar en az tüketilmelidir.', d: 1 },
  { q: '"Akdeniz diyeti" hangi hastalıkları önlemeye yardımcı olur?', a: ['Yalnızca obeziteyi', 'Kardiyovasküler hastalıklar, diyabet ve bazı kanser türleri üzerinde koruyucu etki', 'Yalnızca osteoporozu', 'Hiçbir hastalığı'], c: 1, e: 'Akdeniz diyeti; zeytinyağı, balık, sebze, meyve ve tam tahıl ağırlıklı yapısıyla kalp-damar hastalıkları, tip 2 diyabet ve bazı kanser türlerine karşı koruyucu olduğu bilimsel çalışmalarla desteklenmektedir.', d: 2 },
  { q: '"Uyku apnesi" nedir ve riskleri nelerdir?', a: ['Normal bir durum', 'Uyku sırasında solunum durması; kalp hastalığı ve hipertansiyon riskini artırır', 'Yalnızca horlama', 'Yalnızca çocuklarda'], c: 1, e: 'Uyku apnesi; uyku sırasında üst solunum yolunun tıkanmasıyla birçok kez nefes durmasıdır. Tedavi edilmezse hipertansiyon, kalp ritim bozukluğu ve gündüz uyku hali riskini artırır.', d: 2 },
  { q: '"Stres" kronik olduğunda sağlığa etkileri nelerdir?', a: ['Yalnızca psikolojik', 'Bağışıklık baskılanması, kortizon yüksekliği, kalp hastalığı riski, uyku bozukluğu', 'Yalnızca yorgunluk', 'Hiçbir fiziksel etkisi yok'], c: 1, e: 'Kronik stres; kortizol hormonu yüksekliğine yol açar ve bağışıklık sistemi baskılanması, kardiyovasküler riskler, uyku sorunları ve ruh hali bozuklukları gibi geniş sağlık sorunlarına zemin hazırlar.', d: 2 },
  { q: '"Ameliyat sonrası komplikasyon" nedir?', a: ['Normal iyileşme süreci', 'Ameliyat sırasında ya da sonrasında ortaya çıkan istenmeyen tıbbi sorun', 'Yalnızca ağrı', 'Yalnızca kanamalar'], c: 1, e: 'Ameliyat komplikasyonları; enfeksiyon, kanama, derin ven trombozu, anestezi reaksiyonu gibi ameliyata bağlı olarak gelişen istenmeyen tıbbi durumları kapsar.', d: 2 },
  { q: '"Kemik erimesi" riskini azaltmak için ne yapılmalıdır?', a: ['Yalnızca ilaç kullanımı', 'Kalsiyum ve D vitamini alımı, düzenli egzersiz (ağırlık taşıyan) ve sigara-alkol kaçınma', 'Yalnızca süt içmek', 'Yalnızca güneşte oturma'], c: 1, e: 'Osteoporoz riskini azaltmak için; diyetle yeterli kalsiyum ve D vitamini alımı, düzenli ağırlık kaldırma egzersizleri, sigara ve aşırı alkol tüketiminden kaçınmak önemlidir.', d: 2 },
  { q: '"Kolesterol ilaçları" (statinler) nasıl çalışır?', a: ['Kolesterolü sindirimi bloke eder', 'Karaciğerde kolesterol üretimini (HMG-CoA redüktaz) inhibe ederek LDL\'yi düşürür', 'Kolesterolü salgıya yönlendirir', 'Yalnızca HDL\'yi artırır'], c: 1, e: 'Statinler; karaciğerde kolesterol sentezinin kilit enzimi olan HMG-CoA redüktazı bloke ederek LDL (kötü) kolesterolü düşürür ve kardiyovasküler riski azaltır.', d: 3 },
  { q: '"Kan şekeri kontrolü" neden kritiktir?', a: ['Yalnızca kilo için', 'Kronik yüksek kan şekeri damar, böbrek, göz ve sinir hasarına yol açar', 'Yalnızca enerji için', 'Yalnızca hormon için'], c: 1, e: 'Uzun süreli yüksek kan şekeri; böbrek yetmezliği (nefropati), görme kaybı (retinopati), sinir hasarı (nöropati) ve kardiyovasküler hastalıklar dahil ağır komplikasyonlara yol açar.', d: 2 },
  { q: '"Depresyon" nasıl tanımlanır?', a: ['Yalnızca üzüntü hissi', 'En az 2 hafta süren enerji kaybı, ilgi azalması, uyku ve iştah değişimleri ile çökkünlük', 'Yalnızca stres tepkisi', 'Yalnızca fiziksel bir belirti'], c: 1, e: 'Depresyon; en az iki hafta süren belirgin çökkünlük, enerji kaybı, uyku-iştah değişimleri, konsantrasyon güçlüğü ve zevk alamama ile tanımlanan ciddi bir ruh sağlığı bozukluğudur.', d: 2 },
  { q: '"Anksiyete bozukluğu" depresyondan nasıl ayrılır?', a: ['İkisi aynıdır', 'Anksiyetede aşırı endişe ve korku ön planda; depresyonda çökkünlük ve ilgi kaybı', 'Anksiyete daha hafiftir', 'Depresyon yalnızca yaşlılarda'], c: 1, e: 'Anksiyete bozukluğunda sürekli endişe, tedirginlik, çarpıntı ve kaçınma davranışı ön plandadır; depresyonda ise çökkünlük, ilgi kaybı ve enerji azalması belirgindir. İkisi birlikte de görülebilir.', d: 2 },
  { q: '"Alzheimer hastalığı" neden ilerler?', a: ['Yalnızca yaşlılık', 'Beyinde amiloid plakları ve tau proteini birikimi nöron kaybına yol açar', 'Enfeksiyon nedeniyle', 'Yalnızca genetik'], c: 1, e: 'Alzheimer\'ın tam nedeni bilinmemekle birlikte; amiloid-beta plaklarının ve tau proteininin birikmesi, nöronal bağlantıların bozulması ve beyin dokusunun yitmesi hastalığın ilerlemesinde kritik rol oynar.', d: 3 },
  { q: '"Kalp pili" (pacemaker) ne işe yarar?', a: ['Kan inceltir', 'Kalp ritim bozukluklarında kalbin düzenli atmasını sağlayan elektriksel cihaz', 'Tansiyon düşürür', 'Kolesterol ölçer'], c: 1, e: 'Kalp pili; ritim bozukluklarında (bradikardi, ileti bloğu) kalbe düzenli elektrik uyarısı göndererek normal atım hızını sağlayan implant edilen küçük elektronik cihazır.', d: 2 },
  { q: '"Stent" nedir?', a: ['Ameliyat aleti', 'Daralmış ya da tıkalı damara yerleştirilen açık tutan küçük metal ya da plastik boru', 'Tansiyon ölçer', 'Kan filtresi'], c: 1, e: 'Stent; koroner arterlerde ya da diğer daralmış damar ve kanallarda kan akışını sağlamak amacıyla kateter yardımıyla yerleştirilen küçük kafes benzeri metal tüptür.', d: 2 },
  { q: '"Biyopsiden" sonra ne beklenir?', a: ['Hemen sonuç verilir', 'Alınan doku patoloji laboratuvarında incelenerek gelen rapor tanıyı doğrular ya da ekarte eder', 'Yalnızca ameliyat sonrası yapılır', 'Hiçbir bekleme süresi yoktur'], c: 1, e: 'Biyopsi alınan doku örneği patoloji laboratuvarında incelenerek kanser, enflamasyon ya da başka patolojik süreçlerin varlığı araştırılır; sonuçlar genellikle birkaç gün ile birkaç haftada gelir.', d: 2 },
  { q: '"Radyoterapi" nasıl etki eder?', a: ['İlaç tedavisiyle aynı', 'Yüksek enerjili radyasyon tümör hücrelerinin DNA\'sını hasara uğratarak bölünmelerini engeller', 'Yalnızca cilt üzerinde etkili', 'Kanı temizler'], c: 1, e: 'Radyoterapi; yüksek enerjili X-ışınları ya da proton ışınlarını tümör bölgesine yönelterek kanser hücrelerinin DNA\'sını tahrip eder ve bölünmeyi durdutur. Normal dokuya etkiyi minimize etmek için hassas hedefleme yapılır.', d: 2 },
  { q: '"Türkiye\'de" hangi sağlık sigortası zorunludur?', a: ['Yalnızca özel sigortası', 'Genel Sağlık Sigortası (GSS); tüm vatandaşları kapsar', 'Yalnızca çalışanlara zorunludur', 'Zorunlu sigorta yoktur'], c: 1, e: 'Türkiye\'de 2012\'den itibaren Genel Sağlık Sigortası (GSS) zorunlu hale getirildi; katkı payı gelire göre belirlenir ve sigortasız vatandaş bırakılmamaya çalışılır.', d: 2 },
  { q: '"Türkiye\'de Sağlıkta Dönüşüm Programı" ne sağladı?', a: ['Yalnızca özel hastane', 'Aile hekimliği, tek ödeyici sistem ve hastanelere erişim kolaylığı', 'Yalnızca ilaç indirimi', 'Yalnızca İstanbul\'da'], c: 1, e: '2003\'ten itibaren uygulanan Sağlıkta Dönüşüm Programı; aile hekimliği sistemini, Genel Sağlık Sigortası\'nı ve tüm hastanelere eşit erişimi hayata geçirdi.', d: 2 },
  { q: '"Organ nakli" için en kritik koşul nedir?', a: ['Yalnızca para', 'Doku uyumu (HLA uyuşması) ve bağışçı onayı', 'Yalnızca yaş', 'Yalnızca hastane büyüklüğü'], c: 1, e: 'Organ naklinde en kritik etkenler; alıcı ile verici arasındaki HLA (insan lökosit antijeni) uyumu, kan grubu uyumu ve verici ya da ailesinin onayıdır.', d: 2 },
  { q: '"Türkiye\'de organ bağışı" nasıl yapılır?', a: ['Yalnızca ölümden önce noter ile', 'Nüfus müdürlüklerine, hastanelere veya organ bağışı kartı aracılığıyla bağış beyanında bulunulabilir', 'Yalnızca aile beyanıyla', 'Organ bağışı yasaktır'], c: 1, e: 'Türkiye\'de organ bağışı; nüfus müdürlükleri, hastaneler, çevrimiçi başvuru ve organ bağışı kartı aracılığıyla yapılabilir. Beyin ölümü sonrası ailenin onayı da belirleyici olmaktadır.', d: 2 },
  { q: '"Türkiye\'de "kanser tarama programları" nelerdir?', a: ['Program yoktur', 'Meme, rahim ağzı ve kolon kanserleri için ulusal tarama programları uygulanmaktadır', 'Yalnızca akciğer kanseri', 'Yalnızca özel hastanelerde'], c: 1, e: 'Türkiye\'de Sağlık Bakanlığı koordinasyonuyla meme kanseri (mamografi), rahim ağzı kanseri (smear) ve kolon kanseri (gaitada gizli kan) için ulusal tarama programları yürütülmektedir.', d: 2 },
  { q: '"Türkiye\'de birinci basamak sağlık hizmetleri" kim tarafından verilir?', a: ['Yalnızca devlet hastaneleri', 'Aile hekimlikleri; birinci basamak sağlık hizmetlerinin temel sunucusudur', 'Yalnızca özel klinikler', 'Yalnızca acil servisler'], c: 1, e: '2005\'ten itibaren yaygınlaşan aile hekimliği sistemiyle birlikte birinci basamak sağlık hizmetleri (koruyucu hekimlik, poliklinik, aşı, takip) aile hekimleri tarafından sunulmaktadır.', d: 2 },
  { q: '"Aşılanma" (bağışıklama) neden önemlidir?', a: ['Yalnızca çocuklar için', 'Hastalığa karşı bağışıklık oluşturarak hem bireyi hem toplumu korur; sürü bağışıklığı sağlar', 'Yalnızca seyahat için', 'Hiçbir faydası yoktur'], c: 1, e: 'Aşılanma; vücuda zayıflatılmış ya da ölü patojeni ya da onun bir parçasını tanıtarak bağışıklık sisteminin antikor üretmesini sağlar. Toplumda yüksek aşılanma oranı sürü bağışıklığı oluşturarak salgınları önler.', d: 1 },
  { q: '"COVID-19 pandemisi" tıbbi açıdan nasıl nitelendirilir?', a: ['Basit salgın', 'SARS-CoV-2 virüsünün neden olduğu, 2020\'de küresel pandemi ilan edilen solunum yolu hastalığı', 'Grip türü', 'Yalnızca yaşlıları etkiler'], c: 1, e: 'COVID-19; SARS-CoV-2 koronavirüsünün neden olduğu ve WHO tarafından Mart 2020\'de pandemi ilan edilen, solunum yolunu etkileyen enfeksiyöz hastalıktır.', d: 1 },
  { q: '"Türkiye\'de sağlık turizmi" nasıl gelişmektedir?', a: ['Gelişmemektedir', 'Diş, saç ekimi, plastik cerrahi ve göz ameliyatları başta olmak üzere hızla büyümektedir', 'Yalnızca kaplıca turizmi', 'Yalnızca Arap ülkelerinden'], c: 1, e: 'Türkiye, sağlık turizmi alanında diş tedavisi, saç ekimi, estetik cerrahi, göz ve ortopedi operasyonlarında Avrupa ve Orta Doğu\'dan büyük ilgi çeken önemli bir merkez haline gelmiştir.', d: 2 },
  { q: '"Fizyoterapi" ne zaman uygulanır?', a: ['Yalnızca kırıklarda', 'Kas-iskelet sistemi yaralanmalarında, ameliyat sonrasında ve nörolojik hastalıklarda hareket ve işlevi geri kazandırmak için', 'Yalnızca ağrı kesici olarak', 'Yalnızca yaşlılarda'], c: 1, e: 'Fizyoterapi; spor yaralanması, ameliyat sonrası rehabilitasyon, felç, sırt-bel ağrısı ve eklem hastalıklarında hareket kapasitesini ve işlevselliği yeniden kazandırmak amacıyla uygulanır.', d: 2 },
  { q: '"İnme" (felç) nedir ve belirtileri nelerdir?', a: ['Yalnızca baş ağrısı', 'Beyne kan akışının kesilmesiyle ani yüz sarkması, kol güçsüzlüğü, konuşma güçlüğü', 'Yalnızca yaşlılarda', 'Kalp hastalığı'], c: 1, e: 'İnme; beyine giden kanın pıhtı ya da kanama nedeniyle kesilmesiyle oluşur. FAST (Yüz-Kol-Konuşma-Zaman) testi erken tanıyı sağlar; her dakika beyin hücresi kaybı yaşanır.', d: 2 },
  { q: '"Kalp krizi" ile "kalp durması" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Kalp krizi: koroner tıkanıklık; kalp durması: elektriksel düzensizlikle kalbin aniden durması', 'Kalp durması daha hafif', 'Kalp krizi ani ölüm'], c: 1, e: 'Kalp krizi (miyokard enfarktüsü); koroner arteri tıkayan pıhtıyla kalp kasının zarar görmesidir. Kalp durması ise kalbin elektriksel sisteminin bozulmasıyla aniden pompalamayı kesmesidir.', d: 2 },
  { q: '"Diyabette" tip 1 ile tip 2 arasındaki fark nedir?', a: ['İkisi aynıdır', 'Tip 1: Bağışıklık sistemi beta hücrelerini yok eder, insülin üretilmez; Tip 2: insülin direnci gelişir', 'Tip 2 daha ciddidir', 'Tip 1 yalnızca yaşlılarda'], c: 1, e: 'Tip 1 diyabette bağışıklık sistemi pankreas beta hücrelerini tahrip eder; insülin salgılanmaz. Tip 2\'de ise hücreler insüline direnç geliştirir; yaşam tarzı, obezite ve genetik etkenlerle tetiklenir.', d: 2 },
  { q: '"Otoimmün" hastalıklar neden oluşur?', a: ['Yalnızca enfeksiyon', 'Bağışıklık sisteminin kendi vücut dokusunu yabancı sanarak saldırması', 'Vitamin eksikliği', 'Yalnızca genetik'], c: 1, e: 'Otoimmün hastalıklarda bağışıklık sistemi kendi hücrelerine saldırır; Tip 1 diyabet, romatoid artrit, lupus, MS ve tiroid hastalıkları bu gruba örnektir.', d: 2 },
  { q: '"Antibiyotik direnci" neden tehlikeli bir halk sağlığı sorunudur?', a: ['Yalnızca hastaneler için', 'Bakteriler ilaçlara direnç kazandığında tedavisiz enfeksiyonlar hayatı tehdit eder', 'Yalnızca yaşlılarda', 'Aşılarla önlenebilir'], c: 1, e: 'Antibiyotik direnci; özellikle gereksiz ve aşırı kullanımla hız kazanmakta, birçok enfeksiyonu tedavi edilemez hale getirmekte ve bu durum küresel halk sağlığı için ciddi tehdit oluşturmaktadır.', d: 2 },
  { q: '"Kanserde" erken tanı neden hayat kurtarır?', a: ['Hiçbir farkı yoktur', 'Erken evrede kanser sınırlı yayıldığından tedavi başarısı çok daha yüksek olur', 'Yalnızca bazı kanser türlerinde', 'Tanı maliyeti düşer'], c: 1, e: 'Kanserin erken evresinde tümör küçük ve sınırlıdır; cerrahi, radyoterapi ya da kemoterapi ile tam iyileşme olasılığı ileri evrelere göre çok daha yüksektir.', d: 1 },
  { q: '"Bağışıklık sistemi" nasıl güçlendirilebilir?', a: ['Yalnızca ilaçla', 'Dengeli beslenme, düzenli egzersiz, yeterli uyku, stres yönetimi ve sigara-alkol kaçınma', 'Yalnızca vitamin takviyesiyle', 'Yalnızca aşıyla'], c: 1, e: 'Bağışıklık sistemini desteklemek için; renkli sebze-meyve tüketimi, düzenli orta şiddette egzersiz, 7-9 saat uyku, stres yönetimi ve sigara-alkol gibi zararlı alışkanlıklardan kaçınmak önerilir.', d: 1 },
  { q: '"Palyatif bakım" nedir?', a: ['Yoğun bakım', 'İyileştirme hedefinden ziyade semptomları kontrol eden, yaşam kalitesini artıran destekleyici tıp yaklaşımı', 'Yalnızca ağrı kesici', 'Ameliyat öncesi bakım'], c: 1, e: 'Palyatif bakım; ileri evre hastalıklarda ağrı, bulantı gibi semptomları kontrol etmeyi, psikolojik destek sağlamayı ve kalan yaşam süresinin kalitesini artırmayı hedefleyen bütüncül tıp yaklaşımıdır.', d: 2 },
  { q: '"Telemedicine" (uzaktan tıp) ne anlama gelir?', a: ['Askeri tıp', 'Dijital teknoloji aracılığıyla doktor-hasta görüşmesi, tanı ve takibin uzaktan yapılması', 'Yalnızca acil', 'Yalnızca büyük şehirler'], c: 1, e: 'Telemedicine; video, sesli arama ve dijital platformlar aracılığıyla hasta ile sağlık profesyonelinin fiziksel temas gerektirmeden görüşmesini, tanı ve tedavi planlamasını sağlar. Pandemi döneminde hızla yaygınlaştı.', d: 2 },
  { q: '"Mental sağlık" fiziksel sağlıkla nasıl ilişkilidir?', a: ['İlişki yoktur', 'Ruh sağlığı bozuklukları bağışıklık sistemini, kalp sağlığını ve yaşam süresini olumsuz etkileyebilir', 'Yalnızca depresyon etkiler', 'Yalnızca ağır vakalarda'], c: 1, e: 'Kronik stres, anksiyete ve depresyon; bağışıklık baskılanması, hipertansiyon, kalp hastalığı ve kötü uyku kalitesi gibi fiziksel sağlık sorunlarıyla yakından ilişkilidir. "Bütüncül sağlık" anlayışı ikisini bir arada değerlendirir.', d: 2 },
  { q: '"Psikolojik ilk yardım" nedir?', a: ['İlaç tedavisi', 'Kriz, afet ya da travma sonrasında bireyi sakinleştirip güvenli ortam sağlayan insani destek yaklaşımı', 'Yalnızca psikologlar verir', 'Yalnızca savaş durumunda'], c: 1, e: 'Psikolojik İlk Yardım (PİY); afet, kaza ya da kriz sonrasında bireye güvenli ortam sağlamayı, temel ihtiyaçlarını karşılamayı ve sosyal desteğe bağlamayı amaçlayan kanıta dayalı insani yaklaşımdır.', d: 2 },
  { q: '"Diyetisyen" ile "beslenme uzmanı" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Diyetisyen yasal tescilli akademik unvan; beslenme uzmanı daha genel bir terim olabilir', 'Beslenme uzmanı daha üst', 'Diyetisyen yalnızca kilo için'], c: 1, e: 'Diyetisyen; lisans ya da lisansüstü eğitim alarak yetkili kurumlarca tescil edilen tıbbi beslenme uzmanıdır. "Beslenme danışmanı" ifadesi yasal düzenlemesiz kullanılabilmektedir.', d: 2 },
  { q: '"Probiyotik" gıdalar ne işe yarar?', a: ['Yalnızca bağışıklık', 'Bağırsak mikrobiyomunu destekleyen canlı yararlı bakteri içerirler; sindirim sağlığına katkı sağlar', 'Yalnızca bebekler için', 'Yalnızca egzersizde'], c: 1, e: 'Probiyotikler (yoğurt, kefir, turşu); bağırsak florasını destekleyen canlı mikroorganizmalar içerir. Sindirim rahatsızlıklarını azaltma, bağışıklık modülasyonu ve antibiyotik sonrası flora yenilenmesinde yardımcı olabilir.', d: 2 },
  { q: '"Menopoz" ne zaman ve nasıl yaşanır?', a: ['Yalnızca 70 yaşında', 'Genellikle 45-55 yaşları arasında adet döngüsünün kalıcı olarak sona ermesiyle', 'Yalnızca erkeklerde', 'Belirtisiz yaşanır'], c: 1, e: 'Menopoz; kadınlarda 12 ay adet görmeme ile tanımlanan, overlerın östrojen üretimini azaltmasından kaynaklanan doğal geçiş dönemidir. Sıcak basması, uyku bozukluğu ve kemik erimesi riski gibi belirtileri olabilir.', d: 2 },
  { q: '"Osteoporoz" için en etkin önlem nedir?', a: ['Yalnızca ilaç', 'Yeterli kalsiyum-D vitamini alımı, ağırlık taşıyan egzersiz ve sigara-alkolden kaçınma', 'Yalnızca yaşlılarda', 'Yalnızca kadınlarda'], c: 1, e: 'Osteoporozdan korunmak için; çocukluk ve gençlikten itibaren yeterli kalsiyum ve D vitamini alımı, düzenli yürüyüş gibi ağırlık taşıyan egzersizler ve sigara-aşırı alkol tüketiminden kaçınmak kritik önem taşır.', d: 2 },
  { q: '"Uyku hijyeni" ne anlama gelir?', a: ['Uyku öncesi duş almak', 'Kaliteli uyku için düzenli uyku saati, karanlık-serin oda, ekran sınırlama gibi sağlıklı alışkanlıklar bütünü', 'Yalnızca melatonin kullanmak', 'Yalnızca spor sonrası'], c: 1, e: 'Uyku hijyeni; düzenli uyku-uyanma saati, uyku öncesi ekrandan uzak durma, karanlık ve serin ortam, kafein kısıtlama gibi sağlıklı uyku alışkanlıklarının bütününü tanımlar.', d: 2 },
  { q: '"Alerji testi" nasıl yapılır?', a: ['Yalnızca kan testi', 'Deri prick testi, yama testi ve kan IgE ölçümü gibi yöntemlerle alerjene özgü tepki ölçülür', 'Yalnızca nefes testi', 'Yalnızca çocuklarda'], c: 1, e: 'Alerji testleri; prick testi (deri üzerine alerjene damlatma), patch testi (yama testi) ve RAST/ELISA ile kanda alerjen özgü IgE ölçümünden oluşur.', d: 2 },
  { q: '"Grip aşısı" neden her yıl yenilenir?', a: ['Çok pahalı', 'İnfluenza virüsü her yıl mutasyon geçirir; yeni dönem aşısı güncel virüs türlerine göre formüle edilir', 'Yanlış üretim', 'Bağışıklık düşük'], c: 1, e: 'İnfluenza virüsü, genetik yapısını sık değiştirdiğinden (antijenik kayma/sürüklenme) mevcut aşı yeni mevsim türlerine karşı yeterli koruma sağlayamaz; bu yüzden aşı her yıl güncellenir.', d: 2 },
  { q: '"Kardiyopulmoner resüsitasyon (CPR)" nasıl yapılır?', a: ['Yalnızca nefes ver', 'Göğüs ortasına ritimli baskı (100-120/dak) ve kurtarıcı nefes (eğitim almışsa) kombinasyonu', 'Yalnızca ilaç ver', 'Yalnızca defibrilatörle'], c: 1, e: 'CPR; kalp durmasında beyne kan akışını sürdürmek amacıyla göğüs ortasına iki elin topuğuyla saniyede yaklaşık 2 baskı (100-120/dak) uygulamaktır. Kurtarıcı nefes eğitimlilerce eklenir.', d: 2 },
  { q: '"Triaj" sisteminde en kritik hasta hangi renkle işaretlenir?', a: ['Yeşil', 'Sarı', 'Kırmızı', 'Siyah'], c: 2, e: 'Triaj sisteminde kırmızı etiket; hemen müdahale gerektiren kritik ama kurtarılabilir hastaları işaret eder. Sarı: ertelenebilir, yeşil: hafif, siyah: kurtarılması çok güç ya da hayatını kaybetmiş.', d: 2 },
  { q: '"Kanser tarama testleri" neden erken dönemde yapılmalıdır?', a: ['Çünkü zorunlu', 'Erken aşamada yakalanan kanser; tedaviye çok daha iyi yanıt verir ve iyileşme oranı dramatik artar', 'Yalnızca belirtiler çıkınca', 'Yalnızca ileri yaşta'], c: 1, e: 'Erken evre kanser; cerrahi, radyoterapi veya kemoterapi seçenekleriyle çok daha yüksek başarı oranında tedavi edilebilir. Meme, kolon ve serviks kanser taramalarının erken tespitteki faydası bilimsel olarak kanıtlanmıştır.', d: 2 },
  { q: '"Bağımlılık" hastalık mıdır?', a: ['Hayır, irade sorunudur', 'Evet; beyin ödül sistemini etkileyen, kronik tekrarlayan bir nörolojik-psikiyatrik hastalık', 'Yalnızca uyuşturucu için', 'Yalnızca alkol için'], c: 1, e: 'Modern tıp bağımlılığı; bir tercih ya da ahlaki zayıflık değil, beynin dopamin ve ödül devrelerini değiştiren kronik bir beyin hastalığı olarak tanımlar. Tedavi edilebilir bir tıbbi durumdur.', d: 2 },
  { q: '"Migren" ile "gerilim baş ağrısı" arasındaki fark nedir?', a: ['Aynı şeydir', 'Migren; genellikle tek taraflı, zonklayan, bulantı-ışık hassasiyetiyle seyreder; gerilim tipi ise bilateral ve sıkıştırıcı niteliktedir', 'Yalnızca şiddet farkı', 'Migren yalnızca kadınlarda'], c: 1, e: 'Migren; genellikle tek taraflı, zonklayan şiddetli ağrı, bulantı ve ışık/ses hassasiyetiyle karakterizedir. Gerilim tipi baş ağrısı ise "başı kemer gibi sıkan" şeklinde bilateral, hafif-orta yoğunlukta seyreder.', d: 2 },
  { q: '"Hipertansiyon" neden "sessiz katil" olarak anılır?', a: ['Belirtileri çok fazla', 'Uzun süre belirti vermeden ilerlediği için; erken tespit ancak ölçümle mümkündür', 'Yalnızca ileri yaşta', 'Yalnızca erkeklerde'], c: 1, e: 'Hipertansiyon; çoğunlukla yıllarca belirti vermeksizin kalp, böbrek ve beyin damarlarına hasar verir. Bu yüzden düzenli tansiyon ölçümü; kalp krizi ve inme gibi komplikasyonları önlemenin temel yoludur.', d: 1 },
  { q: '"Kronik ağrı" nasıl tanımlanır?', a: ['Yalnızca yaralanma ağrısı', '3 aydan uzun süren ve altta yatan neden tedavi edilse bile devam eden ağrı; biyopsikososyal faktörleri içerir', 'Yalnızca kanser ağrısı', 'Yalnızca kassal'], c: 1, e: 'Kronik ağrı; 3 ayı aşan ve altta yatan neden iyileşse bile süren ağrı sendromudur. Biyolojik, psikolojik ve sosyal bileşenleri olan karmaşık bir tıbbi tablodur; multidisipliner yaklaşım gerektirir.', d: 2 },
  { q: '"Böbrek yetmezliği" sonucunda neden diyaliz yapılır?', a: ['Kan inceltmek için', 'Böbrekler atıkları ve sıvıyı filtreleyemez hale gelince diyaliz bu işlevi yapay olarak üstlenir', 'Kan üretmek için', 'Yalnızca kalp komplikasyonunda'], c: 1, e: 'Böbrekler; kandan üre, kreatinin ve fazla sıvıyı filtreler. Kronik böbrek yetmezliğinde bu filtrasyon kapasitesi kaybolunca hemodiyaliz ya da periton diyalizi yapay olarak temizlik işlevini üstlenir.', d: 2 },
  { q: '"Organ nakli" için hangi temel uyumluluk testi yapılır?', a: ['Sadece kan grubu', 'Kan grubu uyumu, doku tipi (HLA), cross-match ve organ boyut uyumu', 'Sadece yaş uyumu', 'Yalnızca cinsiyet uyumu'], c: 1, e: 'Organ naklinde; ABO kan grubu uyumu, doku tiplendirmesi (HLA antijenleri), cross-match (bağışıksal uyum testi) ve organın boyut-işlevsel kapasitesi değerlendirilir. Bu testler reddi önlemek için kritiktir.', d: 2 },
  { q: '"Şeker hastası" bireyin ayak bakımı neden kritiktir?', a: ['Estetik', 'Diyabetik nöropati ve damar hasarı; küçük yaraların büyük enfeksiyon/ampütasyona dönüşme riskini artırır', 'Yalnızca ileri yaşta', 'Yalnızca insülin kullananlarda'], c: 1, e: 'Diyabet; periferik sinirleri (nöropati) ve damarları (anjiyopati) etkileyerek ayak duyusunu azaltır ve yaralanma farkındalığını yitirir. Küçük bir yarada fark edilmeyen enfeksiyon hızla ilerleyerek ampütasyona yol açabilir.', d: 2 },
  { q: '"Tansiyon aleti" nasıl doğru kullanılır?', a: ['Ayakta ölçülür', 'Oturur pozisyonda, dinlendikten sonra (5 dk), kol kalp hizasında ve sigara/kahveden kaçınılarak ölçülür', 'Koşar adım ölçülür', 'Sabah uykudan hemen sonra'], c: 1, e: 'Doğru tansiyon ölçümü için; 5 dakika dinlendikten sonra, oturur pozisyonda, kol kalp hizasında tutularak ölçüm yapılmalı ve sigaradan en az 30 dakika önce arındırılmalıdır.', d: 2 },
  { q: '"Anoreksia nervoza" nedir?', a: ['Aşırı yeme bozukluğu', 'Beden imgesi bozukluğu ve aşırı kısıtlayıcı yeme davranışıyla seyreden ciddi bir yeme bozukluğu', 'Yalnızca kadınlarda', 'Sadece ergenlikte'], c: 1, e: 'Anoreksiya nervoza; beden imgesi algı bozukluğu, aşırı kilo alma korkusu ve ağır kısıtlayıcı yeme davranışıyla karakterize, yüksek mortalite oranına sahip ciddi bir psikiyatrik-tıbbi hastalıktır.', d: 2 },
  { q: '"Anestezi" nasıl çalışır?', a: ['Yalnızca kasları uyuşturur', 'Genel anestezi beyni geçici bilinçsizliğe sokar; lokal anestezi sinir iletimini bloke eder', 'Yalnızca ağrıyı keser', 'Kan dolaşımını durdurur'], c: 1, e: 'Genel anestezi; merkezi sinir sistemini etkileyen ilaçlarla bilinç kaybı, ağrı duyusu yitimi ve kas gevşemesi sağlar. Lokal/bölgesel anestezi ise sinir liflerindeki iyon kanallarını bloke ederek yalnızca belirli bölgede ağrıyı keser.', d: 2 },
  { q: '"Kemoterapinin" yan etkileri neden oluşur?', a: ['Yanlış doz', 'Hızlı bölünen kanser hücrelerini hedef alan ilaç; kemik iliği, saç kökleri ve bağırsak gibi sağlıklı hızlı bölünen hücreleri de etkiler', 'Yalnızca bağışıklığı baskılar', 'Sadece mide sorunları'], c: 1, e: 'Kemoterapi; hızlı bölünen hücreleri hedefler. Kanser hücrelerine ek olarak kemik iliği (kansızlık/enfeksiyon riski), saç kökleri, sindirim sistemi epiteli gibi sağlıklı hızlı bölünen hücreler de etkilenerek yan etkiler oluşur.', d: 2 },
  { q: '"Egzersizin" kalp sağlığına faydaları nelerdir?', a: ['Yalnızca kilo kaybı', 'LDL kolesterolü düşürür, HDL\'yi artırır, kalp kasını güçlendirir, kan basıncını düzenler ve tromboz riskini azaltır', 'Yalnızca solunum', 'Yalnızca psikolojik fayda'], c: 1, e: 'Düzenli aerobik egzersiz; kalp kasını güçlendirir, damar elastikiyetini artırır, "iyi" HDL kolesterolü yükseltir, "kötü" LDL\'yi düşürür, tansiyon üzerinde olumlu etki yapar ve genel kardiyovasküler riski azaltır.', d: 1 },
  { q: '"Nöroplastisite" nedir?', a: ['Sinir hasarı', 'Beynin yeni deneyimler, öğrenme ve hasarla birlikte yeniden yapılanabilme kapasitesi', 'Yalnızca çocuklarda', 'Nörolojik hastalık'], c: 1, e: 'Nöroplastisite; beyin sinir ağlarının deneyim, öğrenme, stres ya da hasara yanıt olarak yeniden düzenlenebilme yetisidir. İnme rehabilitasyonundan dil öğrenmeye kadar pek çok alanda kritik öneme sahiptir.', d: 2 },
  { q: '"Antibiyotik" neden viral enfeksiyonlarda işe yaramaz?', a: ['Dozaj az', 'Antibiyotikler yalnızca bakterilere etki eder; virüslerin farklı yapısına karşı etkisizdir', 'Sadece spesifik bakterilerde', 'Saklama koşulları'], c: 1, e: 'Antibiyotikler; bakteri hücre duvarı, protein sentezi veya DNA replikasyonunu hedefleyen ilaçlardır. Virüsler çok farklı biyolojik mekanizmaya sahip olduğundan antibiyotikler grip, nezle gibi viral hastalıklara etki etmez.', d: 1 },
  { q: '"Meme kanseri" riski için hangi faktörler öne çıkar?', a: ['Yalnızca kalıtım', 'BRCA1/2 mutasyonu, aile öyküsü, hormonal faktörler, yaş, obezite ve alkol tüketimi', 'Sadece hormonal kontraseptif', 'Yalnızca radyasyon'], c: 1, e: 'Meme kanseri risk faktörleri; BRCA1/2 gen mutasyonu, güçlü aile öyküsü, erken adet-geç menopoz (uzun östrojen maruziyeti), obezite, alkol tüketimi ve yoğun radyasyon maruziyeti başlıca faktörler arasındadır.', d: 2 },
  { q: '"Otoimmün hastalık" nasıl oluşur?', a: ['Dış bakteri nedeniyle', 'Bağışıklık sisteminin vücudun kendi dokularını yabancı olarak tanıyıp saldırması', 'Yalnızca alerjik', 'Yalnızca ileri yaşta'], c: 1, e: 'Otoimmün hastalıkta; bağışıklık sistemi kendi dokularını (eklem, tiroid, sinir vb.) yabancı antijen gibi algılayarak saldırır. Tip 1 diyabet, romatoid artrit, lupus ve çölyak hastalığı bu gruba girer.', d: 2 },
  { q: '"Kanserin yaygın evrelelemesi (staging)" neyi ifade eder?', a: ['Yalnızca tümör boyutu', 'TNM sistemi; tümör boyutu (T), lenf nodu tutulumu (N) ve uzak metastaz (M) varlığını değerlendirir', 'Yalnızca konum', 'Yalnızca hücre tipi'], c: 1, e: 'TNM evreleme sistemi; kanserin Tümör boyutu, Lenf Nodu tutulumu ve Metastaz durumuna göre Evre I\'den IV\'e kadar sınıflandırır. Tedavi seçimi ve prognoz bu evreye göre belirlenir.', d: 2 },
  { q: '"Beyin felci" (inme) sırasında "FAST" sınavı nedir?', a: ['İlaç adı', 'Face (yüz sarkması), Arm (kol güçsüzlüğü), Speech (konuşma bozukluğu), Time (vakit kaybetme); inme belirtileri', 'Acil servis kodu', 'Tanı testi'], c: 1, e: 'FAST; inme belirtilerini hızlı tanımaya yarayan kısaltmadır: Face (yüzde sarkma), Arm (bir kolun güçsüz düşmesi), Speech (konuşma bozukluğu), Time (hemen 112\'yi ara). Her dakika beyin hücresi kaybı demektir.', d: 1 },
  { q: '"Hamilelik döneminde" folik asit neden önemlidir?', a: ['Enerji için', 'Nöral tüp defektleri (spina bifida) riskini azaltır; çekirdeğe ve hücre bölünmesine destek olur', 'Yalnızca demir desteği', 'Yalnızca son trimestr'], c: 1, e: 'Folik asit (B9); nöral tüp (beyin ve omurilik) gelişiminde kritiktir. Gebelikten önce ve ilk 3 ayda yeterli alım; spina bifida ve anensefali gibi ciddi doğumsal defektlerin riskini önemli ölçüde azaltır.', d: 2 },
  { q: '"Osteoartrit" ile "romatoid artrit" arasındaki fark nedir?', a: ['İkisi aynı', 'Osteoartrit mekanik yıpranmadır; romatoid artrit ise bağışıklık sisteminin eklemlere saldırdığı otoimmün hastalık', 'Yalnızca yaşla ilgili', 'Yalnızca diz ekleminde'], c: 1, e: 'Osteoartrit; eklem kıkırdağının mekanik yıpranmasına bağlıdır ve yaşla birlikte sıklığı artar. Romatoid artrit ise bağışıklık sisteminin sinovyal zarı hedef aldığı, genç yaşlarda da görülen otoimmün hastalıktır.', d: 2 },
  { q: '"Kolorektal kanser taraması" için hangi test önerilir?', a: ['Sadece kan testi', 'Gaitada gizli kan testi ve/veya kolonoskopi; risk grubuna göre 45-50 yaşından itibaren', 'Sadece ultrason', 'Yalnızca belirtiler varsa'], c: 1, e: 'Kolorektal kanser taraması; 45-50 yaşından itibaren gaitada gizli kan testi (GGKT), sigmoidoskopi ya da tam kolonoskopi ile yapılmalıdır. Poliplerin erken evre tespiti kansere dönüşümü engeller.', d: 2 },
  { q: '"Psöriyazis" nedir?', a: ['Alerjik cilt hastalığı', 'Bağışıklık sisteminin cilt hücrelerini aşırı üretmesine yol açan kronik otoimmün cilt hastalığı', 'Mantar enfeksiyonu', 'Sadece yaşlılarda'], c: 1, e: 'Psöriyazis; T hücresi aktivasyonuyla cilt hücrelerinin hızla çoğaldığı kronik otoimmün tablodur. Gümüş-beyaz kepekli kırmızı plaklar görünür. Alevlenme ve remisyon dönemleriyle seyreder.', d: 2 },
  { q: '"Hipertiroidi" ile "hipotiroidi" arasındaki fark nedir?', a: ['Aynı şeyler', 'Hipertiroidi tiroid fazla çalışır (hızlı metabolizma); hipotiroidi ise az çalışır (yavaş metabolizma)', 'Yalnızca kadın hastalığı', 'Yalnızca boğaz'], c: 1, e: 'Tiroid bezi yetersiz hormon üretirse hipotiroidi (yorgunluk, kilo alımı, soğuk hassasiyeti); fazla üretirse hipertiroidi (çarpıntı, terleme, kilo kaybı) tablosu oluşur.', d: 2 },
  { q: '"Uyku apnesi" neden sağlığı tehdit eder?', a: ['Yalnızca horultu', 'Uyku sırasında tekrarlayan solunum durmaları; oksijen düşüşü, kardiyovasküler yük ve kronik yorgunluğa neden olur', 'Yalnızca şişman bireyler', 'Yalnızca yaşlılarda'], c: 1, e: 'Obstrüktif uyku apnesi; uyku sırasında üst solunum yolunun kapanmasıyla tekrar eden apne episodları oluşturur. Her episodda oksijen düşer, kalp ve damarlar strese girer; hipertansiyon, kalp ritim bozukluğu ve depresyon riski artar.', d: 2 },
  { q: '"Kolesterol" yönetiminde hangi diyet öğeleri önemlidir?', a: ['Yalnızca yağ azaltma', 'Doymuş ve trans yağları azaltmak, omega-3 ve lif artırmak, işlenmiş gıdadan uzak durmak', 'Yalnızca et yememek', 'Yalnızca ilaç'], c: 1, e: 'Kolesterol yönetiminde; doymuş yağ (tereyağı, kırmızı et) ve trans yağ (margarin, cips) kısıtlanmalı, omega-3 yağ asitleri (yağlı balık, ceviz) ve çözünür lif (yulaf, fasulye) artırılmalıdır.', d: 2 },
  { q: '"Hepatit B" nasıl bulaşır ve önlenir?', a: ['Hava yoluyla', 'Kan ve vücut sıvıları, cinsel temas, anne-bebek geçişi; aşıyla önlenebilir', 'Yalnızca su ile', 'Yalnızca el temasıyla'], c: 1, e: 'Hepatit B; kan transfüzyonu, kontamine iğne, cinsel temas ve perinatal (anne-bebek) yolla bulaşır. Etkili bir aşısı mevcuttur; Türkiye\'de ulusal aşı takviminde zorunlu olarak yer almaktadır.', d: 2 },
  { q: '"Genel pratisyen" ile "uzman hekim" arasındaki fark nedir?', a: ['İkisi aynı', 'Pratisyen; birinci basamak sağlık hizmeti verir, genel değerlendirme yapar; uzman, belirli bir alanda derin eğitim almış', 'Uzman daha genç', 'Yalnızca hastanede uzman'], c: 1, e: 'Pratisyen (aile hekimi); genel sağlık değerlendirmesi, koruyucu hekimlik ve sevk yapar. Uzman hekim ise belirli bir uzmanlık dalında (kardiyoloji, nöroloji vb.) ileri eğitim almış ve o alanda derinlemesine tanı-tedavi uygulayan hekimdir.', d: 1 },
  { q: '"Genetik danışmanlık" ne zaman başvurulur?', a: ['Yalnızca kanser hastalarında', 'Kalıtsal hastalık aile öyküsü, tekrarlayan düşük, ileri anne yaşı veya genetik bozukluk riski durumlarında', 'Yalnızca doğumdan sonra', 'Yalnızca erişkinlerde'], c: 1, e: 'Genetik danışmanlık; ailede kalıtsal hastalık öyküsü, gebelik kayıpları, akraba evliliği, ileri yaş gebeliği ya da riskli genetik test sonuçlarında başvurulan uzmanlık dalıdır.', d: 2 },
  { q: '"KOAH" (Kronik Obstrüktif Akciğer Hastalığı) nedir?', a: ['Alerjik astım', 'Sigara başta olmak üzere hava yolu maruziyetiyle gelişen kronik, ilerleyici hava akımı kısıtlaması', 'Yalnızca astım', 'Akciğer kanseri'], c: 1, e: 'KOAH; kronik bronşit ve amfizemi kapsayan, sigara içenler başta olmak üzere tekrarlayan solunum yolu maruziyetiyle gelişen kalıcı hava akımı kısıtlamasıdır. Tedavisi yoktur; semptom yönetimi ve ilerlemenin durdurulması hedeflenir.', d: 2 },
  { q: '"Sağlıklı vücut kitle indeksi (VKİ)" aralığı nedir?', a: ['15-20', '18.5-24.9', '25-30', '10-15'], c: 1, e: 'VKİ = ağırlık (kg) / boy² (m²). Normal aralık 18.5-24.9 olarak kabul edilir. 25-29.9 aşırı kilolu, 30 ve üzeri obez sınıfındadır. VKİ yağ dağılımı hakkında bilgi vermez; bel çevresiyle birlikte değerlendirilmelidir.', d: 1 },
  { q: '"D vitamini eksikliği" hangi sağlık sorunlarına yol açar?', a: ['Yalnızca dişlerde', 'Kemik erimesi, bağışıklık zayıflığı, kas güçsüzlüğü ve bazı araştırmalara göre depresyon riski', 'Yalnızca bebeklerde', 'Yalnızca güneşsiz kışlarda'], c: 1, e: 'D vitamini; kalsiyum emilimi ve kemik sağlığı için kritiktir. Yetişkinde osteomalazi, çocukta raşitizm; bağışıklık baskılanması ve kas güçsüzlüğü de D vitamini eksikliğiyle ilişkilendirilmektedir.', d: 2 },
  { q: '"Koroner anjiyografi" nedir?', a: ['Kalbin ultrason görüntüsü', 'Kalp damarlarına kontrast madde verilerek floroskopi ile tıkanıklıkların görüntülendiği girişimsel tanı yöntemi', 'EKG türü', 'Kan tahlili'], c: 1, e: 'Koroner anjiyografi; kasık ya da bilek damarından ilerletilen kateter aracılığıyla kalp koroner arterlerine kontrast madde verilerek darlık ve tıkanıklıkların görüntülendiği altın standart tanı yöntemidir.', d: 2 },
  { q: '"Şizofreni" nedir?', a: ['Kişilik bölünmesi', 'Sanrı, varsanı, düşünce bozukluğu ve sosyal içe çekilmeyle seyreden kronik psikiyatrik hastalık', 'Birden fazla kimlik', 'Sadece konuşma bozukluğu'], c: 1, e: 'Şizofreni; gerçeklikle bağlantıyı bozan sanrılar, halüsinasyonlar (en sık sesler duyma), dezorganize düşünce ve negatif belirtilerden oluşan ciddi kronik psikiyatrik bozukluktur.', d: 2 },
  { q: '"Tüberküloz" (verem) nasıl bulaşır?', a: ['Dokunmayla', 'Hasta bireyin öksürük ve aksırıklarından havaya karışan damlacıklarla solunum yoluyla', 'Yalnızca gıdayla', 'Yalnızca kontamine su ile'], c: 1, e: 'Tüberküloz; Mycobacterium tuberculosis\'in solunum yoluyla bulaştığı, ağırlıklı olarak akciğerleri etkileyen enfeksiyöz hastalıktır. BCG aşısı ağır çocukluk çağı formlarına karşı koruma sağlar.', d: 2 },
  { q: '"Obezite" nasıl tanımlanır?', a: ['Yalnızca görsel', 'VKİ 30 ve üzeri; yağ dokusunun sağlığı olumsuz etkileyen boyutlara ulaşması', 'Sadece fazla yemek', 'Yalnızca kalıtımsal'], c: 1, e: 'Obezite; vücut kitle indeksinin 30 ve üzerinde olması ya da bel çevresinin kritik değerleri aşmasıyla tanımlanan kronik metabolik hastalıktır. Diyabet, kalp hastalığı ve bazı kanser türleri için önemli bir risk faktörüdür.', d: 1 },
  { q: '"Tıbbi etik"in temel ilkeleri nelerdir?', a: ['Yalnızca gizlilik', 'Özerklik, yararlılık, zararsızlık ve adalet', 'Sadece malpraktis', 'Yalnızca hekimin kararı'], c: 1, e: 'Modern tıbbi etiğin dört temel ilkesi; hastanın özerk karar verme hakkına saygı (autonomy), yarar sağlamak (beneficence), zarar vermekten kaçınmak (non-maleficence) ve adalet (justice).', d: 2 },
  { q: '"Fibromiyalji" nedir?', a: ['Kas iltihabı', 'Yaygın kronik kas-iskelet ağrısı, yorgunluk ve uyku bozukluğuyla seyreden santral ağrı sensitizasyon sendromu', 'Yalnızca artrit', 'Yalnızca psikolojik'], c: 1, e: 'Fibromiyalji; yapısal doku hasarı olmaksızın sinir sisteminin ağrı sinyallerini yoğunlaştırdığı kronik bir santral sensitizasyon sendromudur. Yaygın ağrı, yorgunluk ve uyku sorunlarıyla seyreder.', d: 2 },
  { q: '"İmmünoterapi" kanser tedavisinde nasıl çalışır?', a: ['Bağışıklığı baskılar', 'Bağışıklık sistemini kanser hücrelerini tanıyıp yok etmesi için güçlendirir ya da yönlendirir', 'Yalnızca aşı', 'Yalnızca cerrahi destek'], c: 1, e: 'Kanser immünoterapisi; kontrol noktası inhibitörleri ve CAR-T hücre tedavisi gibi yaklaşımlarla bağışıklık sisteminin kanser hücrelerini tanımasını sağlar. Bazı kanser türlerinde çarpıcı başarılar elde edilmiştir.', d: 2 },
  { q: '"Antibiyotik direnci" neden küresel tehdit olarak görülür?', a: ['Yalnızca sanayi sorunu', 'Aşırı kullanımla bakteri mutasyonları dirençli suşlar yaratır; etkili antibiyotik seçeneği giderek daralır', 'Sadece hastanelerde', 'Yalnızca gelişmekte olan ülkelerde'], c: 1, e: 'Antibiyotik direnci; yanlış kullanım, tamamlanmayan tedavi ve hayvancılıkta aşırı antibiyotikle hızlanmaktadır. Çok ilaca dirençli bakteriler yayıldıkça mevcut tedaviler etkisiz kalmakta ve bu küresel sağlık tehditi büyümektedir.', d: 2 },
  { q: '"İnme" için risk faktörleri nelerdir?', a: ['Yalnızca yaş', 'Hipertansiyon, atriyal fibrilasyon, diyabet, sigara, yüksek kolesterol ve obezite', 'Yalnızca kalıtım', 'Yalnızca stres'], c: 1, e: 'İnme risk faktörlerinin başında; kontrolsüz hipertansiyon (en önemli), atriyal fibrilasyon, tip 2 diyabet, sigara kullanımı, yüksek LDL kolesterol ve obezite gelmektedir.', d: 2 },
  { q: '"Yanık dereceleri" nasıl sınıflandırılır?', a: ['Yalnızca 2 derece', '1. derece (yüzeysel), 2. derece (kısmi kalınlık), 3. derece (tam kalınlık), 4. derece (derin dokular)', 'Yalnızca büyük-küçük', 'Sıcaklığa göre'], c: 1, e: 'Yanıklar; 1. derece (kızarıklık), 2. derece (su toplama, derin deri), 3. derece (tam deri kaybı, ağrı yok), 4. derece (kas/kemik tutulumu) şeklinde sınıflandırılır.', d: 2 },
  { q: '"Pnömoni" nedir ve nasıl bulaşır?', a: ['Yalnızca viral', 'Akciğer doku iltihabı; bakteri (en sık S. pneumoniae), virüs veya mantar kaynaklı olabilir', 'Yalnızca çocuklarda', 'Deri temasıyla bulaşır'], c: 1, e: 'Pnömoni; akciğer alveollerinin iltihaplanmasıdır. En sık Streptococcus pneumoniae kaynaklı olsa da viral (influenza, COVID-19) ve mantar pnömonileri de görülür. Solunum damlacıkları yoluyla bulaşabilir.', d: 2 },
  { q: '"Romatoid artrit" tedavisinde kullanılan temel ilaç grupları nelerdir?', a: ['Yalnızca ağrı kesiciler', 'DMARDs (hastalık modifiye ediciler), biyolojikler ve kortikosteroidler', 'Yalnızca cerrahi', 'Yalnızca fizik tedavi'], c: 1, e: 'Romatoid artritte; Metotreksat gibi DMARD\'lar (hastalık modifiye edici antiromatizmal ilaçlar) hastalığın ilerlemesini yavaşlatır. Biyolojik ajanlar (TNF inhibitörleri) ve kortikosteroidler de tedavi protokolünde yer alır.', d: 3 },
  { q: '"Kronik böbrek hastalığında" hangi beslenme değişiklikleri gerekir?', a: ['Protein artır', 'Protein, potasyum, fosfor ve sodyum kısıtlaması; sıvı dengesi yönetimi', 'Yalnızca tuz azalt', 'Yalnızca diyaliz hastaları için'], c: 1, e: 'Kronik böbrek yetmezliğinde böbreklerin atık atma kapasitesi düştüğünden; fazla protein (üre yükü), potasyum (ritim bozukluğu), fosfor (kemik hasarı) ve sodyum (hipertansiyon-ödem) kısıtlanmalıdır.', d: 2 },
  { q: '"Sigara"nın kanser dışındaki sağlık etkileri nelerdir?', a: ['Yalnızca akciğer', 'KOAH, kalp hastalığı, inme, periferik damar hastalığı, iktidarsızlık ve hızlı cilt yaşlanması', 'Yalnızca solunum', 'Yalnızca uzun vadeli'], c: 1, e: 'Sigara; akciğer kanseri dışında KOAH, koroner kalp hastalığı, inme, periferik damar tıkanıklığı, erkekte erektil disfonksiyon ve cilt yaşlanma hızlanması gibi sistemik hasarlar oluşturur.', d: 1 },
  { q: '"Kan grubu uyumsuzluğu" transfüzyonda ne tehlikesi yaratır?', a: ['Yalnızca hafif reaksiyon', 'Akut hemolitik transfüzyon reaksiyonu; eritrositlerin parçalanması, böbrek yetmezliği ve ölüm riski', 'Sadece ateş', 'Yalnızca uzun vadeli'], c: 1, e: 'Yanlış kan grubu transfüzyonunda; alıcının antikorları verici eritrositlerini tahrip eder (hemoliz), ağır akut reaksiyon gelişir ve böbrek yetmezliği dahil hayati tehlike oluşabilir.', d: 2 },
  { q: '"Alzheimer hastalığı"nı diğer demanslardan ayıran özellik nedir?', a: ['Ani başlangıç', 'Yavaş ilerleyen, önce kısa süreli bellekte bozulmaya yol açan amiloid plak ve nörofibriler yumak birikimi', 'Sadece hafıza kaybı', 'Sadece ileri yaşta'], c: 1, e: 'Alzheimer; beta-amiloid plaklar ve tau proteini yumakları birikimiyle nöronal ölümün yavaş ilerlediği demans tipidir. Önce kısa süreli bellek etkilenir; dil, yürütücü işlev ve davranış giderek bozulur.', d: 2 },
  { q: '"Akut apandisit" belirtileri nelerdir?', a: ['Sol karın ağrısı', 'Göbek çevresinden başlayıp sağ alt kadrana yerleşen ağrı, bulantı, iştahsızlık ve ateş', 'Yalnızca ateş', 'Yalnızca mide bulantısı'], c: 1, e: 'Akut apandisit; tipik olarak göbek etrafında başlayıp 24-48 saat içinde sağ alt kadrana (McBurney noktası) taşınan ağrı, bulantı, iştahsızlık ve düşük dereceli ateşle seyreder. Tanı gecikmesi perforasyona yol açabilir.', d: 2 },
  { q: '"Epilepsi" (sara) nedir?', a: ['Bayılma hastalığı', 'Beyin nöronlarının aşırı ve anormal deşarjıyla tekrarlayan nöbetlerle karakterize kronik nörolojik bozukluk', 'Yalnızca çocuk hastalığı', 'Yalnızca bilinç kaybı'], c: 1, e: 'Epilepsi; beyin elektrik aktivitesinin anormal deşarjlarından kaynaklanan tekrarlayan nöbetlerle seyreden kronik nörolojik hastalıktır. Nöbet türleri farklılık gösterir; antiepileptik ilaçlar vakaların çoğunu kontrol altına alır.', d: 2 },
  { q: '"Biyopsi" neden yapılır?', a: ['Kan tahlili için', 'Doku örneği alınarak mikroskobik incelemeyle kesin tanı koymak; özellikle kanser şüphesinde', 'Yalnızca ameliyat öncesi', 'Yalnızca kemik için'], c: 1, e: 'Biyopsi; şüpheli dokudan örnek alınarak patoloji laboratuvarında hücre düzeyinde inceleme yapılmasıdır. Kanser teşhisinde altın standart tanı yöntemidir; tümörün türü, derecesi ve davranışını belirler.', d: 2 },
  { q: '"Hemoglobin" ne işe yarar?', a: ['Kan pıhtılaştırır', 'Alyuvarlardaki demir içerikli protein; oksijeni akciğerlerden dokulara taşır', 'Bağışıklığı sağlar', 'Sindirime yardımcı olur'], c: 1, e: 'Hemoglobin; alyuvarlarda bulunan ve dört demir atomu içeren protein yapısıdır. Oksijeni akciğerlerden bağlayarak vücudun tüm dokularına dağıtır; karbondioksiti geri taşır.' },
  { q: '"Lösemi" nedir?', a: ['Kemik hastalığı', 'Kan hücrelerinin kontrolsüz üremesiyle karakterize kan kanseri türü', 'Anemi türü', 'Damar hastalığı'], c: 1, e: 'Lösemi; kemik iliğinde kan hücrelerinin (genellikle lökositler) anormal biçimde çoğaldığı, normal kan hücresi üretimini baskılayan ve kemoterapiyle tedavi edilen kan kanseri türüdür.' },
  { q: '"Miyopi" (kısa görlük) nasıl oluşur?', a: ['Yaşlanmayla', 'Göz ön-arka çapının uzun olmasıyla ışık retina önünde odaklanır; uzağı bulanık görmek', 'Retina hasarı', 'Şeker hastalığı'], c: 1, e: 'Miyopide göz küresi normalden uzun veya kornea eğriliği fazladır; bu yüzden paralel ışınlar retina önünde odaklanır ve uzaktaki nesneler bulanık görünür. Gözlük, lens veya lazer tedaviyle düzeltilebilir.' },
  { q: '"Lenf sistemi" vücutta ne işlev görür?', a: ['Kan üretir', 'Doku sıvısını dolaşıma geri döndürür, bağışıklık hücrelerini taşır ve yağ absorbe eder', 'Sinir iletimi', 'Hormon salgılar'], c: 1, e: 'Lenf sistemi; doku aralığındaki fazla sıvıyı toplar, bağışıklık sisteminin lenf düğümleri aracılığıyla yabancı maddeleri filtreler ve bağırsak villüslerinden yağları emilimde yardımcı olur.' },
  { q: '"Tansiyon ölçümündeki" iki sayı neyi ifade eder?', a: ['Nabız ve nefes', 'Sistolik (kalp kasıldığında) / diastolik (kalp gevşediğinde) basınç', 'Kan miktarı', 'Damar genişliği'], c: 1, e: 'Sistolik basınç; kalbin kasılıp kanı pompaladığı andaki yüksek basıncı. Diastolik; kalbin gevşeyip dinlendiği andaki düşük basıncı ifade eder. Normal değer yaklaşık 120/80 mmHg\'dır.' },
  { q: '"Otoimmün hastalıklarda" bağışıklık sistemi neden kendi vücuduna saldırır?', a: ['Zayıf bağışıklık', 'Tolerans mekanizmasının bozulmasıyla kendi dokularına yabancı gibi davranılır', 'Virüs saldırır', 'Hormon eksikliği'], c: 1, e: 'Otoimmün hastalıklarda bağışıklık sistemi; merkezi tolerans mekanizması bozulur ve kendi proteinlerini yabancı antijen gibi algılayarak saldırır. Tip 1 diyabet, romatoid artrit ve lupus bu gruba girer.' },
  { q: '"Akupunktur" hangi bölge tıbbına dayanır?', a: ['Hint Ayurveda', 'Geleneksel Çin tıbbı', 'Yunan antik tıbbı', 'Arap tıbbı'], c: 1, e: 'Akupunktur; geleneksel Çin tıbbına dayanan ve enerji akış noktalarına (meridyenler) ince iğne batırılması ilkesine dayanan tamamlayıcı tıp yöntemidir. Batı tıbbı bazı endikasyonlarda destekleyici etkisini kabul etmektedir.' },
  { q: '"Dehidrasyon" (susuz kalma) belirtileri nelerdir?', a: ['Yalnızca susama', 'Susama, koyu idrar, baş dönmesi, halsizlik ve zihin bulanıklığı; ağır vakalarda şok', 'Yalnızca baş ağrısı', 'Yalnızca ateş'], c: 1, e: 'Dehidrasyon; vücut su dengesinin bozulmasıdır. Hafif belirtiler susama ve koyu idrar iken; ağır dehidrasyon tansiyon düşüklüğü, hızlı nabız ve bilinç bozukluğuna kadar ilerleyebilir.' },
  { q: '"Grip (influenza)" ile "soğuk algınlığı" nasıl ayrışır?', a: ['Aynı hastalık', 'Grip; ani yüksek ateş, kas ağrısı ve şiddetli halsizlikle seyreder. Soğuk algınlığı daha hafif ve burun odaklıdır', 'Yalnızca virus türü farkı', 'Grip yalnızca kış'], c: 1, e: 'Grip; influenza virüsünden kaynaklanır, ani 38-40°C ateş, yoğun kas ağrısı ve şiddetli halsizlikle başlar. Soğuk algınlığı ise daha hafif, kademeli başlangıçlı ve ağırlıklı üst solunum yolu semptomlarıyla seyreder.' },
  { q: '"Enfeksiyon" ile "inflamasyon" arasındaki fark nedir?', a: ['Aynı şey', 'Enfeksiyon; mikroorganizma istilası. İnflamasyon; dokunun hasara verdiği bağışıklık yanıtı. Biri olmadan diğeri de olabilir', 'İnflamasyon yalnızca enfeksiyonda', 'Sadece deri için'], c: 1, e: 'Enfeksiyon; bakteri, virüs veya mantar gibi patojenlerin vücuda girmesidir. İnflamasyon ise bu saldırıya (veya mekanik hasara) karşı bağışıklık sisteminin redness/heat/swelling/pain dörtlüsüyle yanıt verdiği süreçtir.' },
  { q: '"Bağırsak florasının" (mikrobiyom) sağlık üzerindeki etkisi nedir?', a: ['Yalnızca sindirim', 'Sindirim, bağışıklık modülasyonu, ruh hali (bağırsak-beyin aksı) ve kronik hastalık riskiyle ilişkili', 'Yalnızca vitamin üretimi', 'Yalnızca diyabet'], c: 1, e: 'Bağırsak mikrobiyomu; beyin-bağırsak aksı aracılığıyla ruh sağlığını, bağışıklık sistemini, otoimmün hastalık riskini ve hatta obezite eğilimini etkileyebilen karmaşık bir ekosistemdir.' },
  { q: '"Hiperglisemi" ve "hipoglisemi" nedir?', a: ['İkisi aynı', 'Hiperglisemi; kan şekeri yüksekliği. Hipoglisemi; kan şekeri düşüklüğü. İkisi de diyabette tehlike işareti', 'Yalnızca kan basıncı', 'Yalnızca böbrek sorunu'], c: 1, e: 'Hiperglisemi (yüksek kan şekeri) uzun vadede damar hasarı yaratır; hipoglisemi (düşük kan şekeri) ise beyin enerji kesintisi nedeniyle bilinç kaybına kadar gidebilecek acil durumdur.' },
  { q: '"Serebral palsi" nedir?', a: ['Epilepsi türü', 'Beyin gelişiminin erken döneminde oluşan hasar sonucu ortaya çıkan hareket ve duruş bozukluğu', 'Yalnızca genetik', 'Yalnızca doğum sonrası'], c: 1, e: 'Serebral palsi; genellikle doğum öncesi, sırası veya kısa süre sonrasında oluşan beyin hasarının yol açtığı, motor fonksiyonları etkileyen kronik bir durumdur. Şiddeti kişiden kişiye büyük farklılık gösterir.' },
  { q: '"Kan transfüzyonunda" en sık kullanılan kan grubu nedir?', a: ['AB+', 'A+', '0- (evrensel verici)', 'B-'], c: 2, e: '0- (O negatif) kan grubu; eritrositlerinde antijen taşımadığı için tüm kan gruplarına verilebilen evrensel vericidir. Acil ve yenidoğan transfüzyonlarında kritik öneme sahiptir.' },
  { q: '"Anestezi riski"ni artıran faktörler nelerdir?', a: ['Yalnızca yaş', 'Obezite, sigara, kalp-akciğer hastalıkları, ilaç kullanımı ve alkol; bunlar anestezi komplikasyon riskini artırır', 'Yalnızca alerji', 'Yalnızca kan grubu'], c: 1, e: 'Anestezi öncesi değerlendirmede; kardiyopulmoner hastalık, obezite, sigara, alkol, ilaç etkileşimleri ve geçirilmiş anestezi reaksiyonları risk faktörleri olarak sorgulanır.' },
  { q: '"Kemik iliği transplantasyonu" neye yarar?', a: ['Kemik kırığı onarımı', 'Hasarlı veya yetersiz çalışan kan hücresi üretimini yeniden kurar; lösemi ve aplastik anemide kullanılır', 'Sinir onarımı', 'Damar tedavisi'], c: 1, e: 'Kemik iliği (kök hücre) transplantasyonu; hasar görmüş veya baskılanmış kemik iliğini sağlıklı kök hücrelerle değiştirerek kan hücresi üretimini yeniden başlatır. Lösemi, lenfoma ve orak hücre anemisinde kullanılır.' },
  { q: '"Psikosomatik" hastalık ne demektir?', a: ['Yalnızca hayal ürünü', 'Psikolojik stres ve duyguların fiziksel semptomlara (mide ağrısı, baş ağrısı, yorgunluk) yol açması', 'Sinir sistemi hastalığı', 'Yalnızca psikiyatri alanı'], c: 1, e: 'Psikosomatik; zihnin bedeni etkilediği durumları tanımlar. Kronik stres; mide ülseri, tansiyon yüksekliği, bağışıklık baskılanması ve ağrı sendromları gibi gerçek fiziksel hastalıklara zemin hazırlayabilir.' },
  { q: '"İnme sonrası rehabilitasyonun" amacı nedir?', a: ['Tam iyileşme garantisi', 'Kayıp fonksiyonları mümkün olan en üst düzeye geri kazandırmak; yürüme, konuşma ve el becerisi', 'Yalnızca ilaç tedavisi', 'Yalnızca hastane bakımı'], c: 1, e: 'İnme rehabilitasyonu; nöroplastisite mekanizmasından yararlanarak hasarlı beyin fonksiyonlarının sağlıklı bölümler tarafından kısmen devralınmasını destekler. Erken dönemde başlanması sonuçları belirgin biçimde iyileştirir.' },
  { q: '"Tiroid bezi" vücutta nasıl bir rol oynar?', a: ['Kan üretir', 'Metabolizmayı, büyümeyi, enerji kullanımını ve ısı üretimini düzenleyen hormonlar salgılar', 'Sindirim enzimi', 'Bağışıklık hücresi'], c: 1, e: 'Tiroid bezi; T3 ve T4 hormonları aracılığıyla metabolizma hızını, kalp atışını, vücut sıcaklığını, büyümeyi ve enerji kullanımını düzenler. Yetersiz (hipotiroidi) veya fazla (hipertiroidi) çalışması geniş sistemik etkiler yaratır.' },
  { q: '"Pankreas"ın iki temel işlevi nedir?', a: ['Kan süzmek ve idrar üretmek', 'Sindirim enzimleri üretmek (ekzokrin) ve insülin-glukagon salgılamak (endokrin)', 'Safra üretmek', 'Kan hücresi yapmak'], c: 1, e: 'Pankreas; hem sindirim bezleri aracılığıyla enzim (amilaz, lipaz, proteaz) salgılayan ekzokrin hem de insülin ve glukagon üreten endokrin görevleri yerine getiren çift işlevli bir bezdir.' },
  { q: '"Enfeksiyon hastalığında izolasyon" ne zaman uygulanır?', a: ['Her hastalıkta', 'Damlacık, hava yolu veya temas yoluyla bulaşabilen hastalıklarda sağlıklı kişileri korumak için', 'Yalnızca ameliyat sonrası', 'Yalnızca yoğun bakımda'], c: 1, e: 'İzolasyon; Tüberküloz, COVID-19, kızamık gibi bulaşıcı hastalıklarda hastanın diğer kişilere bulaştırma riskini azaltmak amacıyla uygulanan kontrol önlemidir.' },
  { q: '"Serebral korteks"in dört lobu nelerdir?', a: ['Frontal, temporal, parietal, oksipital', 'Serebellum, pons, medulla, talamus', 'Limbik, hipotalamus, amigdala, hipokampus', 'Beyin sapı, beyincik, köprü, bademcik'], c: 0, e: 'Serebral korteks; frontal (yürütücü işlev), temporal (dil, hafıza), parietal (duyusal işleme) ve oksipital (görme) olmak üzere dört ana loba ayrılır.' },
  { q: '"Gluten intoleransı" (çölyak) neden sağlık sorunu oluşturur?', a: ['Yalnızca mide krampı', 'Gluten; bağışıklık tepkisine yol açar, ince bağırsak villuslarını hasar görür ve besin emilimi bozulur', 'Yalnızca alerjik', 'Yalnızca cilt sorunu'], c: 1, e: 'Çölyak hastalığı; buğday, arpa ve çavdardaki gluten proteininin otoimmün tepki tetikleyerek ince bağırsak mukozasını tahrip etmesiyle besin malabsorbsiyonuna yol açan genetik kronik hastalıktır.' },
  { q: '"Tıbbi görüntülemede MRI"nın avantajı nedir?', a: ['Hızlı ve ucuz', 'Radyasyon içermez; yumuşak dokuları (beyin, kaslar, eklemler) yüksek çözünürlükte görüntüler', 'Yalnızca kemik için', 'Her hastaya uygundur'], c: 1, e: 'MRI (Manyetik Rezonans Görüntüleme); manyetik alan ve radyo dalgaları kullanır, iyonize radyasyon içermez ve özellikle beyin, omurga, kas-eklem dokularını CT\'den çok daha yüksek kontrastta görüntüler.' },
  { q: '"Bağırsak kanseri" için yaygın risk faktörleri nelerdir?', a: ['Yalnızca genetik', 'Kırmızı et, işlenmiş gıda, hareketsiz yaşam, obezite, sigara, alkol ve kalıtsal faktörler', 'Yalnızca yaş', 'Yalnızca enfeksiyon'], c: 1, e: 'Kolorektal kanser; yüksek kırmızı ve işlenmiş et tüketimi, az lifli diyet, hareketsizlik, obezite, sigara ve alkol gibi değiştirilebilir faktörlerin yanı sıra aile öyküsü ve polip varlığıyla da ilişkilidir.' },
  { q: '"İmmün sistem" ile "enflamasyon" arasındaki ilişki nedir?', a: ['Bağımsız sistemler', 'Bağışıklık aktivasyonu; enflamasyonu başlatır ve düzenler. Kronik enflamasyon ise bağışıklık yükünü artırır', 'Yalnızca ateşte', 'Enflamasyon bağışıklığı zayıflatır'], c: 1, e: 'Akut enflamasyon; bağışıklık sisteminin zararlı uyaranlara karşı verdiği koruyucu yanıttır. Ancak kronik düşük düzeyli enflamasyon; kalp hastalığı, kanser ve Alzheimer gibi hastalıklarla ilişkilendirilmektedir.' },
  { q: '"Apoptozis" (programlı hücre ölümü) neden önemlidir?', a: ['Hücreleri öldürür', 'Hasarlı veya gereksiz hücrelerin kontrollü biçimde elimine edilmesi; kanser önleme ve gelişimde kritik', 'Yalnızca kötü hücrelerde', 'Yalnızca yaşlılıkta'], c: 1, e: 'Apoptozis; genetik olarak programlı, kontrollü hücre ölümüdür. DNA hasarlı veya mutasyona uğramış hücreleri elimine ederek tümör oluşumunu önler; gelişim döneminde parmak aralarının şekillenmesi gibi süreçleri yönetir.' },
  { q: '"Sepsis" neden hayati tehlike taşır?', a: ['Yalnızca enfeksiyon', 'Enfeksiyona karşı kontrolsüz sistemik bağışıklık yanıtı; organ yetmezliği ve ölüme yol açabilir', 'Yalnızca bakteri', 'Yalnızca hastanelerde'], c: 1, e: 'Sepsis; enfeksiyona karşı vücudun anormal ve aşırı sistemik yanıtının doku hasarı, organ yetmezliği ve şoka yol açtığı hayati tehlikeli durumdur. Dünyada önde gelen ölüm nedenlerinden biridir.' },
  { q: '"Kardiyak tamponad" nedir?', a: ['Kalp krizi', 'Kalp kesesinde sıvı birikimi; kalbi sıkıştırarak pompalama kapasitesini kritik düzeyde düşürür', 'Kalp ritim bozukluğu', 'Kalp yetmezliği'], c: 1, e: 'Kardiyak tamponad; perikard (kalp kesesi) içinde biriken sıvının kalp duvarlarına baskı yapması ve pompalamanın ciddi biçimde bozulmasıyla ortaya çıkan acil tıbbi durumdur.' },
  { q: '"Diyabetik retinopati" nedir?', a: ['Göz alerjisi', 'Uzun süreli yüksek kan şekerinin retina damarlarına hasar vererek körlüğe kadar gidebilecek değişiklikler yaratması', 'Glokom türü', 'Katarakt'], c: 1, e: 'Diyabetik retinopati; kronik hipergliseminin retina küçük damarlarını tahrip etmesiyle başlar. Kontrol edilmezse yeni damar büyümesi ve retina dekolmanı ile kalıcı görme kaybına yol açabilir.' },
  { q: '"Panik atak" ile "kalp krizi" nasıl ayırt edilir?', a: ['Aynıdır', 'Panik atakta genellikle korku tetikler; EKG ve troponin normal çıkar. Kalp krizinde troponin yükselir, EKG değişir', 'Yalnızca yaşa göre', 'Yalnızca göğüs ağrısıyla'], c: 1, e: 'Panik atak; çarpıntı, nefes darlığı ve ölüm korku ile kalp krizini taklit edebilir. Ayırımda EKG, troponin ve CK-MB gibi kardiyak belirteçler kullanılır; panik atakta bunlar normaldir.' },
  { q: '"Otoregülasyon" beyin sağlığında ne demektir?', a: ['Beyin aktivitesi', 'Beynin kan basıncı değişikliğine rağmen sabit kan akışını koruma mekanizması', 'Sinir iletimi', 'Hormonal denge'], c: 1, e: 'Serebral otoregülasyon; kan basıncı belirli bir aralıkta değiştiğinde bile beyne gelen kan akışını sabit tutmak için damarların çapını ayarlayan fizyolojik mekanizmadır. İnme ve kafa travmasında bu mekanizma bozulabilir.' },
  { q: '"Kadın sağlığında mamografi" neden yapılır?', a: ['Rutin kan testi', 'Meme dokusunu düşük doz X-ışını ile görüntüleyerek erken evre meme kanserini tespit etmek', 'Yalnızca aile öyküsünde', 'Yalnızca belirti varsa'], c: 1, e: 'Mamografi; erken evre meme kanserini palpe edilebilir kitle oluşmadan önce tespit edebilen tarama yöntemidir. 40-50 yaş üstü kadınlara belirli aralıklarla rutin tarama önerilmektedir.' },
  { q: '"Disleksi" nedir?', a: ['Zeka geriliği', 'Nörolojik temelli okuma-yazma güçlüğü; fonemleri işlemede zorluk. Zeka ile ilişkisi yoktur', 'Görme sorunu', 'Dikkat eksikliği'], c: 1, e: 'Disleksi; fonolojik işleme güçlüğünden kaynaklanan, okuma, yazma ve heceleme zorluğuyla seyreden nörogelişimsel bir durumdur. Zekadan bağımsızdır; birçok başarılı birey disleksikti.' },
  { q: '"Nörotransmitterler" ne işe yarar?', a: ['Beynin elektrik iletisi', 'Sinir hücreleri arasında kimyasal sinyal taşıyan moleküller; ruh hali, uyku ve hareketi düzenler', 'Beyin onarımı', 'Damar genişlemesi'], c: 1, e: 'Dopamin, serotonin, GABA ve asetilkolin gibi nörotransmitterler; nöronlar arasındaki sinaptik iletişimi sağlayan kimyasal habercilerdir. Dengesizlikleri depresyon, şizofreni ve Parkinson gibi hastalıklarla ilişkilidir.' },
  { q: '"Çocukluk çağı obezitesinin" uzun vadeli riskleri nelerdir?', a: ['Yalnızca estetik', 'Tip 2 diyabet, kardiyovasküler hastalık, uyku apnesi, eklem sorunları ve psikososyal etkiler', 'Yalnızca büyüme', 'Ergenlikte kendiliğinden düzelir'], c: 1, e: 'Çocukluk obezitesi; erişkin dönemde Tip 2 diyabet, hipertansiyon, kalp hastalığı, NAFLD ve uyku apnesi riskini artırır. Psikososyal etkiler (düşük benlik saygısı, akran baskısı) da önemli boyuttadır.' },
  { q: '"Yanıkta" ilk yardımın temel kuralı nedir?', a: ['Buz uygula', 'Soğuk (15-20°C) akan su altında 20 dakika; buz ve yağ kullanma', 'Krem sür', 'Üstünü ör'], c: 1, e: 'Yanıkta ilk müdahale; 15-20°C\'deki soğuk akan su altında 20 dakika soğutmaktır. Buz dokuya zarar verir, yağ ısıyı hapseder; ikisi de kontrendikedir.' },
  { q: '"Hipotermi" vücutta neden tehlikelidir?', a: ['Yalnızca donma', 'Vücut sıcaklığı 35°C\'nin altına düşünce; kalp ritmi, beyin işlevi ve kas koordinasyonu bozulur; ölümcül olabilir', 'Yalnızca ekstremitelerde', 'Yalnızca ileri yaşta'], c: 1, e: 'Hipotermi; vücut sıcaklığının 35°C\'nin altına düşmesiyle kardiyak aritmi, bilinç bulanıklığı ve kardiyorespiratuvar durmaya kadar uzanabilen hayati tehlikeli durumdur.' },
  { q: '"Prostat kontrolü" hangi yaşta önerilir?', a: ['20\'li yaşlar', '50 yaş üstü erkeklere; aile öyküsünde 40-45\'ten itibaren', '70 yaş üstü', 'Yalnızca belirti varsa'], c: 1, e: 'Prostat kanseri taraması (PSA testi ve dijital rektal muayene); genel popülasyonda 50 yaşından, aile öyküsü veya yüksek risk grubunda ise 40-45\'ten itibaren önerilmektedir.' },
  { q: '"Antidepresanların" etki mekanizması nedir?', a: ['Beyni uyuşturur', 'Serotonin, noradrenalin veya dopamin geri alımını engelleyerek sinaptik boşlukta bu maddelerin yoğunluğunu artırır', 'Stresin kaynağını giderir', 'Beyin kimyasını değiştirir çok kısa sürede'], c: 1, e: 'SSRI\'lar (örn. fluoksetin); serotonin geri alımını engelleyerek sinaptik boşlukta serotonin düzeyini artırır. SNRI\'lar hem serotonin hem noradrenalin geri alımını hedefler. Etki genellikle 2-4 haftada başlar.' },
  { q: '"Kan pıhtılaşması" (koagülasyon) neden gereklidir?', a: ['Kan sayımı için', 'Yaralanmada kan kaybını durdurmak için trombosit ve pıhtılaşma faktörleri birlikte çalışır', 'Bağışıklık için', 'Yalnızca damar hasarında'], c: 1, e: 'Hemostaz; yaralanma sonrası kan kaybını durdurmak için damar daralması, trombosit aktivasyonu ve pıhtılaşma faktörleri kademesiyle fibrin ağı oluşumunun koordineli biçimde çalışmasıdır.' },
  { q: '"Hipnoz" tıpta nasıl kullanılır?', a: ['Bilinç kaybı', 'Ağrı yönetimi, anksiyete azaltma, sigara bırakma ve fobiler için tamamlayıcı yöntem', 'Anestezi yerine', 'Yalnızca gösteriler için'], c: 1, e: 'Tıbbi hipnoz; kronik ağrı, IBS, anksiyete ve sigara bırakma gibi alanlarda bilinçli bir transa geçilerek önerilerin faydalı biçimde alındığı kanıta dayalı tamamlayıcı yöntemdir.' },
  { q: '"Polikistik over sendromu" (PKOS) nedir?', a: ['Over kanseri', 'Hormonal dengesizlikle karakterize; düzensiz adet, kistler ve insülin direnciyle seyreden endokrin bozukluk', 'Yalnızca ağrı', 'Menopoz belirtisi'], c: 1, e: 'PKOS; androjenlerin yüksek olduğu, adet düzensizliği, over kistleri ve sıklıkla insülin direnciyle seyreden, doğurganlık çağındaki kadınların yaklaşık %10\'unu etkileyen yaygın endokrin bozukluktur.' },

  // ── YENİ SORULAR (244-500) ───────────────────────────────────────────

  // Anatomi & Fizyoloji
  { q: 'İnsan vücudunda en küçük kemik neredededir?', a: ['Parmak', 'Kulak', 'Burun', 'El bileği'], c: 1, e: 'Üzengi kemiği (stapes), orta kulakta yaklaşık 3 mm büyüklüğüyle insan vücudunun en küçük kemiğidir.' },
  { q: 'Kalp kaç odacıktan oluşur?', a: ['2', '3', '4', '6'], c: 2, e: 'Kalp; sağ ve sol kulakçık (atrium) ile sağ ve sol karıncık (ventrikül) olmak üzere 4 odacıktan oluşur.' },
  { q: 'Akciğerlerin temel işlevi nedir?', a: ['Kan üretmek', 'Toksin süzmek', 'Gaz alışverişi (O₂ alıp CO₂ vermek)', 'Sindirim'], c: 2, e: 'Akciğerler; alveoller aracılığıyla kana oksijen sağlar ve metabolizma artığı karbondioksiti dışarı atar.' },
  { q: 'Böbreklerin temel işlevi nedir?', a: ['Kan şekerini düzenlemek', 'Hormonal salgı', 'Kanı süzmek ve idrar oluşturmak', 'Bağışıklık sağlamak'], c: 2, e: 'Böbrekler; kanı süzerek atık ürünleri idrarla dışarı atar, su-elektrolit dengesini ve kan basıncını düzenler.' },
  { q: 'Sinir sisteminin temel hücresi nedir?', a: ['Eritrosit', 'Lökosit', 'Nöron', 'Trombosit'], c: 2, e: 'Nöron (sinir hücresi), sinir sisteminin yapısal ve işlevsel birimidir. Elektrokimyasal sinyaller aracılığıyla bilgi iletir.' },
  { q: 'İnsan vücudundaki en büyük organ hangisidir?', a: ['Karaciğer', 'Beyin', 'Deri', 'Akciğer'], c: 2, e: 'Deri yaklaşık 1,5-2 m² yüzeyi ve 3,5-10 kg ağırlığıyla insan vücudunun en büyük organıdır. Koruma, termoregülasyon ve duyum işlevi görür.' },
  { q: '"Tendon" ile "Ligament" arasındaki fark nedir?', a: ['İkisi aynıdır', 'Tendon kası kemiğe, ligament kemiği kemiğe bağlar', 'Ligament kası kemiğe bağlar', 'Tendon siniri kasa bağlar'], c: 1, e: 'Tendon: kas ile kemik arasında bağlantı kuran sert fibröz bant. Ligament: iki kemik arasındaki bağlantıyı sağlayan fibröz yapı.' },
  { q: 'Dalağın (spleen) görevi nedir?', a: ['Sindirim', 'Eski kırmızı kan hücrelerini süzmek ve bağışıklık desteği', 'İnsülin üretimi', 'Yağ depolamak'], c: 1, e: 'Dalak; yaşlı kırmızı kan hücrelerini ayırır, trombosit ve kan hücresini depolar, enfeksiyona karşı bağışıklık yanıtında görev alır.' },
  { q: '"Lenfatik sistem" neyi taşır?', a: ['Oksijen', 'Lenf sıvısı ve bağışıklık hücreleri', 'Sindirilmiş yağ ve bağışıklık hücreleri', 'Hormonlar'], c: 2, e: 'Lenfatik sistem; doku sıvısını (lenfi) toplayan, bağışıklık hücrelerini taşıyan ve bağırsaktan emilen yağ asitlerini dolaşıma katan ikincil dolaşım sistemidir.' },
  { q: 'İnsan beyninin yaklaşık ağırlığı nedir?', a: ['700 g', '1.400 g', '2.000 g', '3.000 g'], c: 1, e: 'Yetişkin insan beyni ortalama 1.400 g (1,4 kg) ağırlığındadır. Vücut ağırlığının %2\'sini oluşturmasına karşın toplam enerjinin %20\'sini tüketir.' },
  { q: '"Miyelin kılıf" ne işe yarar?', a: ['Kas güçlendirme', 'Sinir iletimini hızlandırır ve sinyali yalıtır', 'Kemik yapısı', 'Hücre zarı koruması'], c: 1, e: 'Miyelin, Schwann hücreleri tarafından oluşturulan yalıtkan kılıftır. Sinir impulsunu hızlandırarak iletimi yaklaşık 100 kat artırır. MS hastalığında miyelin hasar görür.' },
  { q: 'İnsanın kaç çift kranyal siniri vardır?', a: ['6', '10', '12', '16'], c: 2, e: 'Beyinden çıkan 12 çift kranyal sinir; koku, görme, göz hareketi, yüz duyusu-hareketi, işitme-denge ve iç organ fonksiyonlarını yönetir.' },
  { q: '"Perikardit" nedir?', a: ['Akciğer zarı iltihabı', 'Kalbi saran perikard zarının iltihabı', 'Karın zarı iltihabı', 'Beyin zarı iltihabı'], c: 1, e: 'Perikardit; kalbi saran iki katlı perikardum zarının iltihaplanmasıdır. Derin nefes alınca artan göğüs ağrısı tipik bulgusudur.' },
  { q: 'İnsan vücudunda kan üretimi nerede yapılır?', a: ['Dalak', 'Karaciğer', 'Kemik iliği', 'Böbrek'], c: 2, e: 'Kan hücreleri (kırmızı, beyaz ve trombositler) kemik iliğinde üretilir. Yetişkinde omurga, pelvis ve uzun kemiklerin iliği aktif üretim yapar.' },

  // Tıbbi Uzmanlıklar
  { q: '"Dermatoloji" hangi organla ilgilenir?', a: ['Kulak', 'Göz', 'Deri', 'Diş'], c: 2, e: 'Dermatoloji deri, saç ve tırnak hastalıklarını inceleyen tıp dalıdır. Egzama, akne, deri kanseri ve sedef hastalığı bu alanda ele alınır.' },
  { q: '"Gastroenteroloji" hangi sistemi inceler?', a: ['Kalp', 'Sindirim sistemi', 'Hormonal sistem', 'Solunum'], c: 1, e: 'Gastroenteroloji; yemek borusu, mide, ince-kalın bağırsak, karaciğer, safra kesesi ve pankreas hastalıklarını inceler.' },
  { q: '"Üroloji" hangi organlarla ilgilenir?', a: ['Beyin ve omurilik', 'İdrar yolları ve erkek üreme sistemi', 'Dişler', 'Göz ve kulak'], c: 1, e: 'Üroloji; böbrek, üreter, mesane, üretra ve erkek üreme organlarının (prostat, testis) hastalıklarını kapsar.' },
  { q: '"Romatoloji" hangi hastalıkları inceler?', a: ['Kanser', 'Ruh hastalıkları', 'Eklem, kas ve bağ dokusu hastalıkları (artrit, lupus)', 'Kalp hastalıkları'], c: 2, e: 'Romatoloji; romatoid artrit, lupus, gut, ankilozan spondilit gibi eklem, kas ve bağ dokusu hastalıklarını kapsayan tıp uzmanlığıdır.' },
  { q: '"Endokrinoloji" hangi sistemi inceler?', a: ['Sindirim', 'Solunum', 'Hormonal (endokrin) sistem', 'Sinir sistemi'], c: 2, e: 'Endokrinoloji; tiroit, paratiroit, hipofiz, böbreküstü bezi, pankreas ve over/testis gibi iç salgı bezlerinin hastalıklarını ele alır.' },
  { q: '"Psikiyatri" ile "Psikoloji" arasındaki temel fark nedir?', a: ['Aynı şeydir', 'Psikiyatristler tıp doktoru; ilaç yazabilir. Psikologlar ilaç yazamaz', 'Psikologlar ilaç yazar', 'Psikiyatri yalnızca çocukları inceler'], c: 1, e: 'Psikiyatristler tıp fakültesi mezunudur ve ilaç tedavisi uygulayabilir. Psikologlar psikoloji alanında lisans-doktora yapar; terapi uygular ama ilaç yazamaz.' },
  { q: '"Nefroloji" hangi organla ilgilenir?', a: ['Beyin', 'Akciğer', 'Böbrek', 'Karaciğer'], c: 2, e: 'Nefroloji; böbrek hastalıkları, diyaliz ve böbrek nakli alanlarını kapsayan dahiliye uzmanlık dalıdır.' },
  { q: '"Geriatri" hangi hasta grubunu inceler?', a: ['Çocuklar', 'Gençler', 'Yaşlılar', 'Hamileler'], c: 2, e: 'Geriatri; ileri yaş grubunun (genellikle 65+ yaş) sağlık sorunlarını ve bakımını kapsayan tıp dalıdır. Çoklu hastalık yönetimi ve yaşam kalitesi odağındadır.' },
  { q: '"Hematoloji" hangi sistemi inceler?', a: ['Sinir', 'Sindirim', 'Kan ve kan hücreleri', 'Kemik'], c: 2, e: 'Hematoloji; kan hücreleri, kemik iliği, lenf düğümleri ve dalakla ilgili hastalıkları (lösemi, anemi, pıhtılaşma bozuklukları) inceler.' },

  // Hastalıklar & Semptomlar
  { q: '"Romatoid artrit" ile "Osteoartrit" arasındaki fark nedir?', a: ['Aynı hastalıktır', 'Romatoid otoimmün; osteoartrit aşınma kaynaklıdır', 'Osteoartrit daha genç yaşta görülür', 'Romatoid yalnızca yaşlılarda'], c: 1, e: 'Romatoid artrit; bağışıklık sisteminin eklemlere saldırdığı otoimmün hastalıktır. Osteoartrit ise kıkırdağın zamanla aşınmasıyla oluşan dejeneratif eklem hastalığıdır.' },
  { q: '"KOAH" nedir?', a: ['Kalp krizi', 'Kronik Obstrüktif Akciğer Hastalığı', 'Karaciğer sirozu', 'Böbrek yetmezliği'], c: 1, e: 'KOAH (Kronik Obstrüktif Akciğer Hastalığı); kronik bronşit ve amfizemi kapsayan, hava akışını giderek kısıtlayan akciğer hastalığıdır. Sigaranın başlıca nedenidir.' },
  { q: '"Ateroskleroz" ne demektir?', a: ['Kalp büyümesi', 'Damar duvarlarında plak birikmesi ve sertleşmesi', 'Kalp kapak hastalığı', 'Kan incelemesi'], c: 1, e: 'Ateroskleroz; arterlerin iç duvarında kolesterol, yağ ve kalsiyumdan oluşan plakların birikmesiyle damarların daralıp sertleşmesidir. Kalp krizi ve inmenin temel nedenidir.' },
  { q: '"Siroz" hangi organı etkiler?', a: ['Böbrek', 'Karaciğer', 'Pankreas', 'Akciğer'], c: 1, e: 'Karaciğer sirozu; kronik hasar sonucu normal karaciğer dokusunun skar dokusuna dönüşmesidir. Alkol, hepatit B/C ve yağlı karaciğer başlıca nedenlerdir.' },
  { q: '"Hipotiroidizm" ne demektir?', a: ['Tiroit bezi aşırı çalışması', 'Tiroit bezi yetersiz çalışması', 'Tiroit kanseri', 'Tiroit iltihabı'], c: 1, e: 'Hipotiroidizm; tiroit bezinin yeterli hormon üretememesiyle metabolizmanın yavaşlamasıdır. Yorgunluk, kilo alımı ve soğuğa hassasiyet tipik belirtileridir.' },
  { q: '"Hipertiroidizm" hangi belirtilere yol açar?', a: ['Kilo alımı, yorgunluk', 'Kilo kaybı, çarpıntı, sinirlilik, terleme', 'Uyku fazlalığı', 'Kabızlık'], c: 1, e: 'Hipertiroidizm; tiroit bezinin aşırı hormon salgılamasıyla metabolizmanın hızlanmasıdır. Kilo kaybı, çarpıntı, titreme, aşırı terleme ve sinirlilik görülür.' },
  { q: '"Epilepsi" nedir?', a: ['Kas hastalığı', 'Beynin tekrarlayan anormal elektriksel deşarjlarından kaynaklanan nöbet hastalığı', 'Kemik hastalığı', 'Kalp ritim bozukluğu'], c: 1, e: 'Epilepsi; beyin nöronlarının anormal aşırı ve senkronize deşarjları sonucu tekrarlayan nöbetlerle seyreden kronik bir nörolojik hastalıktır.' },
  { q: '"Gut" hastalığı neden oluşur?', a: ['Kalsiyum eksikliği', 'Kanda ürik asit birikmesi ve eklemlere kristal çökmesi', 'Bakteri enfeksiyonu', 'Virüs'], c: 1, e: 'Gut; kanda ürik asit düzeyinin yükselmesiyle eklemlere (özellikle baş parmak) sodyum ürat kristallerinin çökmesi sonucu ani ve şiddetli ağrıyla seyreden hastalıktır.' },
  { q: '"Ülser" nedir?', a: ['Mide kanseri', 'Mide veya bağırsak mukozasında açık yara', 'Safra taşı', 'Fıtık'], c: 1, e: 'Peptik ülser; mide asidinin mukoza koruyucusunu aşmasıyla oluşan açık yaradır. H. pylori bakterisi ve NSAID kullanımı başlıca nedenlerdir.' },
  { q: '"Menenjit" nedir?', a: ['Beyin tümörü', 'Beyin ve omurilik çevresindeki zarların iltihabı', 'Epilepsi türü', 'İnme'], c: 1, e: 'Menenjit; beyin ve omuriliği saran meninksler adı verilen zarların enfeksiyon (bakteri, virüs) ya da diğer nedenlerle iltihaplanmasıdır. Ense sertliği, ateş ve fotofobi tipik bulgulardır.' },
  { q: '"Parkinson hastalığı"nın temel biyolojik nedeni nedir?', a: ['Serotonin eksikliği', 'Dopamin üreten nöronların kaybı', 'Asetilkolin fazlalığı', 'Adrenalen eksikliği'], c: 1, e: 'Parkinson; beyindeki substantia nigra bölgesindeki dopaminerjik nöronların ilerleyen kayбıyla oluşur. Titreme, rijidite, bradikinezi ve postural instabilite başlıca bulgulardır.' },
  { q: '"İBS" (İrritabl Bağırsak Sendromu) ne demektir?', a: ['Bağırsak kanseri', 'Kronik fonksiyonel bağırsak bozukluğu; karın ağrısı ve bağırsak alışkanlığı değişiklikleri', 'Crohn hastalığı', 'Kolit'], c: 1, e: 'İBS; belirgin bir yapısal bozukluk olmaksızın karın ağrısı, şişkinlik ve bağırsak alışkanlığı değişiklikleriyle seyreden kronik fonksiyonel gastrointestinal bozukluktur.' },
  { q: '"Pulmoner emboli" nedir?', a: ['Akciğer kanseri', 'Akciğer damarlarında kan pıhtısı tıkanması', 'Astım krizi', 'Pnömoni'], c: 1, e: 'Pulmoner emboli; çoğunlukla derin ven trombozundan kopan pıhtının akciğer atardamarlarını tıkamasıdır. Ani nefes darlığı, göğüs ağrısı ve hemoptizi tipik bulgulardır.' },
  { q: '"Aort anevrizması" nedir?', a: ['Kalp kapak hastalığı', 'Aort damarının anormal genişlemesi ve balon şeklinde şişmesi', 'Damar tıkanması', 'Kalp yetmezliği'], c: 1, e: 'Anevrizma; damar duvarının zayıflaması sonucu balonlaşmasıdır. Aort anevrizması yırtıldığında hayati tehlike oluşturan iç kanama yapar.' },
  { q: '"Skleroderma" hangi sistemi etkiler?', a: ['Sindirim', 'Bağ dokusu ve cilt; damarlar ve iç organlara da yayılabilir', 'Yalnızca cilt', 'Sinir sistemi'], c: 1, e: 'Skleroderma (sistemik skleroz); bağ dokusunun fibrozu ve küçük damar bozukluklarıyla seyreden otoimmün hastalıktır. Cilt sertleşmesi, Raynaud fenomeni ve iç organ tutulumu görülebilir.' },
  { q: '"Addison hastalığı" nedir?', a: ['Fazla kortizol', 'Böbreküstü bezlerinin yetersiz hormon üretimi (kortizol ve aldosteron eksikliği)', 'Tiroit yetmezliği', 'İnsülin direnci'], c: 1, e: 'Addison hastalığı; adrenal korteksin hasar görmesiyle kortizol ve aldosteron üretiminin azalmasıdır. Yorgunluk, hiperpigmentasyon, düşük tansiyon ve hiponatremi ile kendini gösterir.' },
  { q: '"Fibrilasyon" ne anlama gelir?', a: ['Çok hızlı düzenli kalp atışı', 'Düzensiz ve kaotik kalp atışı', 'Yavaş kalp atışı', 'Kalp durması'], c: 1, e: 'Fibrilasyon; kalp kaslarının koordinasyon olmadan kaotik çarpmasıdır. Atriyal fibrilasyon inme riskini artırır; ventriküler fibrilasyon ise kardiyak arrest nedenidir.' },
  { q: '"Ankilozan spondilit" hangi bölgeyi etkiler?', a: ['Eller', 'Omurga ve sakroiliak eklemler', 'Diz', 'Omuz'], c: 1, e: 'Ankilozan spondilit; esas olarak omurga ve sakroiliak eklemleri etkileyen kronik inflamatuvar artritik hastalıktır. İlerlemiş olgularda omurga kaynaşabilir ("bambu omurga").' },

  // Tedaviler & Prosedürler
  { q: '"Koroner anjiyografi" nedir?', a: ['Kalp ultrason', 'Kalp damarlarını görüntülemek için kateterle kontrast madde verilen işlem', 'EKG türü', 'Kalp nakli'], c: 1, e: 'Koroner anjiyografi; kasık ya da bilekten girilen kateter aracılığıyla koroner arterlere kontrast madde verilerek damar anatomisini ve tıkanıklıklarını gösteren görüntüleme yöntemidir.' },
  { q: '"Stent" nedir?', a: ['Ameliyat aleti', 'Dar veya tıkalı damara yerleştirilen metal kafes boru', 'Kalp kapağı', 'Kan pompası'], c: 1, e: 'Stent; darlık ya da tıkanma olan koroner ve periferik arterlere balon anjiyoplastiyle yerleştirilen metal kafes boru yapısıdır. Damarı açık tutar.' },
  { q: '"Bypass ameliyatı" ne anlama gelir?', a: ['Kalp nakli', 'Tıkalı koroner arterlerin etrafından yeni yol açma cerrahisi', 'Kalp kapağı değişimi', 'Ritim bozukluğu tedavisi'], c: 1, e: 'Koroner baypas; tıkalı koroner arterlerin etrafından damar grefti kullanarak alternatif kan yolu oluşturan açık kalp ameliyatıdır.' },
  { q: '"Radyoterapi" nasıl çalışır?', a: ['İlaçla', 'Yüksek enerjili radyasyon ile kanser hücrelerini hedef alarak hasar verir', 'Cerrahi ile', 'Bağışıklık sistemini aktive eder'], c: 1, e: 'Radyoterapi; DNA hasarı yaparak kanser hücrelerini öldürmek ya da büyümelerini durdurmak için yüksek enerjili iyonize radyasyon (X-ışını veya proton) kullanan tedavi yöntemidir.' },
  { q: '"İmmünoterapi" kanser tedavisinde nasıl çalışır?', a: ['Kanser hücresini doğrudan öldürür', 'Bağışıklık sistemini güçlendirerek kanser hücrelerini tanıyıp yok etmesini sağlar', 'Tümörü küçültür', 'Metastazı durdurur'], c: 1, e: 'İmmünoterapi; kontrol noktası inhibitörleri, CAR-T hücre tedavisi gibi yöntemlerle bağışıklık sistemini kanser hücrelerini tanıyacak şekilde yeniden programlar veya güçlendirir.' },
  { q: '"Fizik tedavi (FTR)" ne zaman uygulanır?', a: ['Yalnızca ameliyat sonrası', 'Hareket kısıtlılığı, ağrı ve işlev kaybını gidermek için çeşitli hastalık ve yaralanmalarda', 'Yalnızca spor yaralanmalarında', 'Yalnızca yaşlılarda'], c: 1, e: 'Fizik tedavi; egzersiz, elektroterapi, manuel terapi ve hidroterapi yöntemleriyle hareket sistemini, ağrıyı ve işlev kaybını ele alan koruyucu ve rehabilitatif bir tıp dalıdır.' },
  { q: '"Proton pompası inhibitörleri (PPI)" ne için kullanılır?', a: ['Ağrı kesici', 'Mide asidi üretimini azaltmak (gastrit, reflü, ülser)', 'Antibiyotik', 'Kolesterol düşürücü'], c: 1, e: 'PPI\'lar (omeprazol, pantoprazol vb.); mide pariyetal hücrelerindeki proton pompasını bloke ederek asit üretimini azaltır. Peptik ülser, GÖRH ve H. pylori tedavisinde kullanılır.' },
  { q: '"Kan transfüzyonu" hangi durumlarda yapılır?', a: ['Yalnızca ameliyatta', 'Ağır anemi, akut kan kaybı, trombosit eksikliği gibi durumlarda', 'Yalnızca kanserde', 'Yalnızca acil serviste'], c: 1, e: 'Kan transfüzyonu; ciddi anemi, akut hemoraji, trombositopeni veya pıhtılaşma faktörü eksikliğinde eksik bileşeni yenilemek amacıyla verilen tedavidir.' },
  { q: '"Kardiyoversiyon" nedir?', a: ['Kalp nakli', 'Kalp ritim bozukluğunu düzenlemek için kontrollü elektrik şoku', 'Anjiyoplasti', 'Bypass'], c: 1, e: 'Kardiyoversiyon; EKG ile senkronize verilen elektrik şokuyla atriyal fibrilasyon gibi ritim bozukluklarını normal sinüs ritmine döndürme işlemidir.' },
  { q: '"Otoimmün hastalık" ne anlama gelir?', a: ['Bulaşıcı hastalık', 'Bağışıklık sisteminin kendi dokularına saldırması', 'Genetik hastalık', 'Hormonal bozukluk'], c: 1, e: 'Otoimmün hastalıkta bağışıklık sistemi kendi vücudunu yabancı olarak algılayarak saldırır. Lupus, romatoid artrit, Hashimoto tiroiditi ve Tip 1 diyabet örneklerdir.' },
  { q: '"Derin beyin stimülasyonu" hangi hastalıkta kullanılır?', a: ['Alzheimer', 'Depresyon', 'Parkinson ve tedaviye dirençli tremor', 'İnme'], c: 2, e: 'DBS; beyne implante edilen elektrotlarla subtalanik çekirdeğe elektrik uyarımı vererek Parkinson titremesini ve rijiditesini azaltan cerrahi tedavi yöntemidir.' },

  // Farmakoloji & İlaçlar
  { q: '"Statin" ilaçları ne için kullanılır?', a: ['Kan basıncı düşürme', 'Kolesterol düşürme', 'Kan sulandırma', 'Şeker düşürme'], c: 1, e: 'Statinler; karaciğerde kolesterol sentezini engelleyen HMG-CoA redüktaz inhibitörleridir. LDL kolesterolü düşürerek kardiyovasküler riski azaltır.' },
  { q: '"Warfarin" hangi amaçla kullanılır?', a: ['Ağrı kesici', 'Kan sulandırıcı (antikoagülan)', 'Antibiyotik', 'Kolesterol düşürücü'], c: 1, e: 'Warfarin; K vitaminine bağımlı pıhtılaşma faktörlerini engelleyen oral antikoagülandır. Atriyal fibrilasyon ve derin ven trombozunda inme/emboli önlemek için kullanılır.' },
  { q: '"Morfin" hangi kategoride bir ilaçtır?', a: ['Antibiyotik', 'Opioid ağrı kesici', 'Antidepresan', 'Antihipertansif'], c: 1, e: 'Morfin; güçlü bir opioid analjeziktir. Merkezi sinir sistemindeki opioid reseptörlerine bağlanarak ağrı algısını azaltır. Bağımlılık potansiyeli yüksektir.' },
  { q: '"Adrenalin (Epinefrin)" hangi acil durumda kullanılır?', a: ['Hipertansiyon', 'Anafilaksi ve kardiyak arrest', 'Diyabet', 'Astım atağı (yalnızca)'], c: 1, e: 'Epinefrin; anafilakside ilk seçenek tedavidir. Kalp krizi ve kardiyak arrestte de kullanılır. Bronkodilatasyon, vazopresör etki ve kalp uyarımı sağlar.' },
  { q: '"Metformin" hangi hastalıkta kullanılır?', a: ['Hipertansiyon', 'Tip 2 diyabet', 'Astım', 'Romatoid artrit'], c: 1, e: 'Metformin; karaciğerde glukoz üretimini azaltan ve insülin duyarlılığını artıran en yaygın kullanılan Tip 2 diyabet ilacıdır.' },
  { q: '"Beta blokerler" nasıl çalışır?', a: ['Damarları genişletir', 'Kalp hızını ve kan basıncını düşürür; adrenalin etkisini bloke eder', 'İdrar söktürücüdür', 'Kolesterol düşürür'], c: 1, e: 'Beta blokerler; kalpteki beta-1 adrenerjik reseptörleri bloke ederek kalp hızını, kasılma gücünü ve kan basıncını düşürür. Hipertansiyon, aritmiler ve kalp yetmezliğinde kullanılır.' },
  { q: '"ACE inhibitörleri" ne işe yarar?', a: ['Ağrı keser', 'Kan basıncını düşürür; kalp ve böbreği korur', 'Kan inceltir', 'Kolesterol düşürür'], c: 1, e: 'ACE inhibitörleri (ramipril, lisinopril); anjiyotensin dönüştürücü enzimi bloke ederek kan basıncını düşürür ve kalp yetmezliği ile diabetik nefropatide koruyucu etki gösterir.' },
  { q: '"Diüretik" ilaçlar ne işe yarar?', a: ['Kalp hızlandırıcı', 'İdrar söktürür; vücuttaki fazla sıvıyı atar', 'Ağrı kesici', 'Antibiyotik'], c: 1, e: 'Diüretikler; böbreklerin su ve tuz atımını artırarak ödem, hipertansiyon ve kalp yetmezliği tedavisinde kullanılır. Furosemid (loop), hidroklorotiazid (tiazid) örneklerdir.' },
  { q: '"Kortikosteroid" ilaçlar ne için kullanılır?', a: ['Yalnızca astım için', 'Güçlü antiinflamatuvar ve bağışıklık baskılayıcı; astım, romatoloji, alerji ve otoimmün hastalıklarda', 'Yalnızca cilt için', 'Antibiyotik'], c: 1, e: 'Kortikosteroidler; inflamasyonu baskılayan ve bağışıklık sistemini düzenleyen güçlü ilaçlardır. Astım, alerjik reaksiyonlar, otoimmün hastalıklar ve organ naklinde kullanılır.' },

  // Tanı Yöntemleri
  { q: '"BT (Bilgisayarlı Tomografi)" ile "MRI" arasındaki temel fark nedir?', a: ['Aynıdır', 'BT X-ışını kullanır, kemik ve akut kanamada iyi; MRI manyetik alan kullanır, yumuşak doku görüntülemede üstün', 'MRI daha ucuzdur', 'BT daha uzun sürer'], c: 1, e: 'BT: X-ışınıyla hızlı görüntüleme yapar; kemik, akut kanama ve toraks-abdomende güçlü. MRI: Radyasyonsuz, uzun sürer; beyin, omurga, eklem ve yumuşak dokuyu daha iyi gösterir.' },
  { q: '"Troponin testi" ne için yapılır?', a: ['Böbrek yetmezliği', 'Kalp krizinin tanısında miyokardiyal hasar belirteci', 'Diyabet', 'Karaciğer hasarı'], c: 1, e: 'Troponin I ve T; kalp kasının hasara uğradığında kana karışan proteinlerdir. Akut miyokard enfarktüsünün en hassas ve spesifik belirtecidir.' },
  { q: '"Hemogram" testi ne gösterir?', a: ['Kan şekeri', 'Tam kan sayımı: kırmızı küre, beyaz küre, trombosit, hemoglobin değerleri', 'Kolesterol', 'Karaciğer enzimleri'], c: 1, e: 'Hemogram (tam kan sayımı); kırmızı küre (RBC), beyaz küre (WBC), trombosit, hemoglobin ve hematokrit gibi kan bileşenlerini ölçer. Anemi, enfeksiyon ve kan kanseri tanısında temel testtir.' },
  { q: '"Ultrasonografi (USG)" ne için kullanılır?', a: ['Yalnızca bebek takibi', 'Ses dalgalarıyla iç organları görüntülemek; karaciğer, böbrek, safra kesesi, hamilelik vb.', 'Yalnızca kalp için', 'Kemik incelemesi'], c: 1, e: 'Ultrasonografi; yüksek frekanslı ses dalgaları kullanarak iç organların gerçek zamanlı görüntülenmesini sağlar. Radyasyon içermez; hamilelik takibi, abdominal görüntüleme ve ekokardiyografide yaygındır.' },
  { q: '"PET tarama" ne için kullanılır?', a: ['Kemik grafisi', 'Metabolik aktiviteyi görüntüleyerek kanser yayılımı ve beyin aktivitesini değerlendirme', 'Kalp kasını inceleme', 'Akciğer enfarktüsü'], c: 1, e: 'PET (Pozitron Emisyon Tomografisi); radyoaktif glikoz ile yüksek metabolik aktiviteyi görüntüler. Kanser evrelemesi, beyin hastalıkları ve kalp perfüzyonunu değerlendirmede kullanılır.' },
  { q: '"Spirometri" hangi sistemi değerlendirir?', a: ['Kalp', 'Solunum fonksiyonu (FEV1, FVC)', 'Sinir sistemi', 'Böbrek'], c: 1, e: 'Spirometri; zorlu ekspirasyon hacmi (FEV1) ve zorlu vital kapasite (FVC) ölçümleriyle akciğer fonksiyonunu değerlendirir. KOAH ve astım tanısında standart testtir.' },
  { q: '"Elektromiografi (EMG)" ne ölçer?', a: ['Kalp elektriği', 'Beyin dalgaları', 'Kas ve sinir elektriksel aktivitesi', 'Göz hareketi'], c: 2, e: 'EMG; kasların ve onları kontrol eden sinirlerin elektriksel aktivitesini ölçer. Sinir sıkışmaları, kas hastalıkları (miyopati) ve ALS gibi nöromüsküler hastalıkların tanısında kullanılır.' },
  { q: '"Ekokardiyografi" nedir?', a: ['EKG testi', 'Ultrasonla kalbin yapı ve fonksiyonunu görüntüleme', 'Koroner anjiyografi', 'Kalp ritmi ölçümü'], c: 1, e: 'Ekokardiyografi; ultrason kullanarak kalp kapakları, odacık boyutları, kasılma gücü ve kan akışını gerçek zamanlı gösteren noninvaziv görüntüleme yöntemidir.' },

  // Enfeksiyon Hastalıkları & Bağışıklık
  { q: '"Grip" (influenza) ile "soğuk algınlığı" arasındaki fark nedir?', a: ['Aynı hastalıktır', 'Grip daha şiddetli; yüksek ateş, kas ağrısı ve ani başlangıçla seyreder', 'Soğuk algınlığı daha tehlikelidir', 'İkisinde de antibiyotik gerekir'], c: 1, e: 'Grip (influenza virüsü) ani yüksek ateş, şiddetli kas ağrısı ve güçsüzlükle başlar. Soğuk algınlığı (rhinovirus vb.) daha hafif, burun tıkanıklığı ağırlıklıdır.' },
  { q: '"Tüberküloz" nasıl bulaşır?', a: ['Yiyeceklerle', 'Hava yoluyla (damlacık ve aerosol)', 'Kan yoluyla', 'Temas yoluyla'], c: 1, e: 'Mycobacterium tuberculosis, enfekte kişinin öksürük ve hapşırmasıyla havaya karışan damlacık ve aerosol aracılığıyla solunum yoluyla bulaşır.' },
  { q: '"HIV" hangi hücreleri hedef alır?', a: ['Eritrositler', 'CD4+ T lenfositleri', 'Trombositler', 'Nötrofiller'], c: 1, e: 'HIV; bağışıklık sisteminin kilit hücreleri olan CD4+ T yardımcı lenfositlerine girerek çoğalır. Bu hücrelerin yıkımı bağışıklığı çökertir ve AIDS\'e zemin hazırlar.' },
  { q: '"Hepatit B" nasıl bulaşır?', a: ['Yalnızca hava yoluyla', 'Kan, cinsel temas ve anneden bebeğe', 'Yalnızca yiyecekle', 'Temas yoluyla'], c: 1, e: 'Hepatit B virüsü; enfekte kan, cinsel temas, kirli iğne paylaşımı ve doğum sırasında anneden bebeğe bulaşır. Aşısı mevcuttur; kronik hepaptit B sirozve karaciğer kanserine yol açabilir.' },
  { q: '"Malaria" (sıtma) hangi parazit nedeniyle oluşur?', a: ['Bakteri', 'Plasmodium paraziti', 'Virüs', 'Mantar'], c: 1, e: 'Sıtma; Anopheles sivrisineğinin ısırmasıyla insana geçen Plasmodium parazitinin kırmızı kan hücrelerini istila etmesiyle oluşan tropikal enfeksiyon hastalığıdır.' },
  { q: '"Aşı (Vaksin)" nasıl koruma sağlar?', a: ['Doğrudan virüsü öldürür', 'Bağışıklık sistemine antijen tanıtarak hafıza hücresi oluşturur', 'Antibiyotik etkisi yapar', 'Vücudu sertleştirir'], c: 1, e: 'Aşı; zayıflatılmış/öldürülmüş patojen ya da antijenik protein içererek bağışıklık sistemini uyarır. Gerçek enfeksiyona maruz kalınca hazır hafıza B ve T hücreleri hızlı yanıt verir.' },
  { q: '"Sepsis" için temel tedavi prensipleri nelerdir?', a: ['Yalnızca antibiyotik', 'Erken antibiyotik, sıvı resüsitasyon, kaynak kontrolü ve organ destek tedavisi', 'Yalnızca oksijen', 'Steroid tedavisi'], c: 1, e: 'Sepsis yönetiminin köşe taşları: tanı konur konmaz geniş spektrumlu antibiyotik başlanması, agresif IV sıvı resüsitasyonu, enfeksiyon odağının kontrolü ve gerekirse vazopresör/organ desteğidir.' },
  { q: '"MRSA" nedir?', a: ['Bir virüs', 'Metisiline dirençli Staphylococcus aureus; antibiyotiğe dirençli bakteri', 'Bir parazit', 'Bir mantar'], c: 1, e: 'MRSA (Metisiline Dirençli Staphylococcus aureus); penisilin ailesi antibiyotiklere dirençli bir bakteri türüdür. Hastane içi enfeksiyonların önemli nedenidir; tedavisi kısıtlı antibiyotiklerle yapılır.' },

  // Kadın-Çocuk Sağlığı
  { q: '"Eklampsi" nedir?', a: ['Gebelikte diyabet', 'Gebelikte yüksek tansiyon + nöbet (preeklampsinin ağır komplikasyonu)', 'Erken doğum', 'Gebelikte anemi'], c: 1, e: 'Eklampsi; preeklampsinin (gebelik hipertansiyonu + proteinüri) ağır komplikasyonudur. Nöbetlerin varlığıyla tanımlanır ve anne-bebek için ciddi tehlike oluşturur.' },
  { q: '"Gestasyonel diyabet" ne demektir?', a: ['Önceden var olan diyabet', 'Gebelik sürecinde ilk kez gelişen diyabet', 'Tip 1 diyabetin gebelikte kötüleşmesi', 'Yenidoğan diyabeti'], c: 1, e: 'Gestasyonel diyabet; gebelikte plasenta hormonlarının insülin direncini artırmasıyla gelişen, doğumdan sonra çoğunlukla düzelen diyabettir.' },
  { q: '"Apgar skoru" nedir?', a: ['Büyüme değerlendirmesi', 'Doğumdan hemen sonra yenidoğanın genel durumunu değerlendiren 5 kriterli puan sistemi', 'Prematüre testi', 'Zekâ ölçümü'], c: 1, e: 'Apgar skoru; doğumun 1. ve 5. dakikasında renk, kalp hızı, refleks, kas tonusu ve solunum değerlendirilerek 0-10 üzerinden verilen puandır. 7 ve üzeri normaldir.' },
  { q: '"Kistik fibrozis" hangi sistemi etkiler?', a: ['Yalnızca akciğer', 'Akciğer, sindirim sistemi ve terleme bezlerini etkileyen genetik hastalık', 'Yalnızca böbrek', 'Yalnızca karaciğer'], c: 1, e: 'Kistik fibrozis; CFTR genindeki mutasyonla aşırı kalın ve yapışkan mukus üretimine yol açan otozomal resesif genetik hastalıktır. Akciğer ve pankreası özellikle etkiler.' },
  { q: '"Fenilketonüri (PKU)" nedir?', a: ['Diyabet türü', 'Fenilalanini metabolize edemeyen genetik hastalık; diyet tedavisi gerektirir', 'Tiroit hastalığı', 'Kemik hastalığı'], c: 1, e: 'PKU; fenilalanin hidroksilaz eksikliğiyle fenilalaninin toksik biriktiği otozomal resesif bir aminoasit metabolizma bozukluğudur. Yenidoğan taramasıyla erken tanınır; diyet tedavisiyle beyin hasarı önlenir.' },

  // Ruh Sağlığı
  { q: '"Bipolar bozukluk" nasıl seyreder?', a: ['Yalnızca depresyon', 'Mani/hipomani ve depresyon dönemlerinin dönüşümlü yaşandığı ruh hali bozukluğu', 'Yalnızca öfke', 'Sanrılarla karakterize'], c: 1, e: 'Bipolar bozukluk; yüksek enerjili mani veya hipomani dönemleri ile depresyon dönemlerinin dönüşümlü yaşandığı kronik ruh hali bozukluğudur. Tip 1\'de tam mani, Tip 2\'de hipomani görülür.' },
  { q: '"Şizofreni"nin pozitif belirtileri nelerdir?', a: ['Duygu küntlüğü', 'Sanrı, varsanı (halüsinasyon) ve dağınık düşünce; işlevselliği olmayan abartılı belirtiler', 'Sosyal geri çekilme', 'İsteksizlik'], c: 1, e: 'Şizofreninin pozitif belirtileri: sanrılar (delüzyon), varsanılar (halüsinasyon, genellikle sesler), dağınık konuşma ve hezeyanlar. Negatif belirtiler ise duyarsızlık, avolisyon ve alojidir.' },
  { q: '"TSSB" (Travma Sonrası Stres Bozukluğu) nedir?', a: ['Kronik ağrı bozukluğu', 'Travmatik olaydan sonra uzun süre devam eden geri dönüşler, kaçınma ve aşırı uyarılmışlık', 'Panik bozukluk', 'Fobia'], c: 1, e: 'TSSB; ölüm tehdidi, ağır yaralanma veya cinsel saldırı gibi travmatik deneyimden sonra aylarca ya da yıllarca süren geri dönüşler, kaçınma davranışı, negatif biliş ve aşırı uyarılmışlık belirtileriyle seyreder.' },
  { q: '"Bilişsel Davranışçı Terapi (BDT)" ne üzerine odaklanır?', a: ['Çocukluk travması', 'Olumsuz düşünce kalıpları ve bunların davranış üzerindeki etkisini değiştirme', 'Bilinçdışı çatışmalar', 'İlaç tedavisi'], c: 1, e: 'BDT; otomatik olumsuz düşünceleri (bilişleri) tespit ederek daha işlevsel düşünce biçimlerine dönüştürmeyi ve bu sayede duygu-davranış örüntülerini değiştirmeyi hedefler.' },
  { q: '"Obsesif Kompulsif Bozukluk (OKB)" nedir?', a: ['Panik atak', 'Rahatsız edici takıntılı düşünceler ve bu düşüncelerden kurtulmak için tekrarlayan ritüeller', 'Fobia', 'Depresyon'], c: 1, e: 'OKB; kontrol edilemeyen obsesyonlar (rahatsız edici düşünceler) ve bunların yarattığı anksiyeteyi azaltmak için yapılan kompulsif (zorunlu) davranışlarla seyreden anksiyete bozukluğudur.' },

  // Beslenme & Koruyucu Tıp
  { q: 'Omega-3 yağ asitleri hangi sağlık yararlarıyla bilinir?', a: ['Kan şekerini düşürür', 'Kalp-damar sağlığı, beyin fonksiyonu ve inflamasyon azalması', 'Kilo verdirir', 'Kemik güçlendirir'], c: 1, e: 'Omega-3 (EPA, DHA, ALA); trigliseritleri düşürür, trombosit agregasyonunu azaltır, beyin gelişimine katkı sağlar ve antiinflamatuvar etki gösterir. Balık, ceviz ve keten tohumu iyi kaynaklardır.' },
  { q: '"İndeks vücut kitle indeksi (VKİ)" nasıl hesaplanır?', a: ['Boy × Ağırlık', 'Ağırlık (kg) / Boy² (m²)', 'Yaş × Ağırlık', 'Bel çevresi / Boy'], c: 1, e: 'VKİ = Ağırlık (kg) / Boy² (m²). VKİ 18,5-24,9 normal; 25-29,9 fazla kilolu; ≥30 obez olarak sınıflandırılır.' },
  { q: '"Kanser taraması"nın amacı nedir?', a: ['Kesin tanı koymak', 'Belirti vermeden önce erken evrede hastalığı saptamak', 'Tedavi etmek', 'Risk faktörlerini azaltmak'], c: 1, e: 'Tarama testleri (mamografi, kolonoskopi, PSA, Pap smear); hastalık henüz semptom vermeden erken evrede yakalamak, tedavinin başarısını artırmak ve mortaliteyi azaltmak amacıyla yapılır.' },
  { q: '"Hipertansiyonu önlemede" hangi diyet önerilir?', a: ['Keto diyeti', 'DASH diyeti (az tuz, bol meyve-sebze, düşük yağlı süt ürünleri)', 'Yüksek proteinli diyet', 'Intermittent fasting'], c: 1, e: 'DASH (Dietary Approaches to Stop Hypertension) diyeti; tuz, kırmızı et ve doymuş yağı kısıtlarken meyve, sebze, tam tahıl ve az yağlı süt ürünlerini öne çıkarır. Kan basıncını etkin düşürür.' },
  { q: '"Çinko" mineralinin bağışıklık sistemindeki rolü nedir?', a: ['Kemik yapımı', 'Lenfosit gelişimi, antikor üretimi ve yara iyileşmesi', 'Sinir iletimi', 'Enerji üretimi'], c: 1, e: 'Çinko; T lenfositlerinin olgunlaşması, doğal öldürücü hücre aktivitesi ve antikor üretiminde kritik rol oynar. Eksikliği bağışıklığı zayıflatır ve yara iyileşmesini yavaşlatır.' },
  { q: '"Meditasyon ve mindfulness" sağlığa nasıl katkı sağlar?', a: ['Yalnızca rahatlatır', 'Kortizol düşürür, anksiyete azaltır, odaklanmayı artırır, kan basıncını düşürebilir', 'Fiziksel egzersizin yerini alır', 'Yalnızca uyku için'], c: 1, e: 'Araştırmalar; düzenli meditasyonun kortizol düzeyini düşürdüğünü, anksiyete ve depresyonu azalttığını, bağışıklık fonksiyonunu iyileştirdiğini ve kan basıncını düşürebildiğini göstermektedir.' },

  // İlk Yardım
  { q: 'Kalp masajında (CPR) göğüse kaç kez baskı uygulanır?', a: ['10/dakika', '30 baskı/2 nefes döngüsü (100-120 baskı/dk)', '15 baskı/2 nefes', '50 baskı/5 nefes'], c: 1, e: 'Güncel AHA kılavuzlarına göre CPR; 30 göğüs baskısı + 2 kurtarma nefesi döngüsüyle 100-120 baskı/dakika hızında uygulanır.' },
  { q: '"Heimlich manevrası" ne için kullanılır?', a: ['Kalp krizi', 'Boğulma; yabancı cisim tıkanıklığını gidermek için karın bölgesine hızlı baskı', 'İnme', 'Düşme yaralanması'], c: 1, e: 'Heimlich manevrası; hava yoluna takılan yabancı cismi fırlatmak için karın üst kısmına arkadan uygulanan hızlı yukarı-içe baskıdan oluşur.' },
  { q: '"Şok" tıbbi anlamda ne demektir?', a: ['Psikolojik travma', 'Organlara yeterli kan perfüzyonunun sağlanamadığı, yaşamı tehdit eden dolaşım yetmezliği', 'Elektrik çarpması', 'Bayılma'], c: 1, e: 'Tıbbi şok; yetersiz doku perfüzyonu nedeniyle hücresel oksijen açığının ortaya çıktığı, tedavi edilmezse çoklu organ yetmezliğine yol açan akut yaşam tehlikesidir.' },
  { q: 'Burun kanamasında ilk yapılması gereken nedir?', a: ['Başı geri yana yatır', 'Başı öne eğ, burun yumuşak kısmına 10-15 dk baskı uygula', 'Buz koy', 'Ense soğut'], c: 1, e: 'Burun kanamasında başı hafifçe öne eğerek kanın yutulması önlenir; burunun yumuşak kısmı (kanatlar) 10-15 dakika sıkıştırılır. Başı geri yatırmak kanın gırtlaktan geçmesine neden olur.' },
  { q: '"Anafilaksi"de ilk müdahale nedir?', a: ['Antihistaminik ilaç', 'Epinefrin (adrenalin) enjeksiyonu, ardından 112 aranması', 'Steroid', 'Sıvı infüzyonu'], c: 1, e: 'Anafilaksi; hayati tehlikeli alerjik reaksiyondur. İlk ve en önemli tedavi uyluk kasına uygulatılan epinefrindir. Akabinde ambulans çağrılır ve hastane acil bakımı sağlanır.' },

  // Genel Tıbbi Bilgiler
  { q: '"Profilaksi" ne anlama gelir?', a: ['Hastalık tedavisi', 'Hastalığı önceden önlemek için yapılan uygulama', 'Tanı testi', 'İlaç dozu'], c: 1, e: 'Profilaksi; hastalığın oluşmasını önlemek amacıyla önceden alınan önlemlerdir. Aşılama, antibiyotik profilaksisi ve korunmalı cinsel ilişki örneklerdir.' },
  { q: '"Remisyon" ne anlama gelir?', a: ['Hastalığın nüks etmesi', 'Hastalık belirtilerinin azalması veya tamamen kaybolması', 'Hastanın ölmesi', 'İlaç değişikliği'], c: 1, e: 'Remisyon; kronik ya da kanser gibi ciddi hastalıklarda belirti ve bulguların kaybolması ya da kabul edilebilir düzeye inmesidir. Tam remisyon tespit edilebilir hastalık kalmaması demektir.' },
  { q: '"Kronik" ve "Akut" hastalık arasındaki fark nedir?', a: ['Kronık hafif, akut ağırdır', 'Kronik uzun süreli; akut kısa ve ani başlangıçlıdır', 'Aynı anlama gelir', 'Kronik bulaşıcı, akut değildir'], c: 1, e: 'Akut hastalık: ani başlar, kısa sürer (grip, apandisit). Kronik hastalık: uzun süre (≥3 ay) devam eder ve genellikle yavaş ilerler (diyabet, KOAH, hipertansiyon).' },
  { q: '"Morbidite" ne anlama gelir?', a: ['Ölüm oranı', 'Hastalık görülme sıklığı veya durumu', 'Hasta sayısı', 'Tedavi başarısı'], c: 1, e: 'Morbidite; bir hastalığın toplumdaki yaygınlığını veya kişideki hastalık durumunu ifade eder. Mortalite ise ölüm oranını belirtir.' },
  { q: '"Enflamasyon" belirtileri nelerdir?', a: ['Soğuma, solukluk', 'Kızarıklık, ısı artışı, şişlik, ağrı ve işlev kaybı', 'Uyuşma', 'Yalnızca ağrı'], c: 1, e: 'Klasik inflamasyon belirtileri (Celsus kriterleri): rubor (kızarıklık), calor (ısı artışı), tumor (şişlik), dolor (ağrı) ve functio laesa (işlev kaybı).' },
  { q: '"Prognoz" ne demektir?', a: ['Tanı', 'Tedavi planı', 'Hastalığın olası gidişatı ve sonucu hakkında tahmin', 'İlaç dozu'], c: 2, e: 'Prognoz; bir hastalığın tedaviyle ya da tedavisiz nasıl bir seyir izleyeceğine dair klinisyenin beklentisidir. "İyi prognoz" iyileşme olasılığının yüksek olduğunu gösterir.' },
  { q: '"Kontraendikasyon" ne anlama gelir?', a: ['İlaç dozu', 'Bir tedavinin uygulanmaması gereken durum veya kişi', 'Yan etki', 'İlaç etkileşimi'], c: 1, e: 'Kontraendikasyon; belirli bir tedavinin uygulanmasının zararlı ya da tehlikeli olduğu durum veya özelliktir. Örn: Aspirin kullanımının kontraendikasyonu aktif peptik ülserdir.' },
  { q: '"İatrojenik" ne demektir?', a: ['Hastadan kaynaklanan', 'Tıbbi müdahalenin neden olduğu istenmeyen etki ya da komplikasyon', 'İlaç alerjisi', 'Bakteri kaynaklı'], c: 1, e: 'İatrojenik; Yunanca "hekim" anlamındaki "iatros"tan gelir. Tıbbi müdahale, ilaç, ameliyat veya hastane bakımının neden olduğu istemeden oluşmuş zararı tanımlar.' },
  { q: '"Biyoavailabilite (Biyoyararlanım)" ne demektir?', a: ['İlacın gücü', 'Uygulanan ilacın sistemik dolaşıma ne kadarının ulaştığı', 'İlacın yan etkisi', 'İlacın fiyatı'], c: 1, e: 'Biyoyararlanım; uygulanan ilacın sistemik dolaşıma ulaşan ve aktif etkisini gösterebilen oranıdır. IV yol %100 biyoyararlanım sağlar; oral yolda karaciğer ilk geçiş etkisi bunu düşürebilir.' },
  { q: '"Plasebo etkisi" ne demektir?', a: ['İlaç yan etkisi', 'Gerçek ilaç içermeyen tedavinin psikolojik mekanizmayla semptom iyileştirmesi', 'Yanlış tanı', 'Nocebo etkisi'], c: 1, e: 'Plasebo etkisi; farmakolojik olarak aktif madde içermeyen tedavinin (şeker hapı, serum) hastanın inancı ve beklentisi aracılığıyla gerçek semptom iyileşmesi sağlamasıdır.' },
  { q: '"Pandemi" ile "Epidemi" arasındaki fark nedir?', a: ['Aynı anlama gelir', 'Epidemi bölgesel; pandemi uluslararası/küresel yayılım', 'Pandemi daha az kişiyi etkiler', 'Epidemi yalnızca tropikal'], c: 1, e: 'Epidemi: bir hastalığın belirli bölge/ülkede beklenenin üzerinde görülmesi. Pandemi: hastalığın birden fazla kıtaya yayılarak küresel ölçeğe ulaşması (örn. COVID-19).' },
  { q: '"Telemedicin (Uzaktan Tıp)" nedir?', a: ['Robot ameliyat', 'İnternet ve teknoloji aracılığıyla uzaktan tanı ve tedavi hizmetleri', 'Tıp eğitimi', 'İlaç üretimi'], c: 1, e: 'Telemedicin; video, telefon ve dijital platformlar aracılığıyla hasta ile sağlık profesyonelinin fiziksel temas olmadan konsültasyon, tanı ve takip yapabilmesini sağlar.' },
  { q: '"Klinik çalışma (Clinical trial)" neden önemlidir?', a: ['Yalnızca ilaç satışı için', 'Yeni tedavilerin güvenlik ve etkinliğini sistematik biçimde test etmek için', 'Yalnızca kanser için', 'Maliyet azaltmak için'], c: 1, e: 'Klinik çalışmalar; yeni ilaç, cihaz veya prosedürlerin güvenliğini ve etkinliğini randomize kontrollü yöntemlerle test eden bilimsel araştırmalardır. Düzenleyici onay için temel kanıt kaynağıdır.' },

  // ── TAMAMLAYICI SORULAR (355-500) ────────────────────────────────────

  // Anatomi & Organ Sistemleri Devam
  { q: 'Sindirim sistemi hangi organlardan oluşur?', a: ['Yalnızca mide', 'Ağız, yemek borusu, mide, ince-kalın bağırsak, karaciğer, pankreas', 'Yalnızca bağırsaklar', 'Mide ve karaciğer'], c: 1, e: 'Sindirim sistemi; ağız, yemek borusu, mide, ince bağırsak, kalın bağırsak ve yardımcı organlar (karaciğer, safra kesesi, pankreas) şeklinde birbirine bağlı bir sistemdir.' },
  { q: '"Pankreas" hangi iki temel görevi yerine getirir?', a: ['Kan üretmek ve toksin süzmek', 'Endokrin (insülin/glukagon) ve ekzokrin (sindirim enzimleri) işlev', 'Yalnızca insülin üretmek', 'Safra üretmek'], c: 1, e: 'Pankreas; endokrin işleviyle kan şekerini düzenleyen insülin ve glukagonu, ekzokrin işleviyle ise yağ, protein ve karbonhidratları sindiren enzimleri üretir.' },
  { q: 'Kırmızı kan hücrelerinin (eritrosit) ortalama ömrü nedir?', a: ['7 gün', '30 gün', '120 gün', '365 gün'], c: 2, e: 'Eritrositler yaklaşık 120 gün (4 ay) yaşar; ardından dalak ve karaciğerde parçalanır. Hemoglobindeki demir geri dönüştürülür.' },
  { q: 'İnce bağırsağın toplam uzunluğu yaklaşık kaçtır?', a: ['1-2 metre', '3-4 metre', '6-7 metre', '10 metre'], c: 2, e: 'İnce bağırsak yaklaşık 6-7 metre uzunluğundadır. Besinlerin sindirilip emildiği esas yerdir; yüzey alanı villus ve mikrovilluslarla büyük ölçüde artırılmıştır.' },
  { q: 'Terlemenin vücuttaki temel amacı nedir?', a: ['Atık atmak', 'Vücut sıcaklığını düzenlemek (termoregülasyon)', 'Deri nem dengesi', 'Elektrolit atımı'], c: 1, e: 'Ter bezleri; ısı stresi veya egzersiz sırasında terleme yoluyla buharlaşma soğutması sağlayarak vücut sıcaklığını normal sınırlarda tutar.' },
  { q: '"Refleks arkı" nedir?', a: ['Bilinçli düşünce yolu', 'Uyaran → duyusal sinir → refleks merkezi → motor sinir → yanıt zinciri', 'Beyin karar yolu', 'Hormonal yol'], c: 1, e: 'Refleks arkı; bilinçli işlemeden geçmeden uyarana hızlı yanıt veren sinirsel yol zinciridir. Diz refleksi (patella refleksi) klasik örneğidir.' },
  { q: '"Hormonal aksın" (HPA ekseni) işlevi nedir?', a: ['Üreme kontrolü', 'Hipotalamus-hipofiz-adrenal bezi ekseni; stres yanıtını koordine eder', 'Büyüme kontrolü', 'Tiroit kontrolü'], c: 1, e: 'HPA (Hipotalamus-Hipofiz-Adrenal) ekseni; strese yanıt olarak kortizol salgısını düzenleyen ana nöroendokrin sistemdir. Kronik aktivasyonu immün baskılanma ve metabolik bozukluklara yol açar.' },
  { q: 'Vücudun su-elektrolit dengesini hangi hormon düzenler?', a: ['İnsülin', 'ADH (antidiüretik hormon) ve aldosteron', 'Kortizol', 'Büyüme hormonu'], c: 1, e: 'ADH (vazopressin) böbreklerin su geri emilimini; aldosteron ise sodyum ve potasyum dengesini düzenler. İkisi birlikte kan hacmini ve osmolaliteyi korur.' },
  { q: 'İskelet kaslarının kasılması hangi iyona bağlıdır?', a: ['Sodyum', 'Potasyum', 'Kalsiyum', 'Magnezyum'], c: 2, e: 'Kasılma mekanizmasında kalsiyum iyonları troponin C\'ye bağlanarak aktin-miyozin etkileşimini başlatır. Kalsiyum sarkoplazmik retikulumdan salınır.' },
  { q: '"Ateriyel kan" ile "venöz kan" arasındaki fark nedir?', a: ['Renk farkı yoktur', 'Arteriyel kan oksijence zengin ve parlak kırmızı; venöz kan CO₂ yüklü ve koyu kırmızıdır', 'Venöz kan daha hızlıdır', 'Aynıdır'], c: 1, e: 'Arteriyel kan; akciğerlerden gelen oksijen yüklü, parlak kırmızı kandır. Venöz kan ise dokulara oksijeni verip karbondioksit alan koyu kırmızı kandır.' },

  // Farmakoloji Devam
  { q: '"Antifungal" ilaçlar ne için kullanılır?', a: ['Viral enfeksiyonlar', 'Mantar enfeksiyonları', 'Bakteri', 'Parazitler'], c: 1, e: 'Antifungaller; kandida, aspergillus gibi mantar enfeksiyonlarına karşı kullanılır. Flukonazol, itrakonazol ve amfoterisin B yaygın örneklerdir.' },
  { q: '"Antihistaminik" ilaçlar ne için kullanılır?', a: ['Ağrı kesici', 'Alerjik reaksiyonlarda histamin blokajı', 'Antibiyotik', 'Kolesterol'], c: 1, e: 'Antihistaminikler; alerjik rinit, kurdeşen, alerjik konjonktivit ve bazı mide sorunlarında histamin H1 veya H2 reseptörlerini bloke eder.' },
  { q: '"NSAİİ" (Nonsteroid Antiinflamatuvar İlaç) örnekleri nelerdir?', a: ['Penisilin, amoksisilin', 'İbuprofen, naproksen, diklofenak, aspirin', 'Morfin, kodein', 'Metformin, glipizid'], c: 1, e: 'NSAİİ\'lar; COX-1 ve COX-2 enzimlerini inhibe ederek prostaglandin sentezini azaltır. Ağrı, ateş ve inflamasyon tedavisinde kullanılır; uzun süreli kullanımda mide kanaması riski var.' },
  { q: '"Diazepam" hangi ilaç grubundadır?', a: ['Antibiyotik', 'Benzodiazepinler (anksiyolitik/sedatif)', 'Antidepresan', 'Antipsikotik'], c: 1, e: 'Diazepam bir benzodiazepindir; GABA reseptörlerini güçlendirerek anksiyete, kas spazmı ve epilepsi tedavisinde kullanılır. Bağımlılık potansiyeli yüksektir.' },
  { q: '"Tiyazid diüretikler" kanı nasıl etkiler?', a: ['Pıhtılaşmayı artırır', 'Sodyum-klor geri emilimini böbrekten azaltır; idrarla sıvı atımı sağlar', 'Kan şekerini düşürür', 'Kolesterol yükseltir'], c: 1, e: 'Tiyazid diüretikler; distal tüpten NaCl geri emilimini engelleyerek idrar yoluyla sodyum, su ve klor atımını artırır. Hipertansiyon ve ödem tedavisinde yaygın kullanılır.' },
  { q: '"İnhaler (Astım spreyi)" nasıl çalışır?', a: ['Bağışıklık güçlendirir', 'İlacı doğrudan hava yollarına ulaştırır; hızlı bronkodilatör etki', 'Kan yoluyla etki eder', 'Yavaş etkilidir'], c: 1, e: 'İnhaler; salbutamol gibi kısa etkili beta-2 agonistleri ya da kortikosteroidleri doğrudan bronş mukozasına ulaştırır. Sistemik yan etkileri oral yola göre çok daha azdır.' },
  { q: '"Heparin" ile "warfarin" arasındaki fark nedir?', a: ['Aynı etki mekanizması', 'Heparin IV/SC, hızlı etkili; warfarin oral, gecikmeli etkili antikoagülan', 'Heparin daha güçlü', 'Warfarin daha hızlı'], c: 1, e: 'Heparin; antitrombin III\'ü aktive ederek trombin ve Xa faktörünü inhibe eder, IV/SC uygulanır, etkisi hemen başlar. Warfarin; K vitaminine bağlı pıhtılaşma faktörlerini oral yoldan bloke eder, etkisi 2-5 günde ortaya çıkar.' },
  { q: '"Nitrat" ilaçları angina tedavisinde ne yapar?', a: ['Kalp hızını artırır', 'Venöz dilatasyon ve koroner dilatasyon ile kalbin yükünü azaltır', 'Kan pıhtılaştırır', 'Kolesterol düşürür'], c: 1, e: 'Nitrogliserin gibi organik nitratlar; NO salarak düz kasları gevşetir, venleri genişletir ve kalbe dönen kan hacmini azaltır. Koroner arterleri de genişleterek miyokardiyal oksijen dengesini iyileştirir.' },

  // Tıbbi Terimler & Latin/Yunanca Kökenler
  { q: '"Ante" ön eki tıpta ne anlama gelir?', a: ['Sonra', 'Karşı', 'Önce/ön', 'Altında'], c: 2, e: '"Ante" Latince "önce" demektir. Antepartum (doğum öncesi), antemortem (ölüm öncesi) gibi tıbbi terimlerde kullanılır.' },
  { q: '"Post" ön eki tıpta ne anlama gelir?', a: ['Önce', 'Sonra', 'Altında', 'Üstünde'], c: 1, e: '"Post" Latince "sonra" demektir. Postoperatif (ameliyat sonrası), postpartum (doğum sonrası) örneklerdir.' },
  { q: '"Hyper" ön eki ne anlama gelir?', a: ['Düşük/az', 'Yüksek/fazla/aşırı', 'Normal', 'Karşı'], c: 1, e: '"Hyper" Yunanca "üst/aşırı" demektir. Hipertansiyon (yüksek tansiyon), hiperglisemi (yüksek kan şekeri) örnekleridir.' },
  { q: '"Hypo" ön eki ne anlama gelir?', a: ['Yüksek', 'Düşük/az/yetersiz', 'Normal', 'Hızlı'], c: 1, e: '"Hypo" Yunanca "altında/az" demektir. Hipoglisemi (düşük kan şekeri), hipotansiyon (düşük tansiyon) örneklerdir.' },
  { q: '"-itis" son eki tıpta ne anlama gelir?', a: ['Tümör', 'İltihap/enflamasyon', 'Eksiklik', 'Ameliyat'], c: 1, e: '"-itis" son eki enflamasyonu belirtir: apandisit (apandiks iltihabı), sinüzit (sinüs iltihabı), artrit (eklem iltihabı).' },
  { q: '"-oma" son eki tıpta ne anlama gelir?', a: ['İltihap', 'Şişlik/tümör', 'Hastalık', 'Eksiklik'], c: 1, e: '"-oma" son eki çoğunlukla tümörü ifade eder: melanoma (deri tümörü), karsinoma (kanser tümörü), hematoma (kan birikmesi).' },
  { q: '"-ectomy" son eki ne anlama gelir?', a: ['İnceleme', 'Cerrahi çıkarma', 'Tamir', 'Görüntüleme'], c: 1, e: '"-ectomy" son eki cerrahi olarak çıkarmayı ifade eder: apendektomi (apandiks çıkarma), kolektomi (kolon çıkarma), mastektomi (meme çıkarma).' },
  { q: '"-scopy" son eki ne anlama gelir?', a: ['Ameliyat', 'Görsel inceleme (kamera ile)', 'İlaç tedavisi', 'Kan testi'], c: 1, e: '"-scopy" son eki optik araçla incelemeyi belirtir: kolonoskopi (kolon incelemesi), bronkoskopi (bronş incelemesi), laparoskopi (karın incelemesi).' },
  { q: '"Bilateral" ne anlama gelir?', a: ['Tek taraflı', 'Her iki tarafta', 'Üç taraflı', 'Merkezi'], c: 1, e: '"Bilateral" Latince iki taraf demektir. Bilateral pnömoni (her iki akciğerde) gibi kullanılır. Tek taraf için "unilateral" denir.' },
  { q: '"Idiopathic" (İdiyopatik) ne anlama gelir?', a: ['Genetik kaynaklı', 'Nedeni bilinmeyen', 'Bakteri kaynaklı', 'İlaç kaynaklı'], c: 1, e: '"İdiyopatik" terimi; nedeninin belirlenemediği hastalıklar için kullanılır. İdiyopatik Parkinson, idiyopatik epilepsi örneklerdir.' },
  { q: '"Benign" tümör ne demektir?', a: ['Yayılan kanser', 'Çevreye yayılmayan iyi huylu tümör', 'Kan tümörü', 'Beyin tümörü'], c: 1, e: 'Benign tümörler; yavaş büyür, etrafı sarar ama infilre etmez ve uzak organlara yayılmaz (metastaz yapmaz). Malign tümörler ise aksine invaziv ve metastatiktir.' },
  { q: '"Malign" tümör ne demektir?', a: ['İyi huylu', 'İnvaziv, hızlı büyüyen, metastaz yapabilen kötü huylu tümör', 'Yavaş büyüyen', 'Tedaviye yanıt veren'], c: 1, e: 'Malign (kötü huylu) tümörler; çevre dokuya infiltre olur, lenf ve kan yoluyla uzak organlara yayılır (metastaz). Bunlar kanser olarak tanımlanır.' },

  // Cinsel Sağlık & Üreme
  { q: '"Pap smear" testi ne için yapılır?', a: ['Meme kanseri taraması', 'Serviks (rahim ağzı) kanser taraması ve HPV tespiti', 'Yumurtalık kanseri', 'İdrar yolu testi'], c: 1, e: 'Pap smear; serviksteki anormal hücre değişikliklerini erken saptamaya yarayan jinekolojik tarama testidir. HPV ile ilişkili servikal kanserin erken tanısında kritiktir.' },
  { q: '"HPV" nedir?', a: ['Hepatit virüsü', 'İnsan Papilloma Virüsü; servikal kanser ve genital siğil nedeni', 'HIV türü', 'Herpes virüsü'], c: 1, e: 'HPV; cinsel temas yoluyla bulaşan, 100\'den fazla alt tipi olan virüstür. Yüksek riskli tipleri (16, 18) servikal kanser, orofarenks ve anal kansere yol açar. Aşısı mevcuttur.' },
  { q: '"Menopoz" kaç yaşında başlar?', a: ['30-35 yaş', '40-44 yaş', '45-55 yaş', '60 yaş'], c: 2, e: 'Menopoz; genellikle 45-55 yaşları arasında, ard arda 12 ay boyunca adet görülmemesiyle tanımlanır. Östrojen düşüşüyle birlikte sıcak basması, uyku bozukluğu ve kemik erimesi riski artar.' },
  { q: '"İnfertilite" (kısırlık) erkeklerde en sık hangi nedene bağlıdır?', a: ['Hormonal bozukluk', 'Sperm sayısı, hareketliliği veya morfolojisindeki sorunlar', 'Yalnızca genetik', 'Yalnızca enfeksiyon'], c: 1, e: 'Erkek infertilitesinin en yaygın nedeni oligospermi (düşük sperm sayısı), asteno spermi (düşük motilite) veya teratospermi (anormal morfoloji) ya da bunların bileşimidir.' },
  { q: '"Ektopik gebelik" nedir?', a: ['Çoğul gebelik', 'Döllenmis yumurtanın rahim dışında (çoğunlukla tüpte) gelişmesi', 'Erken doğum', 'Düşük tehdidi'], c: 1, e: 'Ektopik gebelik; fertilize yumurtanın endometrium yerine rahim dışında (fallop tüpü, over, karın) yerleşmesidir. Tüp rüptürü olursa iç kanama ve hayati tehlike oluşturur.' },

  // Çocuk Sağlığı
  { q: '"Neonatal sarılık" (yenidoğan sarılığı) neden oluşur?', a: ['Karaciğer hastalığı', 'Yenidoğanda bilirubin birikimi; olgunlaşmamış karaciğer işleviyle ilgili', 'Bakteri enfeksiyonu', 'Kan grubu uyumsuzluğu yalnızca'], c: 1, e: 'Fizyolojik neonatal sarılık; yenidoğanda kırmızı kürelerin parçalanmasıyla artan bilirubini olgunlaşmamış karaciğerin işleyememesi sonucu oluşur. Fototerapi ile tedavi edilir.' },
  { q: '"RSV" (Respiratuar Sinsityal Virüsü) hangi yaş grubunu etkiler?', a: ['Yalnızca yetişkinler', 'Özellikle 2 yaş altı bebekler ve immunsupreseler', 'Yalnızca okul çağı', 'Yalnızca yaşlılar'], c: 1, e: 'RSV; 2 yaş altı bebeklerde alt solunum yolu enfeksiyonu (bronşiyolit, pnömoni) yapan başlıca virüstür. Prematüre ve kardiyak anomalili bebeklerde ağır seyredebilir.' },
  { q: '"Otizm Spektrum Bozukluğu" hangi alanlarda güçlük yaratır?', a: ['Yalnızca konuşma', 'Sosyal iletişim, tekrarlayan davranışlar ve duyusal işlemleme', 'Yalnızca zeka', 'Yalnızca motor'], c: 1, e: 'OSD; sosyal etkileşim ve iletişimde güçlük, kısıtlı ilgi alanları, tekrarlayan davranışlar ve duyusal hassasiyetle seyreden nörogelişimsel bir spektrum bozukluğudur.' },
  { q: '"Dikkat Eksikliği Hiperaktivite Bozukluğu (DEHB)" nedir?', a: ['Zeka geriliği', 'Dikkat güçlüğü, aşırı hareketlilik ve dürtüsellikle seyreden nörogelişimsel bozukluk', 'Davranış bozukluğu yalnızca', 'Geçici çocukluk dönemi sorunu'], c: 1, e: 'DEHB; dikkat sürdürmekte güçlük, aşırı hareketlilik ve dürtüsellikle tanımlanan nörogelişimsel bir bozukluktur. Yetişkinliğe uzanabilir; farmakolojik ve davranışsal tedavi kombinasyonu etkilidir.' },

  // Yaşam Tarzı & Önleyici Tıp
  { q: 'Sigara içmenin kalp hastalığı riskine etkisi nedir?', a: ['Etkisi yok', 'Koroner arter hastalığı riskini 2-4 kat artırır', 'Yalnızca akciğeri etkiler', 'Düşük risk'], c: 1, e: 'Sigara; endotel hasarı, LDL oksidasyonu, HDL düşürme ve pıhtılaşma faktörlerini aktive ederek koroner arter hastalığı riskini 2-4 kat yükseltir. Bırakmak riski hızla azaltır.' },
  { q: 'Düzenli aerobik egzersizin kalp-damar sistemine etkisi nedir?', a: ['Tansiyon yükseltir', 'Kalp etkinliğini artırır, tansiyonu düşürür, LDL azaltır, HDL artırır', 'Zararlıdır', 'Yalnızca kilo kontrolü'], c: 1, e: 'Düzenli aerobik egzersiz; kardiyak debisi artırır, istirahat kalp hızını düşürür, kan basıncını azaltır, LDL\'i düşürüp HDL\'i yükseltir ve kardiyovasküler mortaliteyi belirgin azaltır.' },
  { q: 'Alkol tüketiminin karaciğere zararı nasıl başlar?', a: ['Doğrudan kanser', 'Yağlı karaciğer → alkolik hepatit → siroz silsilesi', 'Yalnızca akut toksisisite', 'Karaciğeri etkilemez'], c: 1, e: 'Kronik aşırı alkol; önce steatoz (yağlı karaciğer), ardından alkolik hepatit, siroz ve hepatosellüler karsinoma şeklinde ilerleyen karaciğer hasarına yol açar.' },
  { q: '"Medikal obezite" kriterleri nelerdir?', a: ['VKİ>25', 'VKİ≥30; veya bel çevresi erkekte>102 cm, kadında>88 cm', 'Yalnızca kilo', 'VKİ>35 yalnızca'], c: 1, e: 'Obezite; VKİ ≥30 kg/m² olarak tanımlanır. Santral obezite için bel çevresi erkekte >102 cm, kadında >88 cm eşik kabul edilir. Her iki ölçüm kardiyometabolik riski değerlendirmede kullanılır.' },
  { q: 'Uyku eksikliği hangi sağlık sorunlarına yol açar?', a: ['Yalnızca yorgunluk', 'Bağışıklık zayıflaması, obezite, diyabet, kardiyovasküler ve ruh sağlığı riskleri', 'Yalnızca kilo alımı', 'Geçici etki'], c: 1, e: 'Kronik uyku eksikliği; bağışıklık baskılanması, kortizol artışı, insülin direnci, hipertansiyon, depresyon ve bilişsel bozukluk risklerini artırır. Yetişkinlerde 7-9 saat uyku önerilir.' },
  { q: '"Bağırsak mikrobiyomu" genel sağlıkla nasıl ilişkilidir?', a: ['Yalnızca sindirim', 'Bağışıklık, beyin-bağırsak ekseni, metabolizma ve ruh halini etkiler', 'Yalnızca bağırsak', 'Önemi yoktur'], c: 1, e: 'Bağırsak mikrobiyomu; bağışıklık eğitimi, inflamasyon düzenlemesi, vitamin sentezi, bağırsak-beyin ekseni aracılığıyla ruh hali ve obezite/diyabete predispozisyon üzerinde etkilidir.' },

  // Onkoloji Detay
  { q: '"Tümör marker" nedir?', a: ['Tanı kesin koyar', 'Kanda yükselen, tümör varlığını ya da seyrini takip etmeye yardımcı biyokimyasal madde', 'Yalnızca genetik test', 'Görüntüleme testi'], c: 1, e: 'Tümör belirteçleri (PSA, CA-125, AFP, CEA gibi); kesin kanser tanısı koymaz, ancak takip, tedavi yanıtı ve nüks değerlendirmesinde yardımcı olur.' },
  { q: '"Metastaz" ne anlama gelir?', a: ['Tümörün küçülmesi', 'Kanser hücrelerinin orijinal tümörden uzak organlara yayılması', 'Tümör iltihabı', 'Tümörün iyi huylu olması'], c: 1, e: 'Metastaz; malign tümör hücrelerinin kan ya da lenf yoluyla uzak organlara ulaşarak orada ikincil tümörler oluşturmasıdır. İlerlemiş kanserin en önemli kötü prognostik faktörüdür.' },
  { q: '"Kemoterapi" hangi evrede en etkilidir?', a: ['Her zaman aynı etki', 'Erken evre veya yaygın (metastatik) hastalıkta bağlama ve ilaca göre değişir', 'Yalnızca son evre', 'Hiçbir evrede'], c: 1, e: 'Kemoterapinin etkinliği; kanser türüne, evreye, kemoterapi rejimine ve bireye göre değişir. Bazı kanserler erken evrede kemoterapiyle tamamen iyileşirken bazılarında palyatif amaçla kullanılır.' },
  { q: '"Lenfoma" ile "lösemi" arasındaki fark nedir?', a: ['Aynı hastalıktır', 'Lenfoma lenf dokusu kökenli katı tümör; lösemi kemik iliği kökenli kan kanseri', 'Lösemi katı tümördür', 'İkisi de kan kanseridir'], c: 1, e: 'Lösemi; kemik iliğinden kaynaklanan anormal beyaz küre üretimiyle seyreden kan kanseridir. Lenfoma ise lenfositlerin lenf düğümleri veya dalakta oluşturduğu katı tümördür.' },

  // Acil Tıp
  { q: '"Triaj" (ayıklama) acil serviste ne anlama gelir?', a: ['Ameliyat sırası', 'Hastaları aciliyet durumuna göre önceliklendirme', 'Tanı koyma süreci', 'İlaç listeleme'], c: 1, e: 'Triaj; kısıtlı kaynaklarla en fazla kişiyi kurtarmak amacıyla hastaları aciliyet derecesine göre kategorilere ayırma sistemidir. Acil servis ve afet yönetiminde kullanılır.' },
  { q: '"Hemorajik şok"ta vücut nasıl tepki verir?', a: ['Tansiyonu yükseltir', 'Taşikardi, vazokonstrüksüyon ve solunum hızlanmasıyla perfüzyonu korumaya çalışır', 'Kalp hızı düşer', 'Uyku eğilimi artar'], c: 1, e: 'Hemorajik şokta vücut; adrenalin salgısıyla kalp hızını ve kasılmayı artırır, periferik damarları daraltarak hayati organları korur. Telafi edilemezse organ yetmezliği gelişir.' },
  { q: '"Golden Hour" (Altın Saat) travmada neyi ifade eder?', a: ['Ameliyat süresi', 'Ciddi travmada ilk saatin mortaliteyi belirleyici kritik zaman dilimi olması', 'Yoğun bakım süresi', 'İlaç etkisi başlama süresi'], c: 1, e: 'Altın saat kavramı; ciddi travma vakalarında ilk saatte definitif tedaviye ulaşılmasının mortaliteyi dramatik biçimde azalttığını vurgular. Hava ambulansları ve travma merkezleri bu prensiple çalışır.' },
  { q: '"Defibrilasyon" hangi durumlarda uygulanır?', a: ['Yavaş kalp atışında', 'Ventriküler fibrilasyon ve nabızsız ventriküler taşikardide', 'Her kardiyak arrestte', 'Yalnızca hastanede'], c: 1, e: 'Defibrilasyon; kalbin düzensiz kaotik kasılmasını (VF/nabızsız VT) senkronize etmek için yüksek enerjili anlık elektrik şoku uygulamasıdır. AED cihazları kamuya açık alanlarda bu işlemi yapar.' },
  { q: '"Toksik şok sendromu" neden gelişir?', a: ['Alerji', 'Stafilokok ya da streptokok toksini nedeniyle ani sistemik inflamatuvar yanıt', 'Mantar enfeksiyonu', 'Viral enfeksiyon'], c: 1, e: 'Toksik şok sendromu; Staphylococcus aureus veya Streptococcus pyogenes\'in ürettiği süperantijenlerin bağışıklık sistemini aşırı aktive etmesiyle oluşan nadir ama hayati tehlikeli tablodur.' },

  // Genetik & Biyoteknoloji
  { q: '"Genetik mutasyon" ne anlama gelir?', a: ['Hücre ölümü', 'DNA dizisinde kalıcı değişiklik', 'Protein katlanması', 'Hücre bölünmesi'], c: 1, e: 'Mutasyon; DNA baz dizisindeki kalıcı değişikliktir. Noktasal mutasyon, delesyon veya insersiyon şeklinde olabilir. Kanserin temel mekanizmasını oluşturur.' },
  { q: '"CRISPR-Cas9" teknolojisi ne için kullanılır?', a: ['Görüntüleme', 'Hassas gen düzenlemesi; DNA\'nın belirli bölgesini kesip değiştirme', 'İlaç üretimi', 'Protein sentezi'], c: 1, e: 'CRISPR-Cas9; bakteri kaynaklı doğal bir immün sistem mekanizmasından geliştirilen, DNA\'yı belirli noktada kesen ve değiştiren devrimci gen düzenleme teknolojisidir.' },
  { q: '"Hücre klonlaması" ile "terapötik klonlama" arasındaki fark nedir?', a: ['Aynıdır', 'Terapötik klonlamada embriyo implante edilmez; kök hücre elde edilir', 'Terapötik klonlama yasaklıdır her yerde', 'Klonlama yalnızca hayvanlarda'], c: 1, e: 'Terapötik klonlama; hasta hücrelerinden hastalığı tedavi için uyumlu kök hücre elde etmeyi hedefler, embriyo büyütülmez. Üreme klonlaması ise embriyoyu büyüterek kopyalı birey oluşturmayı amaçlar.' },
  { q: '"Kök hücre tedavisi"nin potansiyel kullanım alanları nelerdir?', a: ['Yalnızca kan hastalıkları', 'Alzheimer, Parkinson, spinal yaralanma, diyabet ve kalp hastalıkları dahil geniş spektrum', 'Yalnızca kanser', 'Yalnızca ortopedi'], c: 1, e: 'Kök hücreler; sonsuz çoğalma ve farklı hücre tiplerine dönüşme kapasiteleriyle kan, nörolojik, kardiyak ve metabolik hastalıklar başta olmak üzere çok geniş bir tedavi potansiyeli taşır.' },
  { q: '"Gen terapisi" nasıl çalışır?', a: ['İlaç tedavisi', 'Hastalık yapan geni düzelterek veya yerine yeni gen koyarak hastalığı tedavi etme', 'Ameliyat', 'Kemoterapi'], c: 1, e: 'Gen terapisi; bozuk veya eksik geni düzeltmek, susturmak ya da yeni terapötik gen eklemek amacıyla viral vektörler veya lipid nanopartiküller kullanılarak yapılan tedavi yaklaşımıdır.' },

  // Epidemiyoloji & Halk Sağlığı
  { q: '"İnsidans" ile "prevalans" arasındaki fark nedir?', a: ['Aynı anlama gelir', 'İnsidans yeni vaka oranı; prevalans tüm mevcut vakalar', 'Prevalans yeni vaka oranı', 'İkisi de ölüm oranıdır'], c: 1, e: 'İnsidans: belirli bir sürede ortaya çıkan yeni vaka sayısı. Prevalans: belirli bir anda hastalıkla yaşayan toplam kişi sayısı. Kronik hastalıkta prevalans yüksekken insidans düşük olabilir.' },
  { q: '"Randomize Kontrollü Çalışma (RKÇ)" neden altın standart sayılır?', a: ['En ucuz yöntem', 'Rastgele gruplama ile seçim yanlılığını azaltır; nedensellik gösterilebilir', 'En hızlı yöntem', 'En kolay analiz'], c: 1, e: 'RKÇ\'de katılımcılar rastgele müdahale veya kontrol grubuna atanır. Bu; karıştırıcı faktörleri dengeler ve gözlenen farkın müdahaleden kaynaklandığına dair en güçlü kanıt sağlar.' },
  { q: '"Sürü bağışıklığı" ne anlama gelir?', a: ['Tüm nüfusu aşılamak', 'Yeterli oranda bağışık birey sayesinde hastalığın toplumda yayılamaması', 'Doğal bağışıklık', 'Kolektif tedavi'], c: 1, e: 'Sürü bağışıklığı; bir toplumun yeterli bir oranı bağışıklık kazandığında (aşı veya geçirilmiş hastalıkla) hastalığın yayılma zincirinin kırılmasıdır. Oran hastalıktan hastalığa değişir.' },
  { q: '"Karanlık bilgi" (Tacit knowledge) tıp eğitiminde ne ifade eder?', a: ['Gizli bilgi', 'Klinik deneyimle kazanılan, sözle tam aktarılamayan pratik yeti ve sezgi', 'Kitap bilgisi', 'Teorik bilgi'], c: 1, e: 'Tacit (örtük) bilgi; klinik tecrübeyle edinilen fizik muayene becerisi, klinik sezgi ve karar verme yetisi gibi doğrudan deneyim gerektiren ve metin aktarımı yetersiz kalan pratik bilgidir.' },
  { q: '"Tıbbi etik"te "özerklik" ilkesi ne anlama gelir?', a: ['Doktorun kararı', 'Hastanın kendi tedavisi hakkında bilgiye dayalı ve özgür karar verme hakkı', 'Ailenin kararı', 'Mahkeme kararı'], c: 1, e: 'Özerklik (otonomi) ilkesi; hastanın yeterli bilgilendirme sonrasında tedaviyi kabul etme ya da reddetme hakkını güvence altına alır. İnformed consent (aydınlatılmış onam) bu ilkenin pratik yansımasıdır.' },
  { q: '"Birinci basamak sağlık hizmeti" ne demektir?', a: ['Hastane acil servisi', 'Toplumda ilk temas noktası; aile hekimliği, koruyucu ve temel sağlık hizmetleri', 'Ameliyathane', 'Yoğun bakım'], c: 1, e: 'Birinci basamak; bireyin sağlık sistemiyle ilk temas kurduğu, aile hekimliği merkezli, koruyucu sağlık hizmetleri, aşılama, kronik hastalık yönetimi ve sevk koordinasyonunu kapsayan basamaktır.' },

  // ── SON TAMAMLAMA (420-500) ──────────────────────────────────────────
  { q: 'Ağız yoluyla alınan ilacın sindirim sisteminden geçip kana karışmasına ne denir?', a: ['Dağılım', 'Emilim (Absorpsiyon)', 'Metabolizma', 'Atılım'], c: 1, e: 'İlaç farmakokinetik döngüsü ADME\'dir: Absorpsiyon (emilim), Distribution (dağılım), Metabolism (metabolizma), Excretion (atılım). Oral ilaçlar ağırlıklı ince bağırsaktan emilir.' },
  { q: '"Yarı ömür" farmakolojide ne ifade eder?', a: ['İlacın bozulma süresi', 'Vücuttaki ilaç konsantrasyonunun yarıya inmesi için geçen süre', 'İlaç süresi', 'Etki başlama süresi'], c: 1, e: 'İlacın yarı ömrü (t½); plazmadaki ilaç miktarının yarıya düşmesi için geçen süredir. Dozaj aralığı ve steady state\'e ulaşma süresi için kritik parametredir.' },
  { q: 'Kalp yetmezliğinde "ejeksiyon fraksiyonu" ne ifade eder?', a: ['Kalp hızı', 'Her atışta ventriküldeki kanın ne kadarının pompalandığı (normal >%55)', 'Kan basıncı', 'Oksijen miktarı'], c: 1, e: 'Ejeksiyon fraksiyonu (EF); sol ventrikülün her atışta diastole sonunda içindeki kanın ne kadarını pompaladığını gösteren yüzdedir. EF<%40 sistolik kalp yetmezliği olarak kabul edilir.' },
  { q: '"Dispne" ne demektir?', a: ['Ağrı', 'Nefes darlığı/nefes almakta güçlük', 'Bulantı', 'Baş dönmesi'], c: 1, e: 'Dispne; kişinin nefes almakta güçlük çektiğini ya da yeterince nefes alamadığını hissettiği subjektif bir semptomdur. Kalp, akciğer, anemi ve anksiyete gibi pek çok nedeni olabilir.' },
  { q: '"Palpitasyon" ne demektir?', a: ['Karın ağrısı', 'Kalp atışının rahatsız edici şekilde farkına varılması', 'Kas spazmı', 'Baş ağrısı'], c: 1, e: 'Palpitasyon; kalbin hızlı, düzensiz ya da güçlü çarptığının rahatsız edici biçimde hissedilmesidir. Benign nedenleri (kafein, stres) olabileceği gibi aritmiye de işaret edebilir.' },
  { q: '"Siyonoz" ne demektir?', a: ['Sarılık', 'Deri ve mukozaların mavimtrak renk alması; oksijen yetersizliği', 'Kızarıklık', 'Solgunluk'], c: 1, e: 'Siyanoz; kandaki deoksijenize hemoglobin fazlasından kaynaklanan deri ve mukozaların mavi-mor renk almasıdır. Merkezi siyanoz akciğer/kalp sorununun, periferik siyanoz dolaşım bozukluğunun göstergesidir.' },
  { q: '"İkter" ne demektir?', a: ['Deri döküntüsü', 'Cildin, gözlerin ve mukozaların sararması (sarılık)', 'Ödem', 'Siyanoz'], c: 1, e: 'İkter (sarılık); kanda bilirubin birikimi sonucu cilt, sklera ve mukozaların sararmasıdır. Karaciğer hastalığı, safra kanalı tıkanması veya hemolitik anemi başlıca nedenleridir.' },
  { q: '"Asit" (karında sıvı birikimi) en sık hangi hastalıkla ilişkilidir?', a: ['Böbrek yetmezliği', 'Karaciğer sirozu', 'Kalp yetmezliği', 'Bağırsak hastalığı'], c: 1, e: 'Asit (peritoneal sıvı birikimi); vakaların %75\'inde karaciğer sirozu nedeniyledir. Kapı toplardamar hipertansiyonu ve albumin düşüklüğü başlıca mekanizmadır.' },
  { q: '"Ödeme" neden oluşur?', a: ['Sıvı azlığı', 'Doku aralarında aşırı sıvı birikmesi; kalp/böbrek yetmezliği, düşük albumin', 'Damar tıkanması', 'Enfeksiyon'], c: 1, e: 'Ödem; kapiller hidrostatik basınç artışı, onkotik basınç düşmesi (albumin azlığı), lenfatik tıkanma veya artan kapiller permeabilite nedeniyle dokuya aşırı sıvı sızmasıdır.' },
  { q: '"Oligüri" ne demektir?', a: ['Aşırı idrar', 'İdrar miktarının azalması (<400 mL/gün)', 'İdrar yokluğu', 'Ağrılı idrar'], c: 1, e: 'Oligüri; günlük idrar miktarının 400 mL\'nin altına düşmesidir. Böbrek yetmezliği, ciddi dehidrasyon veya şokun önemli bulgusudur. Anüri (<100 mL/gün) daha ağır formudur.' },
  { q: '"Ataksi" ne demektir?', a: ['Kas güçsüzlüğü', 'Koordinasyon ve denge bozukluğu; serebellar işlev bozukluğu', 'His kaybı', 'Görme bozukluğu'], c: 1, e: 'Ataksi; ağırlıklı olarak serebellar bozukluğa bağlı koordinasyon ve denge kaybıdır. Sendeleme, titrek el hareketleri (disdiadokokinezi) ve konuşma bozukluğu (dizartri) eşlik edebilir.' },
  { q: '"Afazi" ne demektir?', a: ['Konuşma organı paralizisi', 'Beyin hasarına bağlı dil anlama veya ifade etme bozukluğu', 'Ses kısıklığı', 'Işitme kaybı'], c: 1, e: 'Afazi; inme veya beyin hasarı sonucu konuşmayı anlama (Wernicke afazisi) ya da ifade etme (Broca afazisi) güçlüğüdür.' },
  { q: '"Paralizi" ile "parezi" arasındaki fark nedir?', a: ['Aynı anlama gelir', 'Paralizi tam hareket kaybı; parezi kısmi hareket zayıflığı', 'Parezi daha ağır', 'Paralizi yalnızca bacaklarda'], c: 1, e: 'Paralizi (pleji); bir bölgede tam motor işlev kaybıdır. Parezi ise kas gücünün azaldığı, hareketin hâlâ mümkün olduğu kısmi zayıflıktır.' },
  { q: '"Vertigo" ile "baş dönmesi" arasındaki fark nedir?', a: ['Aynıdır', 'Vertigo: çevre dönüyor hissi (vestibüler köken); baş dönmesi: daha genel dengesizlik hissi', 'Vertigo daha hafif', 'Baş dönmesi vestibüler'], c: 1, e: 'Vertigo; iç kulak veya santral vestibüler patolojiye bağlı çevrenin döndüğü yanılsamasıdır. Genel baş dönmesi ise dengesizlik veya sersemlik şikayetini kapsar; sebebi çok daha geniş yelpazededir.' },
  { q: '"Konjestif kalp yetmezliği"nde neden nefes darlığı olur?', a: ['Akciğer enfeksiyonu', 'Kalbin pompalama yetersizliği; akciğerlerde sıvı birikmesi (pulmoner ödem)', 'Bronkospazm', 'Kalp hızlanması'], c: 1, e: 'Konjestif KY\'de sol ventrikül yetmezliği akciğer venlerinde basınç artışına yol açar; bu sıvı akciğer alveoller içine sızarak gaz alışverişini bozar ve nefes darlığı oluşturur.' },
  { q: '"Anjina pektoris" ile "kalp krizi" arasındaki fark nedir?', a: ['Aynı hastalıktır', 'Angina: geçici iskemi, dinlenmede geçer; MI: kalıcı hasar ve nekroz', 'Angina daha ağırdır', 'MI dinlenmede geçer'], c: 1, e: 'Anjina; koroner akımın geçici yetersizliğiyle oluşan göğüs ağrısıdır, dinlenme veya nitritle geçer, hücre ölümü olmaz. Miyokard enfarktüsü (kalp krizi) ise kalıcı tıkanma ve miyokard nekrozuyla sonuçlanır.' },
  { q: '"Rabdomiyoliz" nedir?', a: ['Kemik erimesi', 'Kas hücrelerinin yıkımı; miyoglobin kana geçer, böbreğe zarar verebilir', 'Bağ dokusu hastalığı', 'Damar iltihabı'], c: 1, e: 'Rabdomiyoliz; iskelet kas hücrelerinin hasarlanarak miyoglobinin kana salınmasıdır. Miyoglobin böbrek tübüllerine zarar vererek akut böbrek yetmezliğine yol açabilir. Ezilme yaralanması, aşırı egzersiz ve bazı ilaçlar tetikleyebilir.' },
  { q: '"Anüri" ne demektir?', a: ['Az idrar', 'Günde 100 mL\'nin altında veya hiç idrar çıkmaması', 'İdrar renginin koyulaşması', 'İdrar yolu enfeksiyonu'], c: 1, e: 'Anüri; günlük idrar miktarının 100 mL\'nin altına düşmesidir. Ciddi böbrek yetmezliği, tam idrar yolu tıkanması veya ağır şokun işareti olabilir.' },
  { q: '"Hiperkalemi" neden tehlikelidir?', a: ['Kası zayıflatır yalnızca', 'Yüksek serum potasyumu; kardiyak ileti bozukluğu ve ölümcül aritmiye yol açabilir', 'Yalnızca yorgunluk', 'Sindirim sorunu'], c: 1, e: 'Hiperkalemi (yüksek serum K⁺); kardiyak ileti sistemini bozarak ventriküler fibrilasyon ve kardiyak arrest riski taşır. EKG\'de çadır şekilli T dalgaları erken bulgudur.' },
  { q: '"Periton diyalizi" ile "hemodiyaliz" arasındaki fark nedir?', a: ['Aynı yöntemdir', 'Hemodiyaliz: makineli kan filtrasyonu; periton diyalizi: karın zarı filtre olarak kullanılır', 'Periton daha etkili', 'Hemodiyaliz evde yapılır'], c: 1, e: 'Hemodiyaliz: kan vücut dışında diyaliz makinesinden geçirilerek filtre edilir. Periton diyalizi: diyaliz solüsyonu karın boşluğuna verilerek periton zarının geçirgenliğiyle atıklar alınır.' },
  { q: '"Transfüzyon reaksiyonu" belirtileri nelerdir?', a: ['Yalnızca kaşıntı', 'Ateş, titreme, bel ağrısı, hemoglobinüri; ağır vakada şok', 'Yalnızca döküntü', 'Baş ağrısı yalnızca'], c: 1, e: 'Akut hemolitik transfüzyon reaksiyonunda kan grubu uyumsuzluğu sonucu kırmızı hücreler yıkılır. Ateş, titreme, bel ağrısı, idrar koyulaşması (hemoglobinüri) ve şok görülebilir.' },
  { q: '"Sellülit" nedir?', a: ['Cilt altı yağ dokusu', 'Deri ve deri altı dokunun bakteriyel enfeksiyonu', 'Egzama türü', 'Deri kanseri'], c: 1, e: 'Sellülit; en sık Streptococcus ve Staphylococcus\'tan kaynaklanan, derinin derin katmanlarını tutan bakteriyel enfeksiyondur. Kızarıklık, sıcaklık, şişlik ve ağrı ile seyreder.' },
  { q: '"Abse" nedir?', a: ['Damar tıkanması', 'İçi irin dolu loküle doku enfeksiyonu; cerrahi drenaj gerektirir', 'Kemik enfeksiyonu', 'Deri yanığı'], c: 1, e: 'Abse; bir boşlukta toplanan irin (lökositler, ölü doku, bakteri) ile oluşan enfeksiyon odağıdır. Antibiyotik yanı sıra irin boşaltılması (drenaj) tedavinin temel bileşenidir.' },
  { q: '"Osteomiyelit" nedir?', a: ['Eklem iltihabı', 'Kemik dokusunun bakteriyel enfeksiyonu', 'Kas hastalığı', 'Bağ dokusu hastalığı'], c: 1, e: 'Osteomiyelit; kemik iliği ve kemik korteksinin genellikle Staphylococcus aureus kaynaklı bakteriyel enfeksiyonudur. Uzun süreli antibiyotik ve bazen cerrahi debridman gerektirir.' },
  { q: '"Gastrit" hangi etkenle en çok ilişkilendirilir?', a: ['Yalnızca stres', 'Helicobacter pylori bakterisi, NSAİİ kullanımı ve alkol', 'Yalnızca alerji', 'Yalnızca asit'], c: 1, e: 'H. pylori dünya nüfusunun ~%50\'sini etkileyen ve gastrit ile peptik ülserin en önemli etkenidir. NSAİİ\'lar ve alkol da mukozayı bozarak gastrite zemin hazırlar.' },
  { q: '"Kolesistit" nedir?', a: ['Karaciğer iltihabı', 'Safra kesesinin iltihabı; çoğunlukla safra taşına bağlı', 'Pankreatit', 'Bağırsak iltihabı'], c: 1, e: 'Kolesistit; safra kesesinin akut ya da kronik iltihabıdır. Vakaların %90\'ı safra taşı tıkanmasına bağlıdır. Sağ üst kadran ağrısı, ateş ve bulantı tipik tablosudur.' },
  { q: '"Pankreatit" en sık hangi iki nedene bağlıdır?', a: ['Stres ve alerji', 'Safra taşı ve alkol', 'Virüs ve bakteri', 'İlaç ve aşı'], c: 1, e: 'Akut pankreatitin %70-80\'i safra taşı tıkanması veya kronik alkol kullanımına bağlıdır. Şiddetli karın ağrısı, bulantı ve yüksek amilaz/lipaz seviyeleri karakteristiktir.' },
  { q: '"Crohn hastalığı" ile "ülseratif kolit" farkı nedir?', a: ['Aynıdır', 'Crohn tüm GİS\'i tutabilir, transmural; ülseratif kolit yalnızca kolonu tutar, mukozal', 'Ülseratif kolit daha yaygın bölge', 'Crohn yalnızca kalın bağırsak'], c: 1, e: 'Crohn; ağızdan anüse tüm GİS\'i tutabilen, atlamalı, transmural inflamasyondur. Ülseratif kolit; rektumdan sürekli uzanan, mukoza ile sınırlı kalın bağırsak hastalığıdır.' },
  { q: 'Diyabetik "ayak" neden bu kadar risklidir?', a: ['Yalnızca deri sorunu', 'Nöropati + damar bozukluğu; küçük yaralanmalar fark edilmeden enfekte olur, ampütasyon gerekebilir', 'Yalnızca dolaşım sorunu', 'Kemik kırıkları'], c: 1, e: 'Diyabetik ayakta periferik nöropati his kaybına, periferik damar hastalığı ise kötü yara iyileşmesine yol açar. Fark edilmeyen küçük yaralar hızla enfekte olarak gangrene ve ampütasyona neden olabilir.' },
  { q: '"Glomerülonefrit" nedir?', a: ['Böbrek taşı', 'Böbreğin glomerüllerini etkileyen inflamatuvar hastalık', 'Böbrek kanseri', 'İdrar yolu enfeksiyonu'], c: 1, e: 'Glomerülonefrit; böbreğin filtrasyon birimi olan glomerülleri etkileyen inflamasyon grubudur. İmmün kompleks birikimi, otoimmün hastalıklar veya post-enfeksiyöz nedenlerle oluşur; hematüri ve proteinüri görülür.' },
  { q: '"Ürolitiyazis" nedir?', a: ['Böbrek iltihabı', 'İdrar yollarında (böbrek, üreter, mesane) taş oluşumu', 'Mesane kanseri', 'İdrar yolu tıkanması'], c: 1, e: 'Ürolitiyazis; idrar yollarında kalsiyum oksalat, ürik asit, struvit veya sistin kristallerinden oluşan taşlardır. Kolik tarzında şiddetli bel ağrısı, hematüri ve bulantı tipik bulgulardır.' },
  { q: '"Skolyoz" nedir?', a: ['Bel fıtığı', 'Omurganın yana doğru anormal eğriliği', 'Boyun fıtığı', 'Kemik erimesi'], c: 1, e: 'Skolyoz; omurganın koronal planda >10° eğilmesidir. Adolesanlarda en yaygın formu idiyopatiktir. Hafif vakalar gözlemle, ağır vakalar (>45°) cerrahi ile tedavi edilir.' },
  { q: '"Kifoz" nedir?', a: ['Omurganın öne eğriliği (kambur)', 'Omurganın yana eğriliği', 'Disk fıtığı', 'Bel lordozu'], c: 0, e: 'Kifoz; torakal omurganın normalin üzerinde öne eğilerek kambur görünümü oluşturmasıdır. Postürel, Scheuermann hastalığı veya osteoporoza bağlı kırık nedeniyle gelişebilir.' },
  { q: '"Tendinit" nedir?', a: ['Eklem iltihabı', 'Tendon iltihabı; aşırı kullanım ve tekrarlayan hareketlerle oluşur', 'Kas yırtığı', 'Bağ iltihabı'], c: 1, e: 'Tendinit; tendonun mekanik aşırı yüklenmesine bağlı inflamasyon ve dejenerasyonudur. En sık omuz rotator kılıfı, Aşil tendonu ve lateral epikondilit (tenisçi dirseği) şeklinde görülür.' },
  { q: '"Karpal tünel sendromu" hangi siniri etkiler?', a: ['Ulnar sinir', 'Median sinir', 'Radyal sinir', 'Brakiyal pleksus'], c: 1, e: 'Karpal tünel sendromu; median sinirin bilekte karpal tünel içinde sıkışmasıyla başparmak, işaret ve orta parmakta uyuşma, yanma ve güçsüzlüğe yol açan sık görülen periferik nöropatidir.' },
  { q: '"Menisküs yırtığı" nerede olur?', a: ['Dirsek', 'Diz eklemindeki fibrokartilaj diskler', 'Kalça', 'Omuz'], c: 1, e: 'Menisküs yırtığı; dizin medial veya lateral fibrokartilaj disklerinde ani rotasyon veya yüklenmeden kaynaklanan hasar sonucu oluşur. Diz ağrısı, şişlik ve kilitlenme bulgusu tipiktir.' },
  { q: '"Bursit" nedir?', a: ['Kemik kırığı', 'Eklem çevresindeki yağ keselerinin (bursaların) iltihabı', 'Kas yırtığı', 'Sinir sıkışması'], c: 1, e: 'Bursit; eklem çevresindeki sürtünmeyi azaltan bursaların iltihabıdır. Tekrarlayan baskı veya enfeksiyon sonucu gelişir; en sık omuz, dirsek ve kalçada görülür.' },
  { q: '"Serebral palsi" nedir?', a: ['Dejeneratif beyin hastalığı', 'Erken beyin hasarına bağlı motor bozukluk; non-progresiftir', 'Genetik kas hastalığı', 'Epilepsi türü'], c: 1, e: 'Serebral palsi; gelişmekte olan beyinde hasar (prenatal, perinatal veya erken postnatal) sonucu oluşan ve ilerleyici olmayan motor işlev bozukluğudur. Spastisite, ataksi veya diskinezi şeklinde olabilir.' },
  { q: '"Multipl Skleroz (MS)" nedir?', a: ['Kas hastalığı', 'Merkezi sinir sisteminde miyelin hasarıyla seyreden otoimmün hastalık', 'Eklem hastalığı', 'Genetik sinir hastalığı'], c: 1, e: 'MS; bağışıklık sisteminin merkezi sinir sistemindeki miyelin kılıfına saldırdığı kronik otoimmün hastalıktır. Belirti ve nükslerin dalgalı seyriyle tipik olup görme bozukluğu, denge sorunu ve yorgunluk sık görülür.' },
  { q: '"Amiyotrofik lateral skleroz (ALS)" nedir?', a: ['Eklem hastalığı', 'Motor nöronların ilerleyici dejenerasyonuyla kas atrofisi ve felce yol açan ölümcül hastalık', 'Beyin tümörü', 'Kas iltihabı'], c: 1, e: 'ALS (Lou Gehrig hastalığı); üst ve alt motor nöronların ilerleyen kaybıyla kas güçsüzlüğü, atrofi ve nihayetinde solunum felcine yol açan nörodejeneratif hastalıktır.' },
  { q: '"Huntington hastalığı" nasıl kalıtılır?', a: ['Resesif', 'Otozomal dominant; bir kopyada mutasyon yeterlidir', 'X\'e bağlı', 'Mitokondriyal'], c: 1, e: 'Huntington otozomal dominant geçişlidir; etkilenmiş ebeveynin çocuğunun hastalığı alma olasılığı %50\'dir. HTT genindeki CAG tekrar uzaması bilişsel gerileme, hareket bozukluğu ve psikiyatrik belirtilere yol açar.' },
  { q: '"Miyastenia gravis" nedir?', a: ['Kas erimesi', 'Nöromüsküler kavşakta otoimmün blok; yorulmayla artan kas zayıflığı', 'Sinir iltihabı', 'Beyin hastalığı'], c: 1, e: 'Miyastenia gravis; asetilkolin reseptörlerine karşı oluşan otoantikorların nöromüsküler kavşakta iletimi bloke ettiği otoimmün hastalıktır. Göz kapağı düşüklüğü, çift görme ve çiğnemede güçlük sık görülür.' },
  { q: '"Wilson hastalığı" nedir?', a: ['Demir birikimine bağlı', 'Bakır metabolizmasının genetik bozukluğu; karaciğer ve beyin bakır birikimi', 'D vitamini eksikliği', 'Demir eksikliği'], c: 1, e: 'Wilson hastalığı; ATP7B genindeki mutasyona bağlı bakırın karaciğer, beyin, kornea ve böbrekte birikmesiyle seyreden otozomal resesif metabolik hastalıktır. Kayser-Fleischer halkası diagnostiktir.' },
  { q: '"Amiloidoz" nedir?', a: ['Protein eksikliği', 'Anormal katlanmış amiloid proteininin organlara birikmesi', 'Yağ birikimi', 'Mineral birikimi'], c: 1, e: 'Amiloidoz; çözünmez amiloid fibrillerinin böbrek, kalp, karaciğer ve sinir sistemine birikmesiyle çoklu organ yetmezliğine yol açan heterojen bir hastalık grubudur.' },
  { q: '"Sarkoidoz" hangi organı en sık etkiler?', a: ['Karaciğer', 'Akciğer ve lenf nodları', 'Böbrek', 'Kalp'], c: 1, e: 'Sarkoidoz; nedeni bilinmeyen granülamatöz inflamatuvar hastalıktır. Vakaların %90\'ında akciğer ve mediastinal lenf nodları tutulur; deri, göz, kalp ve sinir sistemi de etkilenebilir.' },
  { q: '"Talasemi" nedir?', a: ['Pıhtılaşma bozukluğu', 'Hemoglobin zinciri sentezindeki genetik bozukluk; hemolitik anemi', 'Demir eksikliği anemisi', 'Kanama bozukluğu'], c: 1, e: 'Talasemi; alfa veya beta globin zincirinin yetersiz sentezine yol açan otozomal resesif hemoglobinopatilerdir. Hemolitik anemi, orak hücre krizi ve demir yüklenmesi başlıca komplikasyonlardır.' },
  { q: '"Orak hücre anemisi" neden ağrılıdır?', a: ['Demir eksikliği', 'Orak şeklindeki kırmızı hücrelerin küçük damarlarda tıkanarak iskemi yapması', 'Kemik iliği baskılanması', 'Enfeksiyon'], c: 1, e: 'Orak hücre hastalığında mutant hemoglobin S; oksijensiz ortamda polimerizasyon yaparak hücreleri orak şekline sokar. Bu hücreler kılcal damarları tıkayarak ağrılı vaso-oklüzif kriz ve organ hasarına yol açar.' },
  { q: '"Hemofili" nedir?', a: ['Trombosit eksikliği', 'Pıhtılaşma faktörü eksikliği (VIII veya IX); aşırı kanamaya yol açan X\'e bağlı hastalık', 'Alyuvar bozukluğu', 'Kemik iliği yetmezliği'], c: 1, e: 'Hemofili; en sık faktör VIII (Hemofili A) veya IX (Hemofili B) eksikliğine bağlı X\'e bağlı resesif kalıtılan pıhtılaşma bozukluğudur. Eklem içi kanama (hemarthrosis) karakteristiktir.' },
  { q: '"İmmün trombositopeni (ITP)" nedir?', a: ['Kanama yetmezliği', 'Otoimmün trombosit yıkımı; düşük trombosit sayısı ve kanama riski', 'Lösemi türü', 'İlaç alerjisi'], c: 1, e: 'ITP; trombositlere karşı oluşan otoantikorların dalak tarafından trombositleri yok etmesine neden olduğu otoimmün hastalıktır. Peteşi, ekimoz ve kanama riski ile kendini gösterir.' },
  { q: '"Migren" ile "gerilim tipi baş ağrısı" farkı nedir?', a: ['Aynıdır', 'Migren tek taraflı, zonklayıcı, bulantı/ışığa hassasiyet ile; gerilim tipi bilateral, baskı hissi ile seyreder', 'Gerilim tipi daha ağırdır', 'Migren her zaman auralıdır'], c: 1, e: 'Migren: 4-72 saat süren, tek taraflı, zonklayan, bulantı ve fotofobi eşliğindeki orta-şiddetli ağrıdır. Gerilim tipi: bilateral, baskı hissi, hafif-orta şiddetli, günlük aktiviteyi belirgin etkilemez.' },
  { q: '"Epilepsi"de "status epileptikus" ne demektir?', a: ['Hafif nöbet', '5 dakikadan uzun süren veya arada bilincin açılmadığı art arda nöbetler; acil tedavi gerektirir', 'Kronik epilepsi', 'İlaç değişimi'], c: 1, e: 'Status epileptikus; 5 dakikayı aşan veya aralarında tam bilinç kazanılmayan art arda nöbetlerdir. Kalıcı beyin hasarı ve ölüm riski taşıdığından acil benzodiazepin ve ikinci basamak tedavisi zorunludur.' },
  { q: '"Beyin ölümü" nasıl tanımlanır?', a: ['Bilinç kaybı', 'Tüm beyin ve beyin sapı işlevlerinin geri dönüşümsüz kaybı; yasal olarak ölüm', 'Ağır koma', 'Kalp durması'], c: 1, e: 'Beyin ölümü; beyin korteksi ve beyin sapı dahil tüm beyin işlevlerinin klinik testler ve gerekirse EEG ile kanıtlanan geri dönüşümsüz kaybıdır. Yasal olarak ölüm sayılır ve organ bağışını mümkün kılar.' },
  { q: '"Organ nakli"nde "rejeksiyon" neden olur?', a: ['Ameliyat hatası', 'Alıcının bağışıklık sistemi donör organı yabancı kabul ederek saldırır', 'Kan grubu uyumsuzluğu yalnızca', 'İlaç etkileşimi'], c: 1, e: 'Organ reddi; alıcının T lenfositlerinin donörün HLA antijenlerini yabancı tanıyıp immün saldırı başlatmasıdır. İmmunosupresif tedavi (takrolimus, mikofenolat) reddı önlemek için ömür boyu sürer.' },
  { q: '"Palyatif sedasyon" nedir?', a: ['Anestezi', 'Tedaviye dirençli ağrı/semptomlarda bilinç düzeyini azaltarak rahatlama sağlama', 'Ötanazi', 'Uyku ilacı'], c: 1, e: 'Palyatif sedasyon; ağrı, nefes darlığı veya ajitasyon gibi tedaviye dirençli semptomların giderilmesi için terminal dönem hastanın bilinç düzeyinin tıbbi olarak azaltılmasıdır. Ötanaziden etik olarak ayrılır.' },
  { q: '"Biyoetik"te "yarar sağlama" (beneficence) ilkesi nedir?', a: ['Zarar vermemek', 'Hastanın çıkarına hizmet eden, yarar sağlayan eylemlerde bulunma yükümlülüğü', 'Özerkliğe saygı', 'Adalet'], c: 1, e: 'Beneficence; sağlık profesyonelinin hasta için aktif iyilik yapma, yararını maksimize etme yükümlülüğünü ifade eder. "Nonmaleficence" (zarar vermeme) ile birlikte tıp etiğinin temel ilkelerindendir.' },
  { q: '"Bütüncül (Holistik) tıp" anlayışı nedir?', a: ['Yalnızca ilaç tedavisi', 'Hastayı beden, zihin ve sosyal boyutlarıyla bir bütün olarak değerlendirme', 'Alternatif tıp', 'Spesiyalist bakım'], c: 1, e: 'Holistik tıp; hastalık yerine hastaya odaklanır. Biyolojik faktörlerin yanı sıra psikolojik, sosyal ve çevresel unsurları göz önünde bulundurarak kapsamlı değerlendirme ve tedaviyi esas alır.' },
  { q: '"Hekimin bildirme yükümlülüğü" hangi durumlarda geçerlidir?', a: ['Her hastalıkta', 'Bildirimi zorunlu bulaşıcı hastalıklarda ve adli vakalarda', 'Yalnızca ölümlerde', 'Yalnızca kanser'], c: 1, e: 'Hekimler; tüberküloz, HIV, koleralar gibi bildirimi zorunlu bulaşıcı hastalıkları, şüpheli adli vakaları (şiddet, zehirlenme) ve iş kazalarını ilgili makamlara bildirmekle yükümlüdür.' },

  { q: '"Hematüri" ne demektir?', a: ['İdrar azlığı', 'İdrarda kan bulunması', 'İdrar rengi açılması', 'İdrar yolu tıkanması'], c: 1, e: 'Hematüri; idrarda kırmızı kan hücreleri bulunmasıdır. Mikroskobik veya makroskobik olabilir. Böbrek taşı, enfeksiyon veya tümörün işareti olabilir.' },
  { q: '"Proteinüri" ne anlama gelir?', a: ['İdrarda şeker', 'İdrarda anormal miktarda protein bulunması', 'İdrarda bakteri', 'İdrarda kan'], c: 1, e: 'Proteinüri; böbreklerin filtrasyon barijerinin bozulması sonucu idrara protein sızmasıdır. Diyabetik nefropati, glomerülonefrit ve nefrotik sendromun önemli bulgusudur.' },
  { q: '"Nefrotik sendrom" hangi belirtilerle tanınır?', a: ['Yalnızca ödem', 'Masif proteinüri, hipoalbüminemi, ödem ve hiperlipidemi dörtlüsü', 'Yalnızca hipertansiyon', 'Hematüri ve tansiyon'], c: 1, e: 'Nefrotik sendrom; günde >3,5 g proteinüri, düşük albümin, ödem ve yüksek lipid dörtlüsüyle karakterizedir. Minimal change disease, fokal segmental glomerüloskleroz sık nedenleridir.' },
  { q: '"Renal Replasman Tedavisi" hangi durumda gerekir?', a: ['Hafif böbrek yetmezliği', 'Böbreklerin yaşamı sürdüremeyecek düzeyde işlevini yitirdiği son dönem böbrek yetmezliği', 'Sadece proteinüri', 'Sadece hipertansiyon'], c: 1, e: 'Diyaliz veya böbrek nakli; GFR <15 mL/dk ile son dönem böbrek yetmezliğinde sıvı, elektrolit ve atık dengesini sağlamak amacıyla uygulanır.' },
  { q: '"D vitamini eksikliği" çocuklarda hangi hastalığa yol açar?', a: ['Skorbüt', 'Raşitizm (kemik yumuşaması ve deformasyonu)', 'Pellagra', 'Beri-beri'], c: 1, e: 'D vitamini eksikliğinde kalsiyum-fosfor metabolizması bozulur; çocuklarda raşitizm (büyüme plağı defekti, bacak eğriliği), yetişkinlerde osteomalazi (kemik yumuşaması) görülür.' },
  { q: '"Magnezyum" vücutta hangi işlevlerde rol oynar?', a: ['Yalnızca kemik', 'Kas kasılması, sinir iletimi, enerji üretimi (ATP) ve 300\'den fazla enzim reaksiyonu', 'Yalnızca kan pıhtılaşması', 'Yalnızca sindirim'], c: 1, e: 'Magnezyum; ATP sentezi, protein sentezi, DNA onarımı, kas ve sinir işlevi için vazgeçilmezdir. Eksikliği kas krampları, aritmiler ve insülin direnciyle ilişkilidir.' },
  { q: '"C-reaktif protein (CRP)" nedir?', a: ['Kanser belirteci', 'İnflamasyonun akut faz reaktanı; enfeksiyon ve doku hasarında yükselir', 'Kolesterol', 'Kan şekeri'], c: 1, e: 'CRP; karaciğerde üretilen ve inflamasyon, enfeksiyon ile doku hasarında kanda hızla yükselen akut faz reaktanıdır. Enflamatuvar hastalık takibinde ve kardiyovasküler risk değerlendirmesinde kullanılır.' },
  { q: '"D-dimer" testi ne için yapılır?', a: ['Anemi', 'Derin ven trombozu ve pulmoner emboli olasılığını değerlendirmek', 'Karaciğer hastalığı', 'Böbrek yetmezliği'], c: 1, e: 'D-dimer; pıhtı çözülmesi sırasında ortaya çıkan fibrin parçacığıdır. Yüksek hassasiyeti nedeniyle DVT/PE dışlama testinde kullanılır; düşük D-dimer tromboemboliyi büyük ölçüde dışlar.' },
  { q: '"HbA1c" testi ne için yapılır?', a: ['Anlık kan şekeri', 'Son 2-3 ayın ortalama kan şekeri kontrolü; diyabet yönetiminde altın standart', 'İnsülin düzeyi', 'Kolesterol'], c: 1, e: 'HbA1c (glikozillenmiş hemoglobin); kırmızı kürelerin 2-3 aylık ömrü boyunca hemoglobine bağlanan glikoz oranını gösterir. Diyabet tanısı (≥%6,5) ve tedavi takibinde standart test.' },
  { q: '"TSH" testi ne gösterir?', a: ['Tansiyon', 'Tiroit bezi işlevini değerlendiren hipofiz hormonu düzeyi', 'Böbrek fonksiyonu', 'Şeker'], c: 1, e: 'TSH (Tiroit Stimüle Edici Hormon); tiroit bezi işlevini değerlendiren en hassas testtir. Yüksek TSH hipotiroidizmi, düşük TSH hipertiroidizmi işaret eder.' },
  { q: '"ALT" ve "AST" enzimleri neden ölçülür?', a: ['Böbrek hasarı', 'Karaciğer hasarı ve işlev bozukluğu', 'Kas hasarı yalnızca', 'Kalp hasarı yalnızca'], c: 1, e: 'ALT (Alanin Aminotransferaz) ve AST (Aspartat Aminotransferaz); karaciğer hücre hasarında kana sızan enzimlerdir. Hepatit, siroz ve ilaç toksisitesi tanısında kullanılır.' },
  { q: '"BUN (Kan Üre Azotu)" neden ölçülür?', a: ['Karaciğer fonksiyonu', 'Böbrek fonksiyonu ve protein metabolizması değerlendirmesi', 'Kan şekeri', 'Oksijen taşıma kapasitesi'], c: 1, e: 'BUN; karaciğerde protein metabolizması sonucu oluşan ürenin böbrekler tarafından atılımını yansıtır. Böbrek yetmezliğinde yükselir; kreatinin ile birlikte değerlendirilir.' },
  { q: 'Serum "kreatinin" yüksekliği ne anlama gelir?', a: ['Protein fazlalığı', 'Böbrek filtrasyon kapasitesinin azaldığını gösterir', 'Karaciğer hasarı', 'Kasların güçsüzlüğü'], c: 1, e: 'Kreatinin kas metabolizmasından oluşur ve böbreklerce sabit hızda filtre edilir. Serum kreatinin yükselmesi böbreğin filtrasyon kapasitesinin bozulduğuna işaret eder.' },
  { q: '"INR" (International Normalized Ratio) neden ölçülür?', a: ['Anemi takibi', 'Pıhtılaşma süresi ve antikoagülan ilaç (warfarin) yönetimi', 'Trombosit sayımı', 'Kan şekeri'], c: 1, e: 'INR; protrombin zamanının standartlaştırılmış biçimidir. Warfarin gibi antikoagülan tedaviyi izlemede ve karaciğer sentez kapasitesini değerlendirmede kullanılır.' },
  { q: '"Serum albumin" düşüklüğü neye işaret eder?', a: ['Yüksek protein alımı', 'Yetersiz beslenme, karaciğer hastalığı, kronik inflamasyon veya nefrotik sendrom', 'Böbrek taşı', 'Kan sulandırıcı kullanımı'], c: 1, e: 'Albümin karaciğer tarafından üretilir; düşük düzey yetersiz beslenme, karaciğer yetmezliği, kronik inflamasyon ya da idrarla aşırı kayıp (nefrotik sendrom) sonucunda oluşur.' },
  { q: 'Kan gazı analizinde "pH 7,4" ne ifade eder?', a: ['Asidoz', 'Normal fizyolojik pH', 'Alkaloz', 'Hipoksi'], c: 1, e: 'Normal kan pH\'ı 7,35-7,45 arasındadır. 7,4 tam orta değerdir. pH<7,35 asidoz (asit fazlalığı), pH>7,45 alkaloz (baz fazlalığı) anlamına gelir.' },
  { q: '"Puls oksimetresi (SpO₂)" neyi ölçer?', a: ['Kalp hızı yalnızca', 'Kandaki oksijen saturasyonu', 'Kan basıncı', 'Solunum hızı'], c: 1, e: 'Nabız oksimetresi; parmak ucuna yerleştirilen sensörle kırmızı ve kızılötesi ışık kullanarak hemoglobinin oksijen bağlama yüzdesini (SpO₂) noninvaziv ölçer. Normal >%95\'tir.' },
  { q: '"Kapiller geri dolum zamanı" neden değerlendirilir?', a: ['Böbrek fonksiyonu', 'Periferik dolaşımı değerlendirmek; >2 saniye dolaşım yetmezliğine işaret eder', 'Akciğer kapasitesi', 'Sinir iletimi'], c: 1, e: 'Kapiller geri dolum zamanı; tırnağa baskı uygulanıp bırakıldıktan sonra normal pembe rengin geri dönme süresidir. >2 saniye gecikme azalmış perfüzyonun klinik bulgusudur.' },
  { q: '"GFR (Glomerüler Filtrasyon Hızı)" böbrek sağlığında neyi gösterir?', a: ['İdrar üretimi', 'Böbreklerin dakikada süzebileceği kan miktarını; böbrek fonksiyonunun altın standardı', 'Protein atılımı', 'Elektrolit dengesi'], c: 1, e: 'GFR; her iki böbreğin glomerüllerinin dakikada filtrelediği plazma hacmini gösterir. Normal >90 mL/dk; kronik böbrek hastalığı sınıflamasında temel parametredir.' },
  { q: 'İlaçların böbrekte atılımını etkileyen temel faktör nedir?', a: ['Yaş yalnızca', 'GFR; böbrek fonksiyon bozukluğunda ilaç dozu GFR\'e göre ayarlanmalıdır', 'Karaciğer işlevi', 'Vücut ağırlığı'], c: 1, e: 'Böbrekten atılan ilaçların dozu GFR\'e göre belirlenir. Böbrek yetmezliğinde atılım yavaşlayarak ilaç birikimi ve toksisiteye yol açabilir; doz ayarı zorunludur.' },
  { q: '"Entübasyon" nedir?', a: ['İlaç verilmesi', 'Hava yolunu açmak için trakeaya tüp yerleştirme', 'Damar içi sıvı', 'Cerrahi kesi'], c: 1, e: 'Endotrakeal entübasyon; ağız ya da burundan laringoskop yardımıyla trakeaya tüp yerleştirerek mekanik ventilasyon sağlayan veya hava yolunu güvence altına alan işlemdir.' },
  { q: '"Trakeostomi" ne için açılır?', a: ['Anestezi', 'Uzun süreli mekanik ventilasyon ya da üst hava yolu tıkanıklığında solunum güzergahı açmak', 'Kan alma', 'İlaç verilmesi'], c: 1, e: 'Trakeostomi; boyundan trakeaya açılan cerrahi ya da perkütan deliktir. Uzun süreli mekanik ventilasyon, üst hava yolu tıkanıklığı ve uzamış yoğun bakım ihtiyacında uygulanır.' },
  { q: '"Dekübitus yarası" (bası yarası) neden oluşur?', a: ['Cilt enfeksiyonu', 'Uzun süreli baskı sonucu doku iskemisi ve nekroz', 'Cerrahi kesisi', 'Alerji'], c: 1, e: 'Dekübitus yaraları; hareketsiz hastalarda kemik çıkıntıları üzerindeki dokuya uzun süreli baskı sonucu kan akımının kesilmesiyle oluşan doku hasarıdır. Sakrum, topuk ve kalça en sık bölgelerdir.' },
  { q: '"Oksijen terapisi" hangi durumda endikedir?', a: ['Baş ağrısı', 'SpO₂ <90% veya PaO₂ <60 mmHg; hipoksemi', 'Hipertansiyon', 'Ateş'], c: 1, e: 'Oksijen tedavisi; SpO₂\'nin %90\'ın altına düştüğü ya da arteryal oksijen basıncının 60 mmHg\'nin altında olduğu hipoksemi durumunda endikedir. KOAH\'ta dikkatli kullanım gerekir.' },


  // ── Vay Be! Soruları ──
  { q: 'İnsan vücudunda kaç hücre bulunur?', a: ['1 milyar', '1 trilyon', '37 trilyon+', '1 katrilyon'], c: 2, d: 1, vb: true, e: 'Güncel tahminlere göre insan vücudu yaklaşık 37,2 trilyon hücreden oluşur. İlginç olan: vücudumuzdaki bakteri sayısı bu hücre sayısına eşit ya da daha fazladır.' },
  { q: 'Mide asidi ne kadar güçlüdür?', a: ['Hafif asit; zararsız', 'pH 1-2; metal çözebilecek kadar güçlü', 'Sütün asitliği kadar', 'pH 5-6'], c: 1, d: 2, vb: true, e: 'Mide asidi (hidroklorik asit) pH 1-2 düzeyinde olup çinkoyu çözebilecek kadar güçlüdür. Mide duvarı, kalın mukus katmanı sayesinde bu asitten korunur; midenin dış yüzeyine temas eden aynı asit ciddi hasar yaratır.' },
  { q: 'Beyin vücut ağırlığının yüzde kaçı olmasına karşın enerji tüketimi nedir?', a: ['%50 ağırlık, %10 enerji', '%2 ağırlık, %20 enerji tüketir', '%5 ağırlık, %30 enerji', '%10 ağırlık, %50 enerji'], c: 1, d: 2, vb: true, e: 'İnsan beyni vücut ağırlığının yalnızca %2\'sini oluştururken vücudun toplam enerji tüketiminin yaklaşık %20\'sini karşılar. Dinlenme sırasında bile beyin kaslardan daha fazla glikoz tüketir.' },
  { q: 'Yeni doğan bir bebekte kemik sayısı yetişkine göre fazla mıdır?', a: ['Aynı (206)', 'Daha az (150)', 'Daha fazla (~270-300); kaynaşarak yetişkinde 206\'ya düşer', '206\'dan fazla değil'], c: 2, d: 2, vb: true, e: 'Yeni doğanlarda ~270-300 kemik bulunurken yetişkinlerde bu sayı 206\'ya düşer. Büyüme sürecinde kıkırdak yapılar kemikleşir ve ayrı kemikler birbirine kaynaşır; kafatası bu sürecin en belirgin örneğidir.' },
  { q: 'Kalp nakli olmadan kalbin kendi başına çalışabilmesinin sebebi nedir?', a: ['Kan gücüyle çalışır', 'Sinüs düğümü adlı doğal "pacemaker"; beyin sinyali olmadan elektrik üretir', 'Kas gücüyle çalışır', 'Akciğerden güç alır'], c: 1, d: 3, vb: true, e: 'Kalp, kendi elektrik sistemini (sinüs düğümü) içerir. Bu nedenle bir kalp beyin sinyalinden bağımsız olarak vücuttan çıkarıldığında bile kısa süre atmaya devam edebilir — nakil cerrahisinde bu özellik kullanılır.' },
  { q: 'DNA\'nın tüm uzunluğu açılsaydı ne kadar olurdu?', a: ['1 metre', '10 metre', 'Güneş\'e kadar ve geri uzanacak ~170 milyar km', '100 km'], c: 2, d: 3, vb: true, e: 'Tek bir insan hücresindeki DNA yaklaşık 2 metre uzunluğundadır. Vücuttaki tüm hücrelerin DNA\'sı uç uca eklenseydi bu uzunluk Dünya\'dan Güneş\'e ve geri, yaklaşık 300 kez gidip gelmeye eşdeğer olurdu.' },
];

export default questions;
